local cloneref = cloneref or function(instance)
	return instance
end

local Players = cloneref(game:GetService("Players"))
local Lighting = cloneref(game:GetService("Lighting"))
local RunService = cloneref(game:GetService("RunService"))
local TeleportService = cloneref(game:GetService("TeleportService"))
local HttpService = cloneref(game:GetService("HttpService"))
local UserInputService = cloneref(game:GetService("UserInputService"))
local TweenService = cloneref(game:GetService("TweenService"))
local SoundService = cloneref(game:GetService("SoundService"))

local LocalPlayer = Players.LocalPlayer

-- Wait for game to fully load so the game's own modules (PlayerScripts,
-- ReplicatedStorage) finish initializing before we touch anything.
if not game:IsLoaded() then
	game.Loaded:Wait()
end

local PREFIX = "Lin67Hub_"

-- Every connection / instance / restore function the script creates.
-- Cleaned up in one place when the window unloads.
local cleanup = {}
local function track(item)
	table.insert(cleanup, item)
	return item
end

-- Instances this script created, so scans of the game's UI / camera skip them.
local owned = setmetatable({}, { __mode = "k" })
local function own(instance)
	owned[instance] = true
	return instance
end

local function camera()
	return workspace.CurrentCamera
end

-- Where first-person viewmodels live: RIVALS keeps them in
-- Workspace.ViewModels.FirstPerson, other games under the camera.
local function viewmodelFolders()
	local folders = {}
	local root = workspace:FindFirstChild("ViewModels")
	local firstPerson = root and root:FindFirstChild("FirstPerson")
	if firstPerson then
		table.insert(folders, firstPerson)
	end
	if camera() then
		table.insert(folders, camera())
	end
	return folders
end

local function trim(text)
	return (tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

-- Small deterministic hash for cache file names.
local function hashText(text)
	local hash = 5381
	for index = 1, #text do
		hash = (hash * 33 + string.byte(text, index)) % 4294967296
	end
	return string.format("%08x", hash)
end

--== Property snapshots: remember originals so turning a feature off restores them ==--

local function snapshot(instance, properties)
	local saved = {}
	for _, property in properties do
		local ok, value = pcall(function()
			return instance[property]
		end)
		if ok then
			saved[property] = value
		end
	end
	return function()
		for property, value in saved do
			pcall(function()
				instance[property] = value
			end)
		end
	end
end

--== Game modules & method patches ==--

-- require()s LocalPlayer.PlayerScripts.<path...> when it's a ModuleScript.
local function moduleAt(path)
	local node = LocalPlayer:FindFirstChild("PlayerScripts")
	for _, name in path do
		node = node and node:FindFirstChild(name)
	end
	if not (node and node:IsA("ModuleScript")) then
		return nil
	end
	local ok, result = pcall(require, node)
	return ok and type(result) == "table" and result or nil
end

-- class[method] = wrap(original); every patch is undone on unload.
local patches = {}
local function patch(class, method, wrap)
	local original = rawget(class, method)
	if type(original) ~= "function" then
		return false
	end
	local frozen = type(isreadonly) == "function" and isreadonly(class)
	if frozen and type(setreadonly) == "function" then
		setreadonly(class, false)
	end
	local ok = pcall(rawset, class, method, wrap(original))
	if frozen and type(setreadonly) == "function" then
		setreadonly(class, true)
	end
	if ok then
		table.insert(patches, { Class = class, Method = method, Original = original })
	end
	return ok
end
track(function()
	for index = #patches, 1, -1 do
		local entry = patches[index]
		local frozen = type(isreadonly) == "function" and isreadonly(entry.Class)
		if frozen and type(setreadonly) == "function" then
			setreadonly(entry.Class, false)
		end
		pcall(rawset, entry.Class, entry.Method, entry.Original)
		if frozen and type(setreadonly) == "function" then
			setreadonly(entry.Class, true)
		end
	end
	table.clear(patches)
end)

-- Create the config folders on the very first run, so Lin67Hub/configs exists for
-- dropping config files into (and for Load config) before anything is saved.
pcall(function()
	if makefolder and isfolder then
		for _, folder in { "Lin67Hub", "Lin67Hub/configs" } do
			if not isfolder(folder) then
				makefolder(folder)
			end
		end
	end
end)

-- "Silent load" is stored in the autoload config, but configs only apply after the
-- window exists, so read the flag up front: a silent window has no loading screen,
-- starts hidden (RightShift opens it) and pops up nothing.
local silentStart = false
pcall(function()
	local folder = "Lin67Hub"
	local name = isfile(folder .. "/autoload.txt") and readfile(folder .. "/autoload.txt")
	if name and name ~= "" then
		name = string.gsub(name, "%s+$", "")
		local path = folder .. "/configs/" .. name .. ".json"
		if isfile(path) then
			local data = game:GetService("HttpService"):JSONDecode(readfile(path))
			silentStart = type(data) == "table" and data.SilentLoad == true
		end
	end
end)

-- Re-running the script used to stack a second hub (a second ragebot loop firing
-- next to the first). Tear the previous instance down first.
do
	local previous = getgenv().Lin67Window
	if type(previous) == "table" and type(previous.Destroy) == "function" then
		pcall(previous.Destroy, previous)
	end
end

-- The floating open/close button is for phones / tablets: a PC (even one with a touch screen)
-- has the toggle key.
local onPhone
do
	local okPlatform, platform = pcall(function()
		return UserInputService:GetPlatform()
	end)
	if okPlatform and platform then
		onPhone = platform == Enum.Platform.IOS or platform == Enum.Platform.Android
	else
		onPhone = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
	end
end

local Window = MD3:CreateWindow({
	MobileButton = onPhone,
	MinimizeButton = false,
	Title = "Lin67 Hub",
	Subtitle = "RIVALS",
	Icon = "syringe",
	Mode = "Dark",
	ThemeColor = Color3.fromHex("#0FBE94"), -- Vape V4's mint accent
	ToggleKey = Enum.KeyCode.RightShift,
	ConfigFolder = "Lin67Hub",
	SectionsAsSubTabs = true, -- each section is its own sub-category under its tab
	Size = UDim2.fromOffset(940, 620), -- rail holds 11 rows + the MISC band without scrolling
	Silent = silentStart,
})
getgenv().Lin67Window = Window
if Window.Gui then
	own(Window.Gui)
end
print("[Lin67] V2: window created") -- diagnostic

-- Bigger than the library's own fit-to-screen maths: MD3 only ever scales
-- *down* to fit a small viewport, so on a normal screen it leaves the window
-- at 1.0. Cap the scale at UI_BUMP instead and let small screens clamp it
-- the same way (the viewport and resize listeners keep it honest afterwards).
do
	local UI_BUMP = 1.15
	local main, uiScale = Window.Instance, Window._uiScale
	local function bumpScale()
		if not (main and uiScale) then
			return
		end
		local camera = workspace.CurrentCamera
		local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
		local width = math.max(main.Size.X.Offset, 1)
		local height = math.max(main.Size.Y.Offset, 1)
		uiScale.Scale = math.max(math.min(UI_BUMP, (viewport.X - 24) / width, (viewport.Y - 24) / height), 0.4)
	end
	bumpScale()
	local maid = Window._maid
	if maid and maid.GiveTask then
		local camera = workspace.CurrentCamera
		if camera then
			-- colon: Maid:GiveTask reads self._tasks, so a dot call hands the
			-- connection over as self and dies on "_tasks is not a valid member"
			maid:GiveTask(camera:GetPropertyChangedSignal("ViewportSize"):Connect(bumpScale))
		end
		-- Connected after MD3's own viewport handler, so this wins: MD3's
		-- rescale() would otherwise reset the scale back to plain fit.
		maid:GiveTask(main:GetPropertyChangedSignal("Size"):Connect(bumpScale))
	end
end

--== Lin67 skin, part 1/2: chrome (Vape V4) ==--
-- The Vape V4 client's chrome painted over MD3: an opaque near-black shell,
-- the category list moved out of the top strip into a left-hand rail of
-- icon + label rows (with Vape's "MISC" group band above the misc tabs),
-- a search pill floating at the top center of the screen, and the mint
-- accent held back for the active states. No row chevrons, no version chip
-- -- the header is the wordmark and nothing else.
-- MD3's sliding tab pill is dropped -- Vape highlights the row itself -- so
-- _navPill is destroyed and every slide path in MD3 no-ops on it.
-- Part 2 (the palette) runs after the autoload config, so saved colors win.
local function buildLin67Chrome()
	local theme = Window.Theme
	local themer = Window._themer
	local Create = Instance.new
	if not (theme and themer) then
		return
	end

	-- Vape V4's tokens, sampled from its own GUI. (The shell and the idle
	-- row gray live in the palette below -- MD3 binds them to roles.)
	local MINT = Color3.fromHex("#0FBE94") -- the "v4" mint
	local BAND = Color3.fromHex("#141414") -- header / group bands
	local ROW_ON = Color3.fromHex("#242324") -- the active rail row
	local DIM = Color3.fromHex("#595859") -- the group band label
	local RAIL_W, ROW_H = 216, 42 -- ten hub tabs + Settings + the band must fit the rail
	local MISC_GROUP = { Feedback = true, Character = true, Misc = true, Cosmetics = true }

	local main = Window.Instance

	-- Shell: no glow, no accent chrome -- Vape's panel is a flat opaque slab.
	-- main's background (Surface) and its 1px hairline (OutlineVariant) are
	-- themer-bound, so part 2's palette paints the shell.

	-- Header band: the #141414 strip behind Vape's wordmark.
	local topBar = main and main:FindFirstChild("TopBar")
	if topBar then
		topBar.BorderSizePixel = 0
		topBar.BackgroundColor3 = BAND
		topBar.BackgroundTransparency = 0

		-- The version chip (Vape's mint "v4" pill) is gone: the header is
		-- just the wordmark and the search.

		-- font-extrabold for the brand
		if Window._titleLabel then
			Window._titleLabel.Font = Enum.Font.GothamBold
		end

		-- Vape floats its search over the top-center of the screen, out of the
		-- bar entirely: round MD3's box into a full pill, tint the icon mint,
		-- hang the results dropdown under it, and tie both to main.Visible so
		-- the loading screen and RightShift keep them in step.
		local searchBox = topBar:FindFirstChild("TopLeftSearchBox")
		local dropdown = main:FindFirstChild("SearchDropdown")
		local gui = Window.Gui
		if searchBox and gui then
			own(searchBox)
			searchBox.Parent = gui
			searchBox.AnchorPoint = Vector2.new(0.5, 0)
			searchBox.Position = UDim2.new(0.5, 0, 0, 16)
			searchBox.ZIndex = 501
			local boxCorner = searchBox:FindFirstChildOfClass("UICorner")
			if boxCorner then
				boxCorner.CornerRadius = UDim.new(0, 10) -- tight, not a stadium
			end
			-- The window is wider now, so the pill is sized to match it.
			searchBox.Size = UDim2.fromOffset(248, 38)
			local searchInput = searchBox:FindFirstChild("SearchInput")
			if searchInput and searchInput:IsA("TextBox") then
				searchInput.TextSize = 14
			end
			local searchIcon = searchBox:FindFirstChild("SearchIcon")
			if searchIcon then
				themer:Bind(searchIcon, { ImageColor3 = function()
					return MINT
				end })
			end
			if dropdown then
				own(dropdown)
				dropdown.AnchorPoint = Vector2.new(0.5, 0)
				dropdown.Position = UDim2.new(0.5, 0, 0, 62) -- pill bottom (54) + 8
				dropdown.Size = UDim2.new(0, 300, 0, 0)
				dropdown.Parent = gui
				dropdown.ZIndex = 500
			end
			local function syncSearch()
				local shown = main.Visible
				searchBox.Visible = shown
				if not shown and dropdown then
					dropdown.Visible = false
				end
			end
			local maid = Window._maid
			local conn = main:GetPropertyChangedSignal("Visible"):Connect(syncSearch)
			if maid and maid.GiveTask then
				maid:GiveTask(conn)
			end
			syncSearch()
		end
	end

	-- Left rail: Vape's category list runs down the side, so MD3's horizontal
	-- strip becomes a vertical rail of full-width rows (icon + label +
	-- chevron) with the content panel beside it. The sliding pill only ever
	-- marks a horizontal strip -- Vape lights the row itself -- so the pill
	-- is destroyed here and every path that moves it (MD3's _slideToTab and
	-- its canvas listeners, the hub's own pill block below) no-ops on nil.
	local body, pages, navList = Window._body, Window._pages, Window._navList
	if body and pages and navList then
		if Window._navPill then
			Window._navPill:Destroy()
			Window._navPill = nil
		end

		navList.Position = UDim2.new(0, 8, 0, 8)
		navList.Size = UDim2.new(0, RAIL_W, 1, -16)
		navList.CanvasSize = UDim2.new()
		navList.AutomaticCanvasSize = Enum.AutomaticSize.Y
		navList.ScrollingDirection = Enum.ScrollingDirection.Y
		navList.ScrollBarThickness = 0
		navList.BorderSizePixel = 0
		local layout = navList:FindFirstChildOfClass("UIListLayout")
		if layout then
			layout.FillDirection = Enum.FillDirection.Vertical
			layout.HorizontalAlignment = Enum.HorizontalAlignment.Left
			layout.VerticalAlignment = Enum.VerticalAlignment.Top
			layout.Padding = UDim.new(0, 4)
		end
		local navPad = navList:FindFirstChildOfClass("UIPadding")
		if navPad then
			navPad.PaddingLeft = UDim.new(0, 0)
			navPad.PaddingRight = UDim.new(0, 0)
			navPad.PaddingTop = UDim.new(0, 0)
			navPad.PaddingBottom = UDim.new(0, 0)
		end

		-- Content: 8px margin, the rail, a 16px gutter, then the panel.
		pages.Position = UDim2.new(0, 8 + RAIL_W + 16, 0, 6)
		pages.Size = UDim2.new(1, -(8 + RAIL_W + 16 + 8), 1, -12)
	end

	-- The selected row wears a soft #242324 wash and scrolls itself into
	-- view; MD3 repaints the label/icon colors through its own _paint.
	local function paintRows()
		local selected = Window.SelectedTab
		for _, tab in Window.Tabs do
			local button = tab._button
			local hl = button and button:FindFirstChild("VapeRowHL")
			if hl then
				hl.BackgroundTransparency = if tab == selected then 0 else 1
			end
		end
		local btn = selected and selected._button
		if btn and navList then
			local view = navList.AbsoluteSize.Y
			local canvasY = navList.AbsoluteCanvasSize.Y
			local top = btn.Position.Y.Offset
			if view > 0 and canvasY > view then
				local at = navList.CanvasPosition.Y
				if top < at then
					navList.CanvasPosition = Vector2.new(0, math.max(0, top - 4))
				elseif top + ROW_H > at + view then
					navList.CanvasPosition = Vector2.new(0, math.min(canvasY - view, top + ROW_H - view + 4))
				end
			end
		end
	end

	-- Every tab becomes a rail row the moment it is added (the hub adds ten,
	-- MD3 may add its own later); the MISC band drops above the first misc
	-- tab, which gets LayoutOrder tenfold so the band fits between rows.
	local function dressTab(tab)
		local button, icon, label = tab._button, tab._icon, tab._label
		if not button then
			return
		end
		button.Size = UDim2.new(0, RAIL_W, 0, ROW_H)
		button.LayoutOrder = #Window.Tabs * 10
		local rowCorner = button:FindFirstChildOfClass("UICorner")
		if rowCorner then
			rowCorner.CornerRadius = UDim.new(0, 4) -- Vape rows, not pills
		end
		local state = button:FindFirstChild("StateLayer")
		local stateCorner = state and state:FindFirstChildOfClass("UICorner")
		if stateCorner then
			stateCorner.CornerRadius = UDim.new(0, 4)
		end
		-- The rail is text-only now. MD3's icon manager flips Visible back on
		-- once the sprite sheet arrives, so hiding the glyph isn't enough: it
		-- leaves the tree instead (still a GuiObject, so Tab:_paint can keep
		-- coloring it -- it just never renders).
		if icon then
			icon.Visible = false
			icon.Parent = nil
		end
		if label then
			label.Position = UDim2.new(0, 16, 0, 0)
			label.Size = UDim2.new(1, -32, 1, 0)
			label.TextXAlignment = Enum.TextXAlignment.Left
			-- the rail is wider now, so its labels read a size up
			label.TextSize = (tonumber(label.TextSize) or 14) + 2
		end
		if not button:FindFirstChild("VapeRowHL") then
			local hl = Create("Frame") {
				Name = "VapeRowHL",
				BackgroundColor3 = ROW_ON,
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 1,
				Parent = button,
			}
			Create("UICorner") { CornerRadius = UDim.new(0, 4), Parent = hl }
		end
		-- the row chevron (Vape's ">") is dropped: icon + label is enough
		if MISC_GROUP[tab.Title] and navList and not navList:FindFirstChild("VapeMiscBand") then
			local band = Create("Frame") {
				Name = "VapeMiscBand",
				BackgroundColor3 = BAND,
				BorderSizePixel = 0,
				Size = UDim2.new(0, RAIL_W, 0, 30),
				LayoutOrder = button.LayoutOrder - 5,
				ZIndex = 3,
				Parent = navList,
			}
			Create("UIPadding") { PaddingLeft = UDim.new(0, 12), Parent = band }
			Create("TextLabel") {
				Name = "Label",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 1, 0),
				Text = "MISC",
				Font = Enum.Font.GothamBold,
				TextSize = 12,
				TextColor3 = DIM,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 4,
				Parent = band,
			}
		end
	end

	local rawAddTab = Window.AddTab
	Window.AddTab = function(self, ...)
		local tab = rawAddTab(self, ...)
		local ok, err = pcall(dressTab, tab)
		if not ok then
			warn("[Lin67] rail row failed: " .. tostring(err))
		end
		pcall(paintRows)
		return tab
	end

	local rawSelectTab = Window.SelectTab
	Window.SelectTab = function(self, ...)
		local result = rawSelectTab(self, ...)
		pcall(paintRows)
		return result
	end

	-- Toasts: left exactly as the library draws them (the extra hairline
	-- edge is dropped for a cleaner card).
end
do
	local ok, err = pcall(buildLin67Chrome)
	if not ok then
		warn("[Lin67] chrome skin failed: " .. tostring(err))
	else
		print("[Lin67] V2: chrome applied")
	end
end

-- Key settings gear ------------------------------------------------------------------
-- A toggle with a keybind gets a gear button; it opens a small popup with the keybind,
-- "Show in list" and (when the feature has modes) the mode. The keybind, mode and
-- "show in list" are the library's own elements, so their flags and behaviour stay as
-- they were: they are just moved out of the section into a hidden holder, and the key
-- chip itself is shown inside the popup.
do
	local GearUI = {}
	MD3.GearUI = GearUI
	local Create, Switch, Icons = MD3.Create, MD3.Switch, MD3.Icons
	local Typography, Shape = MD3.Typography, MD3.Shape
	local UserInputService = game:GetService("UserInputService")
	local themer = Window._themer
	local current = nil -- the popup that is open: { Frame, Anchor, Close }

	local holder
	local function hide(element)
		if not (element and element.Instance and Window.Gui) then
			return
		end
		if not holder then
			holder = Create("Frame") {
				Name = "KeyGearHolder",
				BackgroundTransparency = 1,
				Size = UDim2.new(),
				Visible = false,
				Parent = Window.Gui,
			}
		end
		element.Instance.Parent = holder
	end

	local function closeCurrent()
		if current then
			local popup = current
			current = nil
			popup.Close()
		end
	end

	if Window.Gui then
		track(UserInputService.InputBegan:Connect(function(input)
			if not current then
				return
			end
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then
				return
			end
			local point = Vector2.new(input.Position.X, input.Position.Y)
			local function inside(gui)
				if not (gui and gui.Parent) then
					return false
				end
				local position, size = gui.AbsolutePosition, gui.AbsoluteSize
				return point.X >= position.X and point.X <= position.X + size.X
					and point.Y >= position.Y and point.Y <= position.Y + size.Y
			end
			-- A press on the gear itself is handled by the gear (it toggles the popup).
			if not inside(current.Frame) and not inside(current.Anchor) then
				closeCurrent()
			end
		end))
		if Window.Instance then
			track(Window.Instance:GetPropertyChangedSignal("Visible"):Connect(function()
				if not Window.Instance.Visible then
					closeCurrent()
				end
			end))
		end
	end

	-- Adds the gear button to a toggle's row, before its switch.
	local function addGearButton(toggle, onClick)
		local frame = toggle.Instance
		local header = frame and frame:FindFirstChild("Header", true)
		local control = header and header:FindFirstChild("Control")
		local textFrame = header and header:FindFirstChild("Text")
		if not (control and textFrame) then
			return nil
		end
		local gear = Create("TextButton") {
			Name = "Gear",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Text = "",
			Size = UDim2.fromOffset(32, 32),
			LayoutOrder = 2,
			Parent = header,
		}
		local icon = Create("TextLabel") {
			Name = "Icon",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(20, 20),
			TextSize = 20,
			Font = Enum.Font.GothamMedium,
			Visible = Icons.CanRender("settings"),
			Parent = gear,
		}
		Icons.Apply(icon, "settings", true)
		themer:Bind(icon, { TextColor3 = "OnSurfaceVariant" })
		control.LayoutOrder = 3
		textFrame.Size = UDim2.new(1, -(52 + 32 + 24), 0, 0)
		gear.Activated:Connect(function()
			onClick(gear)
		end)
		return gear
	end

	-- spec: Section (for the hidden "Show in list" toggle), Toggle, Key (a keybind
	-- element), Modes = { Values, Get, Set } (optional).
	-- Returns false (nothing changed) when this toggle already has a gear.
	local function attachImpl(spec)
		local toggle, key = spec.Toggle, spec.Key
		if not (toggle and key and key.Instance) or toggle._gear then
			return false
		end
		local chip = key.Instance:FindFirstChild("Key", true)
		local header = toggle.Instance and toggle.Instance:FindFirstChild("Header", true)
		if not (chip and header and header:FindFirstChild("Control") and header:FindFirstChild("Text")) then
			return false
		end

		-- "Show in list": takes the keybind in and out of the HUD keybind list.
		local keyFlag = key.Flag or toggle.Flag or "Key"
		local listToggle
		listToggle = spec.Section:AddToggle({
			Title = "Show in list",
			Default = true,
			Flag = keyFlag .. "List",
			Callback = function(show)
				local binds = Window._keybinds
				local index = binds and table.find(binds, key)
				if show and binds and not index then
					table.insert(binds, key)
				elseif not show and index then
					table.remove(binds, index)
				end
				if Window.KeybindsChanged then
					Window.KeybindsChanged:Fire()
				end
			end,
		})

		local frame, modeButtons, listSwitch
		local scale = Window._uiScale

		local function row(parent, order, title)
			local item = Create("Frame") {
				Name = title,
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 40),
				LayoutOrder = order,
				Parent = parent,
			}
			local label = Create("TextLabel") {
				Name = "Title",
				BackgroundTransparency = 1,
				Size = UDim2.new(0, 104, 1, 0),
				Text = title,
				TextXAlignment = Enum.TextXAlignment.Left,
				Parent = item,
			}
			Typography.Apply(label, "BodyLarge")
			themer:Bind(label, { TextColor3 = "OnSurface" })
			local control = Create("Frame") {
				Name = "Control",
				BackgroundTransparency = 1,
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.fromScale(1, 0.5),
				Size = UDim2.new(1, -116, 0, 32),
				Parent = item,
			}
			return item, control
		end

		local function paintModes()
			if not modeButtons then
				return
			end
			local selected = spec.Modes.Get()
			for name, button in modeButtons do
				local on = name == selected
				themer:Bind(button, {
					BackgroundColor3 = on and "PrimaryContainer" or "SecondaryContainer",
					TextColor3 = on and "OnPrimaryContainer" or "OnSecondaryContainer",
				})
			end
		end

		local function build()
			frame = Create("Frame") {
				Name = "KeyGear",
				Visible = false,
				AnchorPoint = Vector2.new(1, 0),
				Size = UDim2.fromOffset(308, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BorderSizePixel = 0,
				ZIndex = 60,
				Parent = Window.Gui,
				[1] = Create("UIPadding") {
					PaddingTop = UDim.new(0, 8),
					PaddingBottom = UDim.new(0, 8),
					PaddingLeft = UDim.new(0, 14),
					PaddingRight = UDim.new(0, 12),
				},
				[2] = Create("UIListLayout") {
					FillDirection = Enum.FillDirection.Vertical,
					SortOrder = Enum.SortOrder.LayoutOrder,
					Padding = UDim.new(0, 4),
				},
				[3] = Create("UIStroke") {
					Thickness = 1,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				},
				[4] = Create("UIScale") { Scale = scale and scale.Scale or 1 },
			}
			Shape.Corner(Shape.Medium, frame)
			themer:Bind(frame, { BackgroundColor3 = "SurfaceContainerHighest" })
			themer:Bind(frame:FindFirstChildOfClass("UIStroke"), { Color = "OutlineVariant" })

			-- Keybind: the library's own key chip, moved in here.
			local _, keyControl = row(frame, 1, "Keybind")
			chip.AnchorPoint = Vector2.new(1, 0.5)
			chip.Position = UDim2.fromScale(1, 0.5)
			chip.Parent = keyControl

			-- Show in list.
			local _, listControl = row(frame, 2, "Show in list")
			listControl.Size = UDim2.new(0, 52, 0, 32)
			listSwitch = Switch.new({ Value = listToggle.Value, Theme = Window.Theme, Parent = listControl })
			listSwitch.Changed:Connect(function(value)
				if listToggle.Value ~= value then
					listToggle:Set(value)
				end
			end)

			-- Mode.
			if spec.Modes then
				local _, modeControl = row(frame, 3, "Mode")
				local strip = Create("Frame") {
					Name = "Modes",
					BackgroundTransparency = 1,
					AnchorPoint = Vector2.new(1, 0.5),
					Position = UDim2.fromScale(1, 0.5),
					Size = UDim2.new(0, 0, 0, 28),
					AutomaticSize = Enum.AutomaticSize.X,
					Parent = modeControl,
					[1] = Create("UIListLayout") {
						FillDirection = Enum.FillDirection.Horizontal,
						SortOrder = Enum.SortOrder.LayoutOrder,
						VerticalAlignment = Enum.VerticalAlignment.Center,
						Padding = UDim.new(0, 4),
					},
				}
				modeButtons = {}
				for order, name in ipairs(spec.Modes.Values) do
					local button = Create("TextButton") {
						Name = name,
						AutoButtonColor = false,
						BorderSizePixel = 0,
						Text = name,
						Size = UDim2.new(0, 0, 0, 28),
						AutomaticSize = Enum.AutomaticSize.X,
						LayoutOrder = order,
						Parent = strip,
						[1] = Create("UIPadding") { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) },
					}
					Shape.Corner(Shape.Full, button)
					Typography.Apply(button, "LabelLarge")
					button.Activated:Connect(function()
						spec.Modes.Set(name)
						paintModes()
					end)
					modeButtons[name] = button
				end
			end
		end

		local gear
		local function close()
			if frame then
				frame.Visible = false
			end
		end
		local function open(button)
			if not frame then
				build()
			end
			if listSwitch then
				listSwitch:SetValue(listToggle.Value == true, true)
			end
			paintModes()
			local position, size = button.AbsolutePosition, button.AbsoluteSize
			frame.Position = UDim2.fromOffset(position.X + size.X, position.Y + size.Y + 4)
			frame.Visible = true
			current = { Frame = frame, Anchor = button, Close = close }
		end

		gear = addGearButton(toggle, function(button)
			if current and current.Frame == frame then
				closeCurrent()
			else
				closeCurrent()
				open(button)
			end
		end)
		if not gear then
			if listToggle.Instance then
				listToggle.Instance:Destroy()
			end
			return false
		end
		toggle._gear = gear
		-- Only now take the elements out of the section: if anything above failed, the
		-- plain key row is still there.
		hide(key)
		hide(listToggle)
		return true
	end

	-- Never lets a problem in the gear break loading the hub: the plain rows stay.
	function GearUI.attach(spec)
		local ok, result = pcall(attachImpl, spec)
		if not ok then
			warn("Lin67 Hub: key gear failed:", result)
			return false
		end
		return result == true
	end

	-- A plain on/off feature whose key can toggle it, hold it on, or be ignored.
	-- cfg: KeyTitle, KeyFlag, ModeFlag. Always = the key does nothing (use the switch).
	function GearUI.press(section, toggle, cfg)
		local mode = "Toggle"
		local keyElement = section:AddKeybind({
			Title = cfg.KeyTitle or "Key",
			Mode = "Hold",
			Flag = cfg.KeyFlag,
			Callback = function(down)
				if mode == "Toggle" then
					if down then
						toggle:Set(not toggle.Value)
					end
				elseif mode == "Hold" then
					toggle:Set(down)
				end
			end,
		})
		local modeElement = section:AddDropdown({
			Title = "Mode",
			Options = { "Always", "Hold", "Toggle" },
			Default = "Toggle",
			Flag = cfg.ModeFlag,
			Callback = function(value)
				mode = value or "Toggle"
			end,
		})
		local attached = GearUI.attach({
			Section = section,
			Toggle = toggle,
			Key = keyElement,
			Modes = {
				Values = { "Always", "Hold", "Toggle" },
				Get = function() return mode end,
				Set = function(value) modeElement:Set(value) end,
			},
		})
		if attached then
			hide(modeElement)
		end
		-- The HUD keybind list shows a key while its feature is on.
		if toggle.Changed and keyElement.SetState then
			toggle.Changed:Connect(function(on)
				keyElement:SetState(on == true)
			end)
			keyElement:SetState(toggle.Value == true)
		end
		return attached
	end

	-- A feature that is only active depending on a key and a mode (Always / Hold /
	-- Toggle). cfg: KeyFlag, KeyTitle, ModeFlag, Modes, DefaultMode, OnMode(mode),
	-- OnActive(active). The key and mode elements keep their flags, so saved configs
	-- (e.g. RageKey / RageActivation) still load.
	function GearUI.gated(section, toggle, cfg)
		local mode = cfg.DefaultMode
		local held, toggled = false, false
		local keyElement
		local function push()
			local active = mode == "Always" or (mode == "Hold" and held) or (mode == "Toggle" and toggled)
			cfg.OnActive(active == true)
			if keyElement and keyElement.SetState then
				keyElement:SetState(active == true)
			end
		end
		keyElement = section:AddKeybind({
			Title = cfg.KeyTitle or "Key",
			Mode = "Hold",
			Flag = cfg.KeyFlag,
			Callback = function(down)
				held = down
				if mode == "Toggle" and down then
					toggled = not toggled
				end
				push()
			end,
		})
		local modeElement = section:AddDropdown({
			Title = "Mode",
			Options = cfg.Modes,
			Default = cfg.DefaultMode,
			Flag = cfg.ModeFlag,
			Callback = function(value)
				mode = value or cfg.DefaultMode
				held, toggled = false, false
				if cfg.OnMode then
					cfg.OnMode(mode)
				end
				push()
			end,
		})
		if cfg.OnMode then
			cfg.OnMode(mode)
		end
		push()
		local attached = GearUI.attach({
			Section = section,
			Toggle = toggle,
			Key = keyElement,
			Modes = {
				Values = cfg.Modes,
				Get = function() return mode end,
				Set = function(value) modeElement:Set(value) end,
			},
		})
		if attached then
			hide(modeElement)
		end
		return attached
	end
end


