-- Ambience ----------------------------------------------------------------

local Ambience = VisualsTab:AddSection("Ambience")
local ambience = {
	Enabled = false,
	Ambient = Color3.fromRGB(140, 140, 160),
	OutdoorAmbient = Color3.fromRGB(140, 140, 160),
	Brightness = 2,
	ClockTime = 14,
	Exposure = 0,
	Shadows = true,
}
local restoreLighting = nil
local applyingAmbience = false

local function setIfChanged(instance, property, value)
	if instance[property] ~= value then
		instance[property] = value
	end
end

local function applyAmbience()
	if not ambience.Enabled or applyingAmbience then
		return
	end
	applyingAmbience = true
	setIfChanged(Lighting, "Ambient", ambience.Ambient)
	setIfChanged(Lighting, "OutdoorAmbient", ambience.OutdoorAmbient)
	setIfChanged(Lighting, "Brightness", ambience.Brightness)
	setIfChanged(Lighting, "ClockTime", ambience.ClockTime)
	setIfChanged(Lighting, "ExposureCompensation", ambience.Exposure)
	setIfChanged(Lighting, "GlobalShadows", ambience.Shadows)
	applyingAmbience = false
end

Ambience:AddToggle({
	Title = "Custom ambience",
	Description = "Override the map's lighting",
	Default = false,
	Flag = "Ambience",
	Callback = function(on)
		ambience.Enabled = on
		if on then
			restoreLighting = restoreLighting or snapshot(Lighting, {
				"Ambient", "OutdoorAmbient", "Brightness", "ClockTime", "ExposureCompensation", "GlobalShadows",
			})
			applyAmbience()
		elseif restoreLighting then
			restoreLighting()
			restoreLighting = nil
		end
	end,
})
Ambience:AddColorPicker({
	Title = "Ambient",
