	{ Title = "Contrast", Property = "Contrast", Min = -1, Max = 1, Step = 0.01, Default = 0.1 },
	{ Title = "Saturation", Property = "Saturation", Min = -1, Max = 1, Step = 0.01, Default = 0.15 },
