	local bar, stroke = newBar()
	bars[index] = { Frame = bar, Stroke = stroke }
end

local function layoutCrosshair()
	crosshairGui.Enabled = crosshair.Enabled
	local length, gap, thickness = crosshair.Length, crosshair.Gap, crosshair.Thickness
	local offset = gap + length / 2
	local layout = {
		{ UDim2.fromOffset(0, -offset), UDim2.fromOffset(thickness, length) },
		{ UDim2.fromOffset(0, offset), UDim2.fromOffset(thickness, length) },
		{ UDim2.fromOffset(-offset, 0), UDim2.fromOffset(length, thickness) },
		{ UDim2.fromOffset(offset, 0), UDim2.fromOffset(length, thickness) },
		{ UDim2.fromOffset(0, 0), UDim2.fromOffset(thickness, thickness) },
	}
	for index, bar in bars do
		bar.Frame.Position = layout[index][1]
		bar.Frame.Size = layout[index][2]
		bar.Frame.BackgroundColor3 = crosshair.Color
		bar.Frame.BackgroundTransparency = crosshair.Transparency
		bar.Frame.Visible = index < 5 or crosshair.Dot
		bar.Stroke.Enabled = crosshair.Outline
		bar.Stroke.Transparency = crosshair.Transparency
	end
end

