		if not table.find(SOUND_NAMES, name) then
			table.insert(extra, name)
		end
	end
	table.sort(extra)
	table.move(extra, 1, #extra, #SOUND_NAMES + 1, SOUND_NAMES)
	table.insert(SOUND_NAMES, "Custom")
end

local soundCache = {}

-- Asset id, rbxassetid://, an .mp3/.ogg/.wav URL or a file in the workspace.
local function resolveSound(source)
	source = trim(source)
	if source == "" then
		return nil
	end
	if soundCache[source] ~= nil then
		return soundCache[source] or nil
	end
	local result = nil
	if source:match("^%d+$") then
		result = "rbxassetid://" .. source
	elseif source:match("^rbxasset") then
		result = source
	elseif source:match("^https?://") then
		local data = MD3.Env.HttpGet(source)
		if data and #data > 0 and not data:match("^%s*<") then
			local extension = source:lower():gsub("[?#].*$", ""):match("%.(%a+)$")
			if extension ~= "ogg" and extension ~= "wav" then
				extension = "mp3"
			end
			MD3.Env.MakeFolder("Lin67Hub/sounds")
			local path = ("Lin67Hub/sounds/%s.%s"):format(hashText(source), extension)
			if MD3.Env.WriteFile(path, data) then
				result = MD3.Env.GetCustomAsset(path)
			end
		end
	elseif MD3.Env.IsFile(source) then
		result = MD3.Env.GetCustomAsset(source)
	end
	soundCache[source] = result or false
	return result
end

local soundHolder = Instance.new("Folder")
soundHolder.Name = MD3.Env.RandomName()
soundHolder.Parent = SoundService
track(own(soundHolder))

local function playFeedbackSound(settings)
	local source = if settings.Sound == "Custom" then settings.CustomSound else SOUND_PRESETS[settings.Sound]
	local id = resolveSound(source)
	if not id then
		return
	end
	local sound = Instance.new("Sound")
	sound.SoundId = id
	sound.Volume = settings.Volume
	sound.PlaybackSpeed = settings.Pitch
	sound.Parent = soundHolder
	sound:Play()
	sound.Ended:Once(function()
		sound:Destroy()
	end)
	task.delay(10, function()
		sound:Destroy()
	end)
end

