-- Hitmarker: four short diagonal bars around the screen center.
local hitmarker = Instance.new("Frame")
hitmarker.BackgroundTransparency = 1
hitmarker.AnchorPoint = Vector2.new(0.5, 0.5)
hitmarker.Position = UDim2.fromScale(0.5, 0.5)
hitmarker.Size = UDim2.fromOffset(0, 0)
hitmarker.Parent = feedbackGui
local hitmarkerBars = {}
for index = 1, 4 do
	local bar = Instance.new("Frame")
	bar.AnchorPoint = Vector2.new(0.5, 0.5)
	bar.BorderSizePixel = 0
	bar.BackgroundTransparency = 1
	bar.Rotation = 45 + (index - 1) * 90
	bar.Parent = hitmarker
	hitmarkerBars[index] = bar
end

local killFlash = Instance.new("Frame")
killFlash.BorderSizePixel = 0
killFlash.Size = UDim2.fromScale(1, 1)
killFlash.BackgroundTransparency = 1
killFlash.Parent = feedbackGui

local hitSettings = {
	Enabled = false, Sound = "Ping", CustomSound = "", Volume = 1, Pitch = 1,
	Marker = true, MarkerColor = Color3.new(1, 1, 1), MarkerSize = 10, MarkerDuration = 0.3,
}
local killSettings = {
	Enabled = false, Sound = "Slash", CustomSound = "", Volume = 1.5, Pitch = 1,
	Flash = true, FlashColor = Color3.fromRGB(255, 60, 60), FlashDuration = 0.4, Notify = true,
}

-- UI flags written by patch threads (game identity) and read by Heartbeat
-- (executor identity), which is the only context that can safely touch
-- ProtectGui-d Instance properties.
local _pendingHitmarker = false
local _pendingKillFlash = false
local _pendingKillPlayer = nil

local markerTweens = {}
local function showHitmarker()
	local size = hitSettings.MarkerSize
	local distance = size * 0.9
	for _, tween in markerTweens do
		tween:Cancel()
	end
	table.clear(markerTweens)
	for index, bar in hitmarkerBars do
		local angle = math.rad(bar.Rotation - 90)
		bar.Position = UDim2.fromOffset(math.cos(angle) * distance, math.sin(angle) * distance)
		bar.Size = UDim2.fromOffset(2, size)
		bar.BackgroundColor3 = hitSettings.MarkerColor
		bar.BackgroundTransparency = 0
		local tween = TweenService:Create(bar, TweenInfo.new(hitSettings.MarkerDuration), { BackgroundTransparency = 1 })
		markerTweens[index] = tween
		tween:Play()
	end
end

local flashTween = nil
local function showKillFlash()
	if flashTween then
		flashTween:Cancel()
	end
	killFlash.BackgroundColor3 = killSettings.FlashColor
	killFlash.BackgroundTransparency = 0.6
	flashTween = TweenService:Create(killFlash, TweenInfo.new(killSettings.FlashDuration), { BackgroundTransparency = 1 })
	flashTween:Play()
end

-- Heartbeat runs in the executor's main thread — has the right capability to
-- touch ProtectGui instances (patch-spawned threads do not).
track(RunService.Heartbeat:Connect(function()
	if _pendingHitmarker then
		_pendingHitmarker = false
		pcall(showHitmarker)
	end
	if _pendingKillFlash then
		local p = _pendingKillPlayer
		_pendingKillFlash = false
		_pendingKillPlayer = nil
		pcall(showKillFlash)
		if killSettings.Notify and p then
			pcall(function()
				Window:Notify({ Title = "Eliminated", Content = p.DisplayName, Icon = "star", Duration = 2 })
			end)
		end
	end
end))

local function onHit()
	if not hitSettings.Enabled then
		return
	end
	pcall(playFeedbackSound, hitSettings)
	if hitSettings.Marker then
		_pendingHitmarker = true
	end
end

local function onKill(player)
	if not killSettings.Enabled then
		return
	end
	pcall(playFeedbackSound, killSettings)
	if killSettings.Flash or killSettings.Notify then
		_pendingKillFlash = killSettings.Flash or false
		_pendingKillPlayer = player
	end
end

-- Detection hooks the game's own feedback (character models in a match
-- aren't player.Character, so watching Humanoids misses them):
--  * Hit: ItemInterface:DamageEffect(info, ...) is what draws the game's
--    hitmarker when a hit of yours lands; info["\0"] is the damage dealt.
--  * Kill: DuelInterface.EliminationFeed:Play(victim, eliminator, assister, ...)
--    adds a line to the kill feed.
-- Both are looked up by path, since UserInterface holds GUIs with the same names.
-- The same retry loop installs the Removables hooks further down.
local removables = {
	NoScopeOverlay = false,
	NoADSVignette = false,
	NoBurnEffect = false,
	NoScopeReticle = false,
	NoHitmarker = false,
}

do
	local HIT_INTERVAL = 0.05 -- shotgun pellets land together; one sound per volley
	local lastHit = -math.huge
	local ITEM_INTERFACE = { "Modules", "ClientReplicatedClasses", "ClientFighter", "ClientItem", "ItemInterface" }
	local SCOPE = { "Modules", "ClientReplicatedClasses", "ClientFighter", "ClientItem", "ItemInterface", "Mouse", "Scope" }

	local function isLocalItem(itemInterface)
		local ok, isLocal = pcall(function()
			return itemInterface.ClientItem.ClientFighter.IsLocalPlayer
		end)
		return not ok or isLocal ~= false
	end

	local function hookHits()
		local class = moduleAt(ITEM_INTERFACE)
		return class ~= nil and patch(class, "DamageEffect", function(original)
			return function(self, info, ...)
				local dealt = type(info) == "table" and rawget(info, utf8.char(0))
				if hitSettings.Enabled and dealt ~= 0 and isLocalItem(self) then
					local now = os.clock()
					if now - lastHit >= HIT_INTERVAL then
						lastHit = now
						pcall(onHit)
					end
				end
				return original(self, info, ...)
			end
		end)
	end

	local function hookKills()
		local class = moduleAt({ "Modules", "ClientReplicatedClasses", "ClientDuel", "DuelInterface", "EliminationFeed" })
		return class ~= nil and patch(class, "Play", function(original)
			return function(self, victim, eliminator, ...)
				if killSettings.Enabled and eliminator == LocalPlayer and victim ~= LocalPlayer
					and typeof(victim) == "Instance" and victim:IsA("Player")
				then
					pcall(onKill, victim)
				end
				return original(self, victim, eliminator, ...)
			end
		end)
	end

	local function hookScope()
		local class = moduleAt(SCOPE)
		return class ~= nil and patch(class, "SetActive", function(original)
			return function(self, active, ...)
				if removables.NoScopeOverlay and active then
					self._is_scope_active = active
					if self.ActiveChanged then
						self.ActiveChanged:Fire()
					end
					return
				end
				return original(self, active, ...)
			end
		end)
	end

	local function hookScopeReticle()
		local class = moduleAt(SCOPE)
		return class ~= nil and patch(class, "Update", function(original)
			return function(self, ...)
				local result = table.pack(original(self, ...))
				if removables.NoScopeReticle then
					pcall(function()
						if self.ReticleFrame then
							self.ReticleFrame.Visible = false
						end
					end)
				end
				return table.unpack(result, 1, result.n)
			end
		end)
	end

	local function hookVignette()
		local class = moduleAt(ITEM_INTERFACE)
		return class ~= nil and patch(class, "Update", function(original)
			return function(self, ...)
				local result = table.pack(original(self, ...))
				if removables.NoADSVignette then
					pcall(function()
						local vignette = self.Frame:FindFirstChild("AimingVignette")
						if vignette then
							vignette.Visible = false
						end
					end)
				end
				return table.unpack(result, 1, result.n)
			end
		end)
	end

	local function hookBurn()
		local class = moduleAt({ "Modules", "ClientReplicatedClasses", "ClientEntity" })
		return class ~= nil and patch(class, "ReplicateFromServer", function(original)
			return function(self, replicationType, ...)
				if removables.NoBurnEffect and replicationType == "BurnEffect" then
					return
				end
				return original(self, replicationType, ...)
			end
		end)
	end

	local function hookGameHitmarker()
		local class = moduleAt({ "Modules", "ClientReplicatedClasses", "ClientFighter", "ClientItem", "ItemInterface", "Mouse", "MouseCrosshair" })
		return class ~= nil and patch(class, "DamageEffect", function(original)
			return function(self, info, ...)
				if removables.NoHitmarker then
					return
				end
				return original(self, info, ...)
			end
		end)
	end

	-- The game's modules may still be loading when Lin67 Hub starts.
	local hooks = {
		Hits = hookHits, Kills = hookKills, Scope = hookScope, ScopeReticle = hookScopeReticle,
		Vignette = hookVignette, Burn = hookBurn, GameHitmarker = hookGameHitmarker,
	}
	task.spawn(function()
		for _ = 1, 60 do
			for name, hook in hooks do
				if hook() then
					hooks[name] = nil
				end
			end
			if next(hooks) == nil then
				return
			end
			task.wait(1)
		end
	end)
end

