-- Auto execute ----------------------------------------------------------------

local AutoExecute = MiscTab:AddSection("Auto Execute")
local queueOnTeleport = queue_on_teleport
	or queueonteleport
	or (syn and syn.queue_on_teleport)
	or (fluxus and fluxus.queue_on_teleport)
-- The queued loader is added once, as soon as the toggle is on (the game
-- teleports you into matches itself, which doesn't always fire OnTeleport).
-- It reads the URL from a file when it runs, so turning the toggle off or
-- changing the URL later still counts even though the queue can't be undone.
local AUTOEXEC_FILE = "Lin67Hub/autoexecute.txt"
local AUTOEXEC_LOADER = [[
-- Only one copy may run per server: the loader gets queued once per hub load, so several
-- queued copies can fire together after a teleport. The first one claims this server.
local _env = (getgenv and getgenv()) or _G
local _job = tostring(game.JobId)
if _job ~= "" and _env.__LYAutoExecJob == _job then return end
_env.__LYAutoExecJob = _job

-- Waits until the game is really done loading, not just joined: DataModel, character,
-- the game's own controllers + main UI, the player's data, and no pending asset loads.
-- Each wait has a timeout so a broken join can't block the queue forever.
local function waitFor(cond, timeout)
	local t0 = tick()
	while not cond() and tick() - t0 < timeout do
		task.wait(0.25)
	end
	return cond()
end

-- 1. DataModel.
if not game:IsLoaded() then game.Loaded:Wait() end

local _lp = game:GetService("Players").LocalPlayer
if not _lp then
	repeat task.wait() _lp = game:GetService("Players").LocalPlayer until _lp
end

-- 2. Character with a live Humanoid and root part.
waitFor(function()
	local c = _lp.Character
	return c and c:FindFirstChildOfClass("Humanoid") and c:FindFirstChild("HumanoidRootPart")
end, 60)

-- 3. Server session: Remotes replicated.
local _rs = game:GetService("ReplicatedStorage")
waitFor(function() return _rs:FindFirstChild("Remotes") end, 30)

-- 4. The game's client: controllers started, main UI built, player data received.
waitFor(function()
	local scripts = _lp:FindFirstChild("PlayerScripts")
	local controllers = scripts and scripts:FindFirstChild("Controllers")
	local gui = _lp:FindFirstChild("PlayerGui")
	return controllers
		and controllers:FindFirstChild("FighterController")
		and controllers:FindFirstChild("MechanicsController")
		and gui and gui:FindFirstChild("MainGui")
		and _lp:GetAttribute("Level") ~= nil
end, 45)

-- 5. The game's own scripts have really run: their controller modules are loaded
--    (via getloadedmodules where the executor has it).
waitFor(function()
	if type(getloadedmodules) ~= "function" then return true end
	local ok, list = pcall(getloadedmodules)
	if not ok or type(list) ~= "table" then return true end
	local found = { FighterController = false, MechanicsController = false, MiscellaneousController = false, PreloadController = false }
	for _, module in ipairs(list) do
		if found[module.Name] == false then found[module.Name] = true end
	end
	for _, present in pairs(found) do
		if not present then return false end
	end
	return true
end, 45)

-- 6. No assets still being fetched (loading screen / preload), steady for 1.5 s.
local _cp = game:GetService("ContentProvider")
local _quiet = 0
local _t0 = tick()
while _quiet < 6 and tick() - _t0 < 40 do
	if _cp.RequestQueueSize == 0 then _quiet += 1 else _quiet = 0 end
	task.wait(0.25)
end

-- 7. Let the game's own loading screen finish and the first frames settle.
task.wait(2)

local ok, url = pcall(readfile, %q)
url = ok and type(url) == "string" and url:match("^%%s*(.-)%%s*$") or ""
if url ~= "" then loadstring(game:HttpGet(url))() end
]]
local AUTOEXEC_URL = "https://raw.githubusercontent.com/www067/lin67/main/LIN6767V7.lua"
local AUTOEXEC_LEGACY = "https://lua.lystore.lol/O5BmHqMr1QPdpZXWf2vLEDKSdrclP6f7/loader.luau"
-- The toggle's real state is the file it feeds (the queued loader reads it after the teleport,
-- so the switch and the file can't drift). Read that file back on boot: an old LY URL parked
-- there by an earlier build -- or a GitHub blob/older-version URL, which returns HTML rather
-- than lua -- is rewritten to this hub's raw copy before anything can queue it. Any other URL
-- (one you typed yourself) is left alone.
local parked = nil
do
	if MD3.Env.IsFile(AUTOEXEC_FILE) then
		local held = MD3.Env.ReadFile(AUTOEXEC_FILE)
		if type(held) == "string" then
			held = held:match("^%s*(.-)%s*$") or held
			if held == AUTOEXEC_LEGACY or held:find("www067/lin67", 1, true) then
				held = AUTOEXEC_URL
				MD3.Env.WriteFile(AUTOEXEC_FILE, held)
			end
			if held ~= "" then
				parked = held
			end
		end
	end
end

local autoExecute = {
	Enabled = parked ~= nil,
	Url = parked or AUTOEXEC_URL,
	Queued = false,
}

local function syncAutoExecute()
	local url = autoExecute.Enabled and trim(tostring(autoExecute.Url)) or ""
	MD3.Env.MakeFolder("Lin67Hub")
	if not MD3.Env.WriteFile(AUTOEXEC_FILE, url) then
		return false
	end
	if url ~= "" and not autoExecute.Queued then
		-- A hub instance that was itself started by the queue (or reloaded in the same server)
		-- has already queued once for this teleport: don't stack another copy.
		local env = getgenv and getgenv() or _G
		local job = tostring(game.JobId)
		if job ~= "" and env.__LYAutoExecQueuedFor == job then
			autoExecute.Queued = true
		else
			autoExecute.Queued = pcall(queueOnTeleport, AUTOEXEC_LOADER:format(AUTOEXEC_FILE))
			if autoExecute.Queued then env.__LYAutoExecQueuedFor = job end
		end
	end
	return true
end

if type(queueOnTeleport) == "function" then
	local autoExecuteToggle
	autoExecuteToggle = AutoExecute:AddToggle({
		Title = "Re-run after teleport",
		Description = "Loads Lin67 Hub again in the next server (Rejoin, Server hop, joining a match)",
		Default = autoExecute.Enabled,
		Flag = "AutoExecute",
		Callback = function(on)
			autoExecute.Enabled = on
			if not syncAutoExecute() and on then
				Window:Notify({ Title = "Auto Execute", Content = "Your executor can't write files", Icon = "error" })
				task.defer(function()
					autoExecuteToggle:Set(false, true)
				end)
			end
		end,
	})
	-- A queue only lasts one teleport; queue again for the next one.
	track(LocalPlayer.OnTeleport:Connect(function(state)
		if state == Enum.TeleportState.Failed then
			return
		end
		if state == Enum.TeleportState.Started and autoExecute.Enabled and not autoExecute.Queued then
			syncAutoExecute()
		end
	end))
else
	AutoExecute:AddParagraph({
		Title = "Not supported",
		Content = "Your executor has no queue_on_teleport.",
	})
end

-- Interface: streamer mode & hide HUD ------------------------------------------------

local InterfaceSection = MiscTab:AddSection("Interface")
local StarterGui = cloneref(game:GetService("StarterGui"))
local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")

-- Hide HUD: turns off the game's ScreenGuis and Roblox's core UI (not Lin67 Hub).
local hiddenGuis = nil
local coreGuiStates = nil

local function setHudHidden(on)
	if on and not hiddenGuis then
		hiddenGuis = {}
		for _, gui in PlayerGui:GetChildren() do
			if gui:IsA("ScreenGui") and gui.Enabled and not owned[gui] then
				gui.Enabled = false
				table.insert(hiddenGuis, gui)
			end
		end
		coreGuiStates = {}
		for _, coreType in Enum.CoreGuiType:GetEnumItems() do
			if coreType ~= Enum.CoreGuiType.All then
				local ok, enabled = pcall(StarterGui.GetCoreGuiEnabled, StarterGui, coreType)
				if ok then
					coreGuiStates[coreType] = enabled
				end
			end
		end
		pcall(StarterGui.SetCoreGuiEnabled, StarterGui, Enum.CoreGuiType.All, false)
	elseif not on and hiddenGuis then
		for _, gui in hiddenGuis do
			pcall(function()
				gui.Enabled = true
			end)
		end
		hiddenGuis = nil
		for coreType, enabled in coreGuiStates do
			pcall(StarterGui.SetCoreGuiEnabled, StarterGui, coreType, enabled)
		end
		coreGuiStates = nil
	end
end

local hideHudToggle = InterfaceSection:AddToggle({
	Title = "Hide HUD",
	Description = "Hide the game's UI for clean screenshots / clips",
	Default = false,
	Flag = "HideHUD",
	Callback = setHudHidden,
})
MD3.GearUI.press(InterfaceSection, hideHudToggle, { KeyTitle = "Toggle HUD", KeyFlag = "HideHUDKey", ModeFlag = "HideHUDMode" })
-- Game UI that gets re-created (e.g. on respawn) stays hidden too.
track(PlayerGui.ChildAdded:Connect(function(gui)
	if hiddenGuis and gui:IsA("ScreenGui") and not owned[gui] then
		task.defer(function()
			if hiddenGuis and gui.Enabled then
				gui.Enabled = false
				table.insert(hiddenGuis, gui)
			end
		end)
	end
end))
track(function()
	setHudHidden(false)
end)

-- Auto respawn ------------------------------------------------------------------
-- RIVALS lets you skip the death screen through a "respawn now" remote in
-- ReplicatedStorage.Remotes. After you die, fire it (a few tries) once the
-- delay has passed.

local MatchSection = MiscTab:AddSection("Match")
local ReplicatedStorage = cloneref(game:GetService("ReplicatedStorage"))
local autoRespawn = { Enabled = false, Warned = false, Generation = 0 }

local function findRespawnRemote()
	local remotes = ReplicatedStorage:FindFirstChild("Remotes")
	if not remotes then
		return nil
	end
	for _, child in remotes:GetDescendants() do
		if child:IsA("RemoteEvent") and child.Name:lower():find("respawn") then
			return child
		end
	end
	return nil
end

-- Try to click a button via whichever method the executor supports.
local function fireButton(button)
	if type(fireclick) == "function" then
		pcall(fireclick, button)
		return
	end
	-- Signal:Fire() works on some executors.
	pcall(function()
		button.MouseButton1Click:Fire()
	end)
	-- getconnections fallback: call each handler directly.
	if type(getconnections) == "function" then
		local ok, conns = pcall(getconnections, button.MouseButton1Click)
		if ok and conns then
			for _, conn in conns do
				if type(conn.Function) == "function" then
					pcall(conn.Function)
				end
			end
		end
	end
end

-- Walk a GUI tree looking for a visible "respawn now"-style button.
-- Returns the first match, or nil.
local RESPAWN_TEXTS = { "respawn", "skip" }
local function findRespawnButton(root)
	local candidates = {}
	for _, descendant in root:GetDescendants() do
		if (descendant:IsA("TextButton") or descendant:IsA("ImageButton"))
			and descendant.Visible
			and descendant.Active
			and not owned[descendant]
		then
			local text = ""
			pcall(function()
				text = tostring(descendant.Text):lower()
			end)
			for _, keyword in RESPAWN_TEXTS do
				if text:find(keyword) then
					return descendant
				end
			end
			table.insert(candidates, descendant)
		end
	end
	-- 若畫面上只有一顆可點按鈕（文字可能被混淆），直接點它
	if #candidates == 1 then
		return candidates[1]
	end
	return nil
end

local function onDied()
	if not autoRespawn.Enabled then
		return
	end
	autoRespawn.Generation += 1
	local generation = autoRespawn.Generation
	local diedCharacter = LocalPlayer.Character

	task.spawn(function()
		if not autoRespawn.Enabled or generation ~= autoRespawn.Generation then
			return
		end
		if LocalPlayer.Character ~= diedCharacter then
			return -- already respawned without our help
		end

		-- Strategy 1: fire the respawn remote directly (works when the name is readable).
		local remote = findRespawnRemote()
		if remote then
			for _ = 1, 5 do
				if LocalPlayer.Character ~= diedCharacter or not autoRespawn.Enabled then
					return
				end
				pcall(remote.FireServer, remote)
				task.wait(0.1)
			end
			return
		end

		-- Strategy 2: simulate a click on the death-screen "Respawn Now" button.
		-- RIVALS shows a death screen GUI in PlayerGui; scan it for the button.
		local function tryScreens()
			for _, gui in PlayerGui:GetChildren() do
				if gui:IsA("ScreenGui") and gui.Enabled and not owned[gui] then
					local button = findRespawnButton(gui)
					if button then
						fireButton(button)
						return true
					end
				end
			end
			return false
		end

		if tryScreens() then
			return
		end

		-- Screen may not have appeared yet — watch for it.
		local watchConn
		local function cleanup()
			if watchConn then
				watchConn:Disconnect()
				watchConn = nil
			end
		end
		watchConn = PlayerGui.ChildAdded:Connect(function(child)
			if not autoRespawn.Enabled or generation ~= autoRespawn.Generation then
				cleanup()
				return
			end
			if child:IsA("ScreenGui") then
				task.defer(function()
					if tryScreens() then
						cleanup()
					end
				end)
			end
		end)
		-- Give up after 8 s to avoid leaking the connection.
		task.delay(8, cleanup)
	end)
end

local diedConnection = nil
local function watchOwnHumanoid(character)
	if diedConnection then
		diedConnection:Disconnect()
		diedConnection = nil
	end
	local humanoid = character and (character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 10))
	if humanoid and LocalPlayer.Character == character then
		diedConnection = humanoid.Died:Connect(onDied)
	end
end
if LocalPlayer.Character then
	task.spawn(watchOwnHumanoid, LocalPlayer.Character)
end
track(LocalPlayer.CharacterAdded:Connect(watchOwnHumanoid))
track(function()
	autoRespawn.Enabled = false
	if diedConnection then
		diedConnection:Disconnect()
	end
end)

MatchSection:AddToggle({
	Title = "Auto respawn",
	Description = "Skip the death screen and respawn right away",
	Default = false,
	Flag = "AutoRespawn",
	Callback = function(on)
		autoRespawn.Enabled = on
		autoRespawn.Warned = false
	end,
})

-- Movement recorder -------------------------------------------------------------
-- Records your own path and replays it as a local ghost of your character
-- (only you see it; your real character is never moved). Recordings can be
-- saved to / loaded from Lin67Hub/recordings.

-- Cosmetics -------------------------------------------------------------------
-- Client-side only, following LY-broken's cosmetics unlocker:
--  * Unlock All wraps PlayerDataController.CurrentData.Data so its
--    CosmeticInventory field lists every cosmetic; the menus then show them
--    all as owned.
--  * Skins picked below are laid over your weapon data
--    (PlayerDataController:GetWeaponData, used by the lobby and menus) and over
--    the replicated data a ClientItem is built from (your guns in a match).
-- Nothing is sent to the server, so other players still see your real skins.

-- A function, not a do-block, so its locals don't count toward the main
-- chunk's 200-local limit.
local function setupCosmetics()
	local COSMETICS_FOLDER = "Lin67Hub"
	local COSMETICS_FILE = COSMETICS_FOLDER .. "/cosmetics.json"
	local SLOTS = { "Skin", "Wrap", "Charm", "Finisher" }
	local NONE = "None"

	local function writeField(tbl, key, value)
		local frozen = type(isreadonly) == "function" and isreadonly(tbl)
		if frozen and type(setreadonly) == "function" then
			setreadonly(tbl, false)
		end
		local ok = pcall(rawset, tbl, key, value)
		if frozen and type(setreadonly) == "function" then
			setreadonly(tbl, true)
		end
		return ok
	end

	local moduleCache = {}
	local function requireModule(name)
		if moduleCache[name] ~= nil then
			return moduleCache[name]
		end
		local roots = { LocalPlayer:FindFirstChild("PlayerScripts"), ReplicatedStorage }
		for _, root in roots do
			-- FindFirstChild returns only the first match, which can be a same-named
			-- non-module (e.g. the CosmeticViewportFrame UI template), so scan for a module.
			local module = root and root:FindFirstChild(name, true)
			if root and not (module and module:IsA("ModuleScript")) then
				module = nil
				for _, descendant in root:GetDescendants() do
					if descendant.Name == name and descendant:IsA("ModuleScript") then
						module = descendant
						break
					end
				end
			end
			if module then
				local ok, result = pcall(require, module)
				if ok and result ~= nil then
					moduleCache[name] = result
					return result
				end
			end
		end
		return nil
	end

	-- The game's WrapController asks every WrapGroupObject whether its ancestry is
	-- visible each frame. That walk climbs past our hidden-UI container and throws
	-- "lacking capability Plugin" (~200 logged errors/s, the 250ms hitch every 3s)
	-- for every wrap preview in the Cosmetics tab. Answer for our own GUI ourselves.
	local wrapVisibilityFixed = false
	local function fixWrapVisibility()
		if wrapVisibilityFixed then
			return
		end
		wrapVisibilityFixed = true
		local group = requireModule("WrapGroupObject")
		local original = type(group) == "table" and rawget(group, "_IsAncestryVisible")
		if type(original) ~= "function" then
			return
		end
		-- The controller's thread cannot touch instances under our hidden GUI at all
		-- (even IsDescendantOf throws), so don't inspect them: try the game's check
		-- once, and treat an object it cannot read as inactive (cached, weak).
		local blocked = setmetatable({}, { __mode = "k" })
		local function wrapped(self, ...)
			if blocked[self] then
				return false
			end
			local ok, result = pcall(original, self, ...)
			if ok then
				return result
			end
			blocked[self] = true
			return false
		end
		local frozen = table.isfrozen(group)
		if frozen and type(setreadonly) == "function" then
			setreadonly(group, false)
		end
		pcall(function()
			group._IsAncestryVisible = wrapped
		end)
		if frozen and type(setreadonly) == "function" then
			setreadonly(group, true)
		end
	end

	local function index(value, key)
		local ok, result = pcall(function()
			return value[key]
		end)
		return ok and result or nil
	end

