-- Combat > Gun. Created by the ported features; the weapon tweaks below add to it.
local GunSection = nil

-- A function of its own so its locals don't count against the main chunk's.
local function loadPortedFeatures()
	-- A small Linoria-style front over MD3 sections (Toggles / Options,
	-- groupbox:AddToggle(idx, info), :AddColorPicker, :AddKeyPicker, dependency
	-- boxes), so the ported code keeps its original shape. Every element is saved
	-- under its Linoria index as the MD3 Flag.

	local Toggles, Options = {}, {}
	local connections = {}
	local unloaders = {}
	local guis = setmetatable({}, { __mode = "k" })
	local drawings = setmetatable({}, { __mode = "k" })
	local boxes = {}

	local Port = {
		Unloaded = false,
		GuiParent = MD3.Env.GetGuiParent(),
	}

	Port.Holder = own(Instance.new("Folder"))
	Port.Holder.Name = MD3.Env.RandomName()
	Port.Holder.Parent = Port.GuiParent

	function Port.Track(connection)
		table.insert(connections, connection)
		return connection
	end

	function Port.OnUnload(fn)
		table.insert(unloaders, fn)
	end

	function Port.Gui(gui)
		gui.Name = MD3.Env.RandomName()
		gui.ResetOnSpawn = false
		MD3.Env.ProtectGui(gui)
		gui.Parent = Port.GuiParent
		guis[own(gui)] = true
		return gui
	end

	-- Drawing objects are removed on unload too.
	local drawingNew = Drawing and Drawing.new
	local Drawing = drawingNew and setmetatable({
		new = function(kind)
			local object = drawingNew(kind)
			drawings[object] = true
			return object
		end,
	}, { __index = Drawing }) or nil

	local INSTANCE_GAMEPLAY_OVERLAY_ORDER = 10

	-- Lin67 never hides gameplay overlays while its window is open.
	local function isInstanceMenuOpen()
		return false
	end
	local shouldSuppressGameplayOverlays = isInstanceMenuOpen

	local function instanceSafeRequire(module, timeout)
		local deadline = os.clock() + (timeout or 10)
		local lastError
		repeat
			local ok, result = pcall(require, module)
			if ok then
				return result
			end
			lastError = result
			task.wait(0.1)
		until os.clock() > deadline
		error("Lin67 Hub: couldn't load " .. module:GetFullName() .. " (" .. tostring(lastError) .. ")")
	end

	getgenv().InstanceConfigLoading = false

	local function titleCase(text)
		text = tostring(text or ""):gsub("[:%s]+$", "")
		if text == "enable" or text == "enabled" then
			return "Enabled"
		end
		return (text:gsub("^%l", string.upper))
	end

	local function refreshBoxes()
		for _, box in boxes do
			local visible = box.Parent == nil or box.Parent.Visible
			if visible then
				for _, dependency in box.Dependencies do
					if dependency[1].Value ~= dependency[2] then
						visible = false
						break
					end
				end
			end
			box.Visible = visible
			for _, member in box.Members do
				member:SetVisible(visible)
			end
		end
	end

	local Library = {
		Unloaded = false,
		MainColor = Color3.fromRGB(28, 28, 28),
		BackgroundColor = Color3.fromRGB(20, 20, 20),
		OutlineColor = Color3.fromRGB(50, 50, 50),
		FontColor = Color3.new(1, 1, 1),
		ScreenGui = Port.Gui(Instance.new("ScreenGui")),
	}
	Library.ScreenGui.IgnoreGuiInset = true
	Library.ScreenGui.DisplayOrder = 998

	function Library:Notify(text, duration)
		Window:Notify({ Title = "Lin67 Hub", Content = tostring(text), Icon = "info", Duration = duration })
	end

	function Library:Create(className, props)
		local instance = Instance.new(className)
		for property, value in props do
			if property ~= "Parent" then
				instance[property] = value
			end
		end
		instance.Parent = props.Parent
		return instance
	end

	function Library:CreateLabel(props)
		local label = Library:Create("TextLabel", { BackgroundTransparency = 1 })
		for property, value in props do
			if property ~= "Parent" then
				label[property] = value
			end
		end
		label.Parent = props.Parent
		return label
	end

	function Library:AddToRegistry() end

	function Library:UpdateDependencyBoxes()
		refreshBoxes()
	end

	-- Elements -------------------------------------------------------------------

	local Element = {}
	Element.__index = Element

	function Element:_fire(raw)
		local value = if self._fromMD3 then self._fromMD3(raw) else raw
		self.Value = value
		for _, addon in self.Addons do
			if addon.SyncToggleState then
				addon.Toggled = value == true
				addon._md3:SetState(addon.Toggled)
			end
		end
		-- Color pickers also hand over the end of their gradient as a second value.
		local second = nil
		if self.Type == "ColorPicker" and self._md3 and self._md3.GetColor2 then
			second = self._md3:GetColor2()
		end
		if self._callback then
			self._callback(value, second)
		end
		for _, fn in self._changed do
			local ok, err = pcall(fn, value, second)
			if not ok then
				warn("Lin67 Hub:", err)
			end
		end
		refreshBoxes()
	end

	function Element:SetValue(value)
		self._md3:Set(value)
	end

	function Element:OnChanged(fn)
		table.insert(self._changed, fn)
		fn(self.Value)
	end

	function Element:SetValues(values)
		self.Values = values
		self._md3:SetOptions(values)
	end

	function Element:SetVisible(visible)
		self._md3:SetVisible(visible)
	end

	function Element:AddColorPicker(idx, info)
		self._group:_colorPicker(idx, info, self)
		return self
	end

	function Element:AddKeyPicker(idx, info)
		self._group:_keyPicker(idx, info, self)
		return self
	end

	local KeyPicker = setmetatable({}, { __index = Element })
	KeyPicker.__index = KeyPicker

	function KeyPicker:GetState()
		if self.Mode == "Always" then
			return true
		elseif self.Mode == "Hold" then
			return self.Held
		end
		return self.Toggled
	end

	-- The MD3 keybind runs in Hold mode (press and release both arrive here);
	-- Toggle / Hold behave like Linoria's key picker on top of that.
	function KeyPicker:_key(down)
		if self.Mode == "Always" then
			return
		end
		if self.Mode == "Hold" then
			local was = self.Held
			self.Held = down
			if was ~= down then
				local parent = self._parent
				if self.SyncToggleState and parent and parent.Type == "Toggle" then
					parent:SetValue(down)
				elseif self._callback and self._holdCallback then
					self._callback(down)
				end
			end
			self._md3:SetState(down)
			return
		end
		if self.Mode == "Toggle" and down then
			local parent = self._parent
			if self.SyncToggleState and parent and parent.Type == "Toggle" then
				parent:SetValue(not parent.Value)
			else
				self.Toggled = not self.Toggled
			end
			if self._callback then
				self._callback(self.Toggled)
			end
		end
		self._md3:SetState(self.Toggled)
	end

	local Group = {}
	Group.__index = Group

	local function newGroup(section, box)
		return setmetatable({ _section = section, _box = box }, Group)
	end

	function Port.Section(tab, title)
		return newGroup(tab:AddSection(title), nil)
	end

	function Group:_add(md3Element)
		if self._box then
			table.insert(self._box.Members, md3Element)
			md3Element:SetVisible(self._box.Visible)
		end
		return md3Element
	end

	function Group:_wrap(kind, info, class)
		local element = setmetatable({
			Type = kind,
			Text = info.Text,
			Addons = {},
			_group = self,
			_changed = {},
			_callback = info.Callback,
		}, class or Element)
		return element, function(value)
			element:_fire(value)
		end
	end

	function Group:AddToggle(idx, info)
		local element, fire = self:_wrap("Toggle", info)
		element.Value = info.Default == true
		element._md3 = self:_add(self._section:AddToggle({
			Title = titleCase(info.Text),
			Description = info.Tooltip,
			Default = element.Value,
			Flag = idx,
			Callback = fire,
		}))
		Toggles[idx] = element
		return element
	end

	function Group:AddSlider(idx, info)
		local element, fire = self:_wrap("Slider", info)
		local min, max = info.Min or 0, info.Max or 100
		element.Value = math.clamp(tonumber(info.Default) or min, min, max)
		element._md3 = self:_add(self._section:AddSlider({
			Title = titleCase(info.Text),
			Min = min,
			Max = max,
			Step = 10 ^ -(info.Rounding or 0),
			Default = element.Value,
			Suffix = info.Suffix,
			Flag = idx,
			Callback = fire,
		}))
		Options[idx] = element
		return element
	end

	function Group:AddDualSlider(leftIdx, rightIdx, leftInfo, rightInfo)
		return self:AddSlider(leftIdx, leftInfo), self:AddSlider(rightIdx, rightInfo)
	end

	local function toSet(list)
		local set = {}
		for key, value in list or {} do
			if type(key) == "number" then
				set[value] = true
			elseif value == true then
				set[key] = true
			end
		end
		return set
	end

	function Group:AddDropdown(idx, info)
		local element, fire = self:_wrap("Dropdown", info)
		local values = info.Values or {}
		local default = info.Default
		if info.Multi then
			local list = {}
			for name in toSet(type(default) == "table" and default or {}) do
				table.insert(list, name)
			end
			default = list
			element._fromMD3 = toSet
			element.Value = toSet(list)
		else
			if type(default) == "number" then
				default = values[default]
			end
			element.Value = default
		end
		element.Values = values
		element.Multi = info.Multi == true
		element._md3 = self:_add(self._section:AddDropdown({
			Title = titleCase(info.Text or idx),
			Options = values,
			Default = default,
			Multi = info.Multi == true,
			Flag = idx,
			Callback = fire,
		}))
		Options[idx] = element
		return element
	end

	function Group:AddInput(idx, info)
		local element, fire = self:_wrap("Input", info)
		element.Value = tostring(info.Default or "")
		element._md3 = self:_add(self._section:AddInput({
			Title = titleCase(info.Text),
			Default = element.Value,
			Placeholder = info.Placeholder,
			Numeric = info.Numeric == true,
			Finished = info.Finished ~= false,
			Flag = idx,
			Callback = fire,
		}))
		Options[idx] = element
		return element
	end

	function Group:_colorPicker(idx, info, parent)
		local element, fire = self:_wrap("ColorPicker", info)
		local title = info.Title and titleCase(info.Title)
			or (parent and titleCase(parent.Text) .. " color")
			or titleCase(idx)
		element.Value = info.Default or Color3.new(1, 1, 1)
		local default = element.Value
		if typeof(info.Default2) == "Color3" then
			-- A pair of colors becomes a two-stop gradient (flat when both match).
			default = {
				Color = element.Value,
				Mode = info.Default2 ~= element.Value and "Gradient" or "Solid",
				Anim = "None",
				Speed = 1,
				Stops = { { Pos = 0, Color = element.Value }, { Pos = 1, Color = info.Default2 } },
			}
		end
		element._md3 = self:_add(self._section:AddColorPicker({
			Title = title,
			Default = default,
			Flag = idx,
			Callback = fire,
		}))
		Options[idx] = element
		return element
	end

	function Group:_keyPicker(idx, info, parent)
		local picker = self:_wrap("KeyPicker", info, KeyPicker)
		picker.Mode = if info.SyncToggleState then "Toggle" else info.Mode or "Toggle"
		picker.SyncToggleState = info.SyncToggleState == true
		picker.Toggled = false
		picker.Held = false
		picker.Value = info.Default or "None"
		picker._parent = parent
		local name = titleCase(info.Text or (parent and parent.Text) or idx)
		picker._md3 = self:_add(self._section:AddKeybind({
			Title = name .. " key",
			Default = info.Default,
			Mode = "Hold",
			Notify = false,
			Flag = idx,
			Callback = function(down)
				picker:_key(down)
			end,
			ChangedCallback = function(key)
				picker.Value = key and key.Name or "None"
			end,
		}))
		if parent then
			table.insert(parent.Addons, picker)
		end
		local onToggle = parent and parent.Type == "Toggle" and parent._md3 ~= nil
		if onToggle and not (info.Modes and #info.Modes > 1) then
			-- Every key on a toggle can run as Always / Hold / Toggle. Callbacks that
			-- only know on/off (Callback(state)) also get the Hold state.
			info.Modes = { "Always", "Hold", "Toggle" }
			picker._holdCallback = true
		end
		if info.Modes and #info.Modes > 1 then
			local modes = self:AddDropdown(idx .. "Mode", {
				Text = name .. " key mode",
				Values = info.Modes,
				Default = picker.Mode,
				Callback = function(mode)
					picker.Mode = mode
					picker.Toggled = false
					picker.Held = false
					picker._md3:SetState(false)
				end,
			})
			picker.Modes = modes
		end
		-- On a toggle: the key (and mode) move into the toggle's gear popup instead of
		-- taking rows of their own.
		if parent and parent.Type == "Toggle" and parent._md3 then
			local ok, attached = pcall(MD3.GearUI.attach, {
				Section = self._section,
				Toggle = parent._md3,
				Key = picker._md3,
				Modes = picker.Modes and {
					Values = info.Modes,
					Get = function() return picker.Mode end,
					Set = function(mode) picker.Modes:SetValue(mode) end,
				} or nil,
			})
			if ok and attached and picker.Modes and picker.Modes._md3 then
				-- keep the mode dropdown out of the section (it is driven from the popup)
				local row = picker.Modes._md3.Instance
				local holder = Window.Gui and Window.Gui:FindFirstChild("KeyGearHolder")
				if row and holder then
					row.Parent = holder
				end
			end
		end
		Options[idx] = picker
		return picker
	end

	function Group:AddKeyPicker(idx, info)
		return self:_keyPicker(idx, info, nil)
	end

	function Group:AddButton(text, callback)
		if type(text) == "table" then
			text, callback = text.Text, text.Func or text.Callback
		end
		return self:_add(self._section:AddButton({ Title = titleCase(text), Callback = callback }))
	end

	function Group:AddLabel(text)
		return self:_add(self._section:AddLabel(tostring(text)))
	end

	function Group:AddDivider()
		return self:_add(self._section:AddDivider())
	end

	function Group:AddDependencyBox()
		local box = { Members = {}, Dependencies = {}, Visible = true, Parent = self._box }
		table.insert(boxes, box)
		local group = newGroup(self._section, box)
		function group:SetupDependencies(dependencies)
			box.Dependencies = dependencies
			refreshBoxes()
		end
		return group
	end

	-- Unload: switch every feature off through its own callback (that's what
	-- restores what it changed), then drop connections, GUIs and drawings.
	track(function()
		Port.Unloaded = true
		Library.Unloaded = true
		for _, element in Toggles do
			if element.Value == true and element._callback then
				pcall(element._callback, false)
			end
		end
		for _, element in Options do
			if element.Type == "KeyPicker" and (element.Toggled or element.Held) then
				element.Toggled, element.Held = false, false
				if element._callback then
					pcall(element._callback, false)
				end
			end
		end
		for _, connection in connections do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(connections)
		for index = #unloaders, 1, -1 do
			pcall(unloaders[index])
		end
		for gui in guis do
			pcall(function()
				gui:Destroy()
			end)
		end
		for object in drawings do
			pcall(function()
				object:Remove()
			end)
		end
		Port.Holder:Destroy()
	end)

	-- Connections made per event (a sound, a character) pile up; forget the
	-- ones that are already gone.
	task.spawn(function()
		while not Port.Unloaded do
			task.wait(30)
			for index = #connections, 1, -1 do
				if not connections[index].Connected then
					table.remove(connections, index)
				end
			end
		end
	end)

	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Workspace         = game:GetService("Workspace")
	local Camera            = workspace.CurrentCamera
	local GameModules       = ReplicatedStorage:WaitForChild("Modules", 30)
	local Utility           = instanceSafeRequire(GameModules:WaitForChild("Utility", 30))
	local EnumLibrary       = instanceSafeRequire(GameModules:WaitForChild("EnumLibrary", 30))

	-- The camera tab's stretched resolution is applied to Camera.CFrame itself,
	-- so WorldToViewportPoint already matches what is drawn: no extra correction.
	local function getAspectStretch()
		return 1
	end

	local function worldToScreen(worldPos, cam)
		cam = cam or workspace.CurrentCamera
		if not cam or not worldPos then
			return nil, false
		end
		local v, onScreen = cam:WorldToViewportPoint(worldPos)
		if not onScreen or v.Z <= 0 then
			return v, false
		end
		return v, true
	end

	local function screenAnchor(xNorm, yNorm, cam)
		cam = cam or workspace.CurrentCamera
		if not cam then
			return Vector2.zero
		end
		local vs = cam.ViewportSize
		return Vector2.new(vs.X * xNorm, vs.Y * yNorm)
	end

	local function screenCenter(cam)
		return screenAnchor(0.5, 0.5, cam)
	end

	local function getUnstretchedCameraCFrame(cam)
		cam = cam or workspace.CurrentCamera
		if not cam then
			return nil
		end
		local cf = cam.CFrame
		return CFrame.fromMatrix(cf.Position, cf.RightVector.Unit, cf.UpVector.Unit, -cf.LookVector.Unit)
	end

	getgenv().InstanceGetAspectStretch = getAspectStretch
	getgenv().InstanceWorldToScreen = worldToScreen
	getgenv().InstanceScreenAnchor = screenAnchor
	getgenv().InstanceScreenCenter = screenCenter
	getgenv().InstanceGetUnstretchedCameraCFrame = getUnstretchedCameraCFrame

	_G.Features = _G.Features or {}
	getgenv().InstanceCombatLastShotAt = getgenv().InstanceCombatLastShotAt or 0

	local function markCombatShot()
		getgenv().InstanceCombatLastShotAt = tick()
	end
	getgenv().InstanceMarkCombatShot = markCombatShot

	getgenv().InstanceWorldToScreenEsp = function(worldPos, cam)
		return worldToScreen(worldPos, cam)
	end

	local damageBillboardInfoCache = setmetatable({}, { __mode = "k" })
	local getDamageBillboardInfo

	local espgui
	local findShotMuzzlePosition
	local localHitTargets = setmetatable({}, { __mode = "k" })

