			local picker = Options and Options.AimbotKey
			if not picker then return end

			local mode = picker.Mode and string.lower(picker.Mode) or "toggle"
			if mode ~= aimbot.keyMode then
				aimbot.keyMode = mode
				aimbot.enabled = false
				clearAimbotLock()
				updaimbot()
			end

			if mode == "always" then
				-- no key: on whenever the master toggle is on
				if aimbot.masterEnabled ~= aimbot.enabled then
					aimbot.enabled = aimbot.masterEnabled
					if not aimbot.enabled then
						clearAimbotLock()
					end
					updaimbot()
				end
				return
			end

			if mode ~= "hold" or not aimbot.masterEnabled then return end
			local held = picker:GetState()
			if held == aimbot.enabled then return end
			aimbot.enabled = held
			if not held then
				clearAimbotLock()
			end
			updaimbot()
		end))

