				SpreadAngle = Vector2.new(180, 180),
				EmissionDirection = Enum.NormalId.Bottom,
				Lifetime = NumberRange.new(0.8, 1.4),
				Drag = 3,
				Acceleration = Vector3.new(0, -14, 0),
				Size = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.5),
					NumberSequenceKeypoint.new(1, 0.1)
				}),
				LightEmission = 0.2,
				Brightness = 2,
			})
			spawnHitEmitter(targetPart, {
				Name = "VoidRiftEdge",
				Texture = "rbxassetid://446111271",
				Color = voidEdge,
				EmitCount = 45,
				Speed = NumberRange.new(10, 22),
				SpreadAngle = Vector2.new(180, 180),
				Lifetime = NumberRange.new(0.4, 0.85),
				RotSpeed = NumberRange.new(-300, 300),
				Brightness = 10,
				LightEmission = 1,
				Cleanup = 2,
			})
		end

		local function plasmaEffect(adornee, color)
			local targetPart = getHitEffectPart(adornee)
			if not targetPart then return end
			local plasmaB = Color3.new(math.clamp(1 - color.R, 0, 1), math.clamp(color.G, 0, 1), math.clamp(color.B + 0.3, 0, 1))
			spawnHitFlash(targetPart, color, 12, 18, 0.35)
			spawnHitEmitter(targetPart, {
				Name = "PlasmaCore",
				Texture = "rbxassetid://446111271",
				Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, color),
					ColorSequenceKeypoint.new(0.5, plasmaB),
					ColorSequenceKeypoint.new(1, color)
				}),
				Brightness = 15,
				EmitCount = 55,
				Speed = NumberRange.new(6, 16),
				SpreadAngle = Vector2.new(180, 180),
				Lifetime = NumberRange.new(0.35, 0.7),
				Size = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.55),
					NumberSequenceKeypoint.new(1, 0.08)
				}),
				LightEmission = 1,
			})
			spawnHitRing(targetPart, plasmaB, {Name = "PlasmaRing", StartSize = 0.4, EndSize = 5.5, Duration = 0.4, StartTransparency = 0.25})
		end

		local function glitchEffect(adornee, color)
			local targetPart = getHitEffectPart(adornee)
			if not targetPart then return end
			for i = 1, 6 do
				spawnHitEmitter(targetPart, {
					Name = "GlitchShard" .. i,
					Texture = "rbxassetid://243660364",
					Color = (i % 2 == 0) and color or blendHitColor(color, 0.5),
					EmitCount = 8,
					Speed = NumberRange.new(18, 32),
					SpreadAngle = Vector2.new(40, 40),
					EmissionDirection = Enum.NormalId.Top,
					Lifetime = NumberRange.new(0.1, 0.25),
					Drag = 0,
					RotSpeed = NumberRange.new(-500, 500),
					Size = NumberSequence.new({
						NumberSequenceKeypoint.new(0, 0.35),
						NumberSequenceKeypoint.new(1, 0.1)
					}),
					Transparency = NumberSequence.new({
						NumberSequenceKeypoint.new(0, math.random() * 0.4),
						NumberSequenceKeypoint.new(1, 1)
					}),
					Cleanup = 0.8,
				})
			end
			spawnHitFlash(targetPart, blendHitColor(color, 0.6), 8, 10, 0.15)
		end

		local function cosmicDustEffect(adornee, color)
			local targetPart = getHitEffectPart(adornee)
			if not targetPart then return end
			spawnHitFlash(targetPart, blendHitColor(color, 0.25), 5, 16, 0.6)
			spawnHitEmitter(targetPart, {
				Name = "CosmicDust",
				Texture = "rbxassetid://1084982556",
				Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
					ColorSequenceKeypoint.new(0.4, color),
					ColorSequenceKeypoint.new(1, darkenHitColor(color, 0.2))
				}),
				EmitCount = 60,
				Speed = NumberRange.new(3, 14),
				SpreadAngle = Vector2.new(180, 180),
				Lifetime = NumberRange.new(1.2, 2),
				Drag = 0.5,
				Acceleration = Vector3.new(0, 2, 0),
				RotSpeed = NumberRange.new(-80, 80),
				Brightness = 9,
				Size = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.08),
					NumberSequenceKeypoint.new(0.5, 0.18),
					NumberSequenceKeypoint.new(1, 0.04)
				}),
				Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.1),
					NumberSequenceKeypoint.new(1, 1)
				}),
			})
			spawnHitRing(targetPart, blendHitColor(color, 0.1), {Name = "CosmicRing", StartSize = 0.2, EndSize = 3.5, Duration = 0.8, StartTransparency = 0.65, Material = Enum.Material.Glass})
		end

		local hitEffectHandlers = {
			Particles = particledesign,
			Fortnite = fortniteffect,
			Shockwave = shockwaveEffect,
			Lightning = lightningEffect,
			Blood = bloodEffect,
			Fire = fireEffect,
			Ice = iceEffect,
			Hearts = heartsEffect,
			Stars = starsEffect,
			Confetti = confettiEffect,
			Ripple = rippleEffect,
			Sparks = sparksEffect,
			Neon = neonPulseEffect,
			Void = voidRiftEffect,
			Plasma = plasmaEffect,
			Glitch = glitchEffect,
			["Cosmic Shit"] = cosmicDustEffect,
		}

		Port.Track(workspace.DescendantAdded:Connect(function(obj)
			if not hitEffectEnabled then return end
			if not obj:IsA("BillboardGui") then return end
			local info = getDamageBillboardInfo(obj)
			if not info then return end

			task.defer(function()
				if not obj or not obj.Parent then return end
				obj.Enabled = false

				each_style(function(style)
					local handler = hitEffectHandlers[style]
					if handler then
						if style == "Fortnite" then
							handler(info.adornee, hitEffectColor, info.lbl.Text)
						else
							handler(info.adornee, hitEffectColor)
						end
					end
				end)
			end)
		end))
		end)()

	end

	-- Feedback: bullet tracers
	do
		local TracersGroup = Port.Section(FeedbackTab, "Bullet Tracers")

		local tracerEnabled  = false
		local tracerColor    = Color3.fromRGB(255, 255, 255)
		local tracerDuration = 3
		local tracerSize     = 1
		local tracerFadeTime = 0.5
		local tracerLerpSpeed = 0
		local tracerStyle    = "Line"
		local tracers        = {}
		local tracerconn     = nil
		local tracerEffectHooked = false

		local DISABLE_TRACERS = false
		local lastTracerCreations = {}
		local DEDUPE_INTERVAL     = 0.1
		local DEDUPE_EXPIRY       = 1.0

		local textureAssets = {
			Line      = "",
			Beam      = "rbxassetid://12781852245",
			Lightning = "rbxassetid://446111271",
			Heartrate = "rbxassetid://5830549480",
			Chain     = "rbxassetid://9632168658",
			Glitch    = "rbxassetid://8089467613",
			Swirl     = "rbxassetid://5638168605",
			Neon      = "rbxassetid://6361963422",
			Plasma    = "rbxassetid://8993645509",
			Laser     = "rbxassetid://14549123968",
		}

		local function muzzlepos()
			local viewModels = workspace:FindFirstChild("ViewModels")
			if not viewModels then return nil end
			local firstPerson = viewModels:FindFirstChild("FirstPerson")
			if not firstPerson then return nil end
			local playerName = LocalPlayer.Name
			for _, model in ipairs(firstPerson:GetChildren()) do
				if model:IsA("Model") and model.Name:find("^" .. playerName) then
					local iv = model:FindFirstChild("ItemVisual")
					if iv then
						local body = iv:FindFirstChild("Body")
						if body then
							local bp = body:FindFirstChild("BodyPrimary")
							if bp then
								local muzzle = bp:FindFirstChild("_muzzle")
								if muzzle and muzzle:IsA("Attachment") then
									return muzzle.WorldPosition
								end
							end
						end
					end
				end
			end
			if type(findShotMuzzlePosition) == "function" then
				return findShotMuzzlePosition()
			end
			return nil
		end

		local function getTracerDrawEnd(tr, age)
			if tracerLerpSpeed <= 0 then
				return tr.EndPos
			end
			local drawTime = math.max(tracerLerpSpeed * 0.25, 0.001)
			local progress = math.clamp(age / drawTime, 0, 1)
			return tr.StartPos:Lerp(tr.EndPos, progress)
		end

		local function makeLineTracer(pos3, endPos)
			local outline = Drawing.new("Line")
			outline.Thickness   = 4 * tracerSize
			outline.Color       = Color3.new(0, 0, 0)
			outline.Transparency = 1
			outline.Visible     = false

			local line = Drawing.new("Line")
			line.Thickness   = 2 * tracerSize
			line.Color       = tracerColor
			line.Transparency = 1
			line.Visible     = false

			table.insert(tracers, {
				IsLine      = true,
				Outline     = outline,
				Line        = line,
				StartPos    = pos3,
				EndPos      = endPos,
				Lifetime    = tracerDuration,
				FadeTime    = tracerFadeTime,
				CreatedTime = tick(),
			})
		end

		local function makeBeamTracer(pos3, endPos)
			local a0 = Instance.new("Attachment")
			a0.Parent = workspace.Terrain
			local a1 = Instance.new("Attachment")
			a1.Parent = workspace.Terrain

			local beam          = Instance.new("Beam")
			beam.Attachment0    = a0
			beam.Attachment1    = a1
			beam.Color          = ColorSequence.new(tracerColor)
			local baseW         = tracerStyle == "Laser" and 0.02 or 0.15
			beam.Width0         = baseW * tracerSize
			beam.Width1         = baseW * tracerSize
			beam.Transparency   = NumberSequence.new(0)
			beam.FaceCamera     = true
			beam.LightEmission  = 0.8
			beam.LightInfluence = 0.2

			local tex = textureAssets[tracerStyle]
			if tex and tex ~= "" then
				beam.Texture       = tex
				beam.TextureLength = 4
				beam.TextureSpeed  = 1
			else
				beam.Texture       = ""
				beam.TextureLength = 1
				beam.TextureSpeed  = 0
			end

			beam.Parent = workspace.Terrain
			a0.WorldPosition = pos3
			a1.WorldPosition = endPos

			table.insert(tracers, {
				IsLine      = false,
				Beam        = beam,
				Attachment0 = a0,
				Attachment1 = a1,
				StartPos    = pos3,
				EndPos      = endPos,
				Lifetime    = tracerDuration,
				FadeTime    = tracerFadeTime,
				CreatedTime = tick(),
			})
		end

		local function maketracer(pos3, endPos)
			if DISABLE_TRACERS or not pos3 or not endPos then return end

			local kx = math.floor(pos3.X * 5 + 0.5)
			local ky = math.floor(pos3.Y * 5 + 0.5)
			local kz = math.floor(pos3.Z * 5 + 0.5)
			local ex = math.floor(endPos.X * 5 + 0.5)
			local ey = math.floor(endPos.Y * 5 + 0.5)
			local ez = math.floor(endPos.Z * 5 + 0.5)
			local posKey = kx * 1e9 + ky * 1e6 + kz * 1e3 + ex + ey * 1e-3 + ez * 1e-6

			local now = tick()
			local last = lastTracerCreations[posKey]
			if last and (now - last) < DEDUPE_INTERVAL then return end
			lastTracerCreations[posKey] = now

			if tracerStyle == "Line" then
				makeLineTracer(pos3, endPos)
			else
				makeBeamTracer(pos3, endPos)
			end
		end

		local function destroyTracer(t)
			if t.IsLine then
				if t.Outline then t.Outline:Remove() end
				if t.Line    then t.Line:Remove()    end
			else
				if t.Beam        then t.Beam:Destroy()        end
				if t.Attachment0 then t.Attachment0:Destroy() end
				if t.Attachment1 then t.Attachment1:Destroy() end
			end
		end

		local frameCount       = 0
		local DEDUPE_PRUNE_INT = 120
		local camera           = workspace.CurrentCamera

		local function updtracers()
			if #tracers == 0 then return end

			frameCount = frameCount + 1
			local now   = tick()
			local cam   = camera or workspace.CurrentCamera
			camera      = cam

			local myChar = LocalPlayer.Character
			local myPos  = myChar and myChar:FindFirstChild("HumanoidRootPart")
						   and myChar.HumanoidRootPart.Position

			if frameCount % DEDUPE_PRUNE_INT == 0 then
				for k, t in next, lastTracerCreations do
					if (now - t) > DEDUPE_EXPIRY then
						lastTracerCreations[k] = nil
					end
				end
			end

			local i = #tracers
			while i >= 1 do
				local tr  = tracers[i]
				local age = now - tr.CreatedTime

				if age >= tr.Lifetime then
					destroyTracer(tr)
					tracers[i] = tracers[#tracers]
					tracers[#tracers] = nil
				else
					local fadeAlpha
					local fadeStart = tr.Lifetime - tr.FadeTime
					if age >= fadeStart then
						fadeAlpha = 1 - math.clamp((age - fadeStart) / tr.FadeTime, 0, 1)
					else
						fadeAlpha = 1
					end

					if tr.IsLine then
						local visible = false
						local drawEnd = getTracerDrawEnd(tr, age)
						local camPos = cam and cam.CFrame.Position
						local nearCamera = camPos and (tr.StartPos - camPos).Magnitude <= 12
						if nearCamera or not myPos or (tr.StartPos - myPos).Magnitude > 2 then
							local s2, onS = worldToScreen(tr.StartPos, cam)
							local e2, onE = worldToScreen(drawEnd, cam)

							if onS and onE then
								local sx, sy = s2.X, s2.Y
								local ex2, ey = e2.X, e2.Y
								if sx == sx and sy == sy and ex2 == ex2 and ey == ey
								   and math.abs(sx) < 20000 and math.abs(sy) < 20000
								   and math.abs(ex2) < 20000 and math.abs(ey) < 20000 then

									local dx = ex2 - sx
									local dy = ey - sy
									local len = math.sqrt(dx * dx + dy * dy)
									if len > 0.1 and len < 3000 then
										local fv2s = Vector2.new(sx, sy)
										local fv2e = Vector2.new(ex2, ey)

										tr.Outline.From = fv2s
										tr.Outline.To   = fv2e
										tr.Outline.Transparency = fadeAlpha
										tr.Outline.Visible = true

										tr.Line.From = fv2s
										tr.Line.To   = fv2e
										tr.Line.Transparency = fadeAlpha
										tr.Line.Visible = true
										visible = true
									end
								end
							end
						end

						if not visible then
							tr.Outline.Visible = false
							tr.Line.Visible    = false
						end
					else
						local drawEnd = getTracerDrawEnd(tr, age)
						if tr.Attachment0 then
							tr.Attachment0.WorldPosition = tr.StartPos
						end
						if tr.Attachment1 then
							tr.Attachment1.WorldPosition = drawEnd
						end
						tr.Beam.Transparency = NumberSequence.new(1 - fadeAlpha)
					end
				end

				i = i - 1
			end
		end

		local function hookTracerEffect()
			if tracerEffectHooked then return end
			pcall(function()
				local TracerEffect = require(LocalPlayer.PlayerScripts.Modules.TracerEffect)
				local origPlay     = TracerEffect.Play

				TracerEffect.Play = function(self, tracerData, config, extraData)
					if tracerEnabled and tracerData and tracerData.IsLocal and tracerData.RaycastResults then
						local mPos = muzzlepos()
						if mPos then
							for _, hit in ipairs(tracerData.RaycastResults) do
								if hit.Position then
									maketracer(mPos, hit.Position)
								end
							end
						end
					end
					return origPlay(self, tracerData, config, extraData)
				end

				tracerEffectHooked = true
				Port.OnUnload(function()
					TracerEffect.Play = origPlay
				end)
			end)
		end

		local function startTracers()
			if DISABLE_TRACERS then
				tracerEnabled = false
				return
			end

			hookTracerEffect()

			if not tracerconn then
				tracerconn = Port.Track(RunService.RenderStepped:Connect(updtracers))
			end
		end

		local function stoptracers()
			if tracerconn then
				tracerconn:Disconnect()
				tracerconn = nil
			end
			for _, tr in ipairs(tracers) do
				destroyTracer(tr)
			end
			tracers = {}
		end

		TracersGroup:AddToggle("TracerEnabled", {
			Text    = "enable",
			Default = false,
			Callback = function(val)
				tracerEnabled = val
				if val then
					startTracers()
				else
					stoptracers()
				end
			end
		}):AddColorPicker("TracerColor", {
			Default  = Color3.fromRGB(255, 255, 255),
			Title    = "tracer color",
			Callback = function(val)
				tracerColor = val
				for _, tr in ipairs(tracers) do
					if tr.IsLine then
						if tr.Line then tr.Line.Color = val end
					elseif tr.Beam then
						tr.Beam.Color = ColorSequence.new(val)
					end
				end
			end
		})

		TracersGroup:AddDropdown("TracerStyle", {
			Text     = "style",
			Default  = "Line",
			Values   = {"Line","Beam","Lightning","Heartrate","Chain","Glitch","Swirl","Neon","Plasma","Laser"},
			Callback = function(val)
				tracerStyle = val
			end
		})

		TracersGroup:AddSlider("TracerDuration", {
			Text     = "duration",
			Default  = 3,
			Min      = 0.1,
			Max      = 10,
			Rounding = 1,
			Compact  = true,
			Callback = function(val)
				tracerDuration = val
				for _, tr in ipairs(tracers) do tr.Lifetime = val end
			end
		})

		TracersGroup:AddSlider("TracerSize", {
			Text     = "size",
			Default  = 1,
			Min      = 0.5,
			Max      = 5,
			Rounding = 1,
			Compact  = true,
			Callback = function(val)
				tracerSize = val
				for _, tr in ipairs(tracers) do
					if tr.IsLine then
						if tr.Outline then tr.Outline.Thickness = 4 * val end
						if tr.Line    then tr.Line.Thickness    = 2 * val end
					elseif tr.Beam then
						local baseW = tracerStyle == "Laser" and 0.02 or 0.15
						tr.Beam.Width0 = baseW * val
						tr.Beam.Width1 = baseW * val
					end
				end
			end
		})

		TracersGroup:AddSlider("TracerFade", {
			Text     = "fade time",
			Default  = 0.5,
			Min      = 0,
			Max      = 2,
			Rounding = 1,
			Compact  = true,
			Callback = function(val)
				tracerFadeTime = val
				for _, tr in ipairs(tracers) do tr.FadeTime = val end
			end
		})

		TracersGroup:AddSlider("TracerLerpSpeed", {
			Text     = "lerp speed",
			Default  = 0,
			Min      = 0,
			Max      = 5,
			Rounding = 1,
			Compact  = true,
			Callback = function(val)
				tracerLerpSpeed = val
			end
		})

		task.defer(function()
			for _ = 1, 30 do
				if tracerEffectHooked then
					break
				end
				hookTracerEffect()
				task.wait(0.5)
			end
		end)

	end

	-- Weapon a player holds, for the ESP
	local function getEspPlayerWeapon(player)
		if not player then return "None" end
		local viewModels = workspace:FindFirstChild("ViewModels")
		if not viewModels then return "None" end
		local playerName = player.Name

		local function weaponFromModelName(modelName)
			local parts = {}
			for part in modelName:gmatch("[^-]+") do
				table.insert(parts, part:match("^%s*(.-)%s*$"))
			end
			if #parts >= 2 and parts[1] == playerName then
				return parts[2]
			end
			return nil
		end

		for _, child in ipairs(viewModels:GetChildren()) do
			local w = weaponFromModelName(child.Name)
			if w then return w end
		end

		local fp = viewModels:FindFirstChild("FirstPerson")
		if fp then
			for _, child in ipairs(fp:GetChildren()) do
				local w = weaponFromModelName(child.Name)
				if w then return w end
			end
		end

		return "None"
	end

	-- Hit notifications (lived inside the ragebot)
	do
		local config = ragebot.config
		local ragePerf = ragebot.ragePerf
		local isRageEnabled = ragebot.isRageEnabled
		local players = cloneref(game:GetService("Players"))
		local player = players.LocalPlayer
		local TextService = game:GetService("TextService")
		local UserInputService = cloneref(game:GetService("UserInputService"))

		local hitNotifEntries = {}
		local hitNotifHpTrack = {}
		local hitNotifHumConn = {}
		local hitNotifCharConn = {}
		local hitNotifResolveQueues = {}
		local hitNotifResolveBusy = {}

		local HIT_NOTIF_ANIM_STYLES = {
			"fade",
			"slide left",
			"slide right",
			"slide down",
			"bounce",
			"fade bounce",
			"scale",
		}

		local HIT_NOTIF_STACK_WIDTH = 300

		local hitNotifRoot = Library:Create("Frame", {
			Name = "HitNotifications",
			BackgroundTransparency = 1,
			Size = UDim2.new(0, HIT_NOTIF_STACK_WIDTH, 1, -24),
			Position = UDim2.fromOffset(12, 12),
			ZIndex = 250,
			Parent = Library.ScreenGui,
		})

		local function getHitNotifScreenPosition()
			local hn = config.hitNotifications
			local preset = hn.position or "Top Left"
			if preset == "Custom" then
				return Vector2.new(hn.offsetX or 12, hn.offsetY or 12)
			end

			local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)
			local margin = 12
			local stackH = 280
			local centerX = vp.X * 0.5 - HIT_NOTIF_STACK_WIDTH * 0.5

			local presets = {
				["Top Left"] = Vector2.new(margin, margin),
				["Top Center"] = Vector2.new(centerX, margin),
				["Top Right"] = Vector2.new(vp.X - HIT_NOTIF_STACK_WIDTH - margin, margin),
				["Center Left"] = Vector2.new(margin, vp.Y * 0.5 - stackH * 0.5),
				["Center"] = Vector2.new(centerX, vp.Y * 0.5 - stackH * 0.5),
				["Center Right"] = Vector2.new(vp.X - HIT_NOTIF_STACK_WIDTH - margin, vp.Y * 0.5 - stackH * 0.5),
				["Bottom Left"] = Vector2.new(margin, vp.Y - stackH - margin),
				["Bottom Center"] = Vector2.new(centerX, vp.Y - stackH - margin),
				["Bottom Right"] = Vector2.new(vp.X - HIT_NOTIF_STACK_WIDTH - margin, vp.Y - stackH - margin),
			}
			return presets[preset] or presets["Top Left"]
		end

		local function applyHitNotifRootPosition()
			local pos = getHitNotifScreenPosition()
			hitNotifRoot.Position = UDim2.fromOffset(math.floor(pos.X), math.floor(pos.Y))
		end

		local function hnEaseOutCubic(t)
			return 1 - (1 - t) ^ 3
		end

		local function hnEaseInCubic(t)
			return t * t * t
		end

		local function hnEaseOutBack(t)
			local c1 = 1.70158
			return 1 + (c1 + 1) * (t - 1) ^ 3 + c1 * (t - 1) ^ 2
		end

		local HIT_NOTIF_IN_SAMPLERS = {}
		local HIT_NOTIF_OUT_SAMPLERS = {}

		HIT_NOTIF_IN_SAMPLERS.fade = function(t)
			return hnEaseOutCubic(t), 0, 0, 1
		end
		HIT_NOTIF_IN_SAMPLERS["slide left"] = function(t)
			local e = hnEaseOutCubic(t)
			return e, (1 - e) * -52, 0, 1
		end
		HIT_NOTIF_IN_SAMPLERS["slide right"] = function(t)
			local e = hnEaseOutCubic(t)
			return e, (1 - e) * 52, 0, 1
		end
		HIT_NOTIF_IN_SAMPLERS["slide down"] = function(t)
			local e = hnEaseOutCubic(t)
			return e, 0, (1 - e) * -32, 1
		end
		HIT_NOTIF_IN_SAMPLERS.bounce = function(t)
			return math.clamp(t * 6, 0, 1), 0, 0, hnEaseOutBack(t)
		end
		HIT_NOTIF_IN_SAMPLERS["fade bounce"] = function(t)
			return hnEaseOutCubic(t), 0, 0, 0.78 + hnEaseOutBack(t) * 0.28
		end
		HIT_NOTIF_IN_SAMPLERS.scale = function(t)
			local e = hnEaseOutCubic(t)
			return e, 0, 0, 0.62 + e * 0.38
		end

		HIT_NOTIF_OUT_SAMPLERS.fade = function(t)
			local e = hnEaseInCubic(t)
			return 1 - e, 0, 0, 1
		end
		HIT_NOTIF_OUT_SAMPLERS["slide left"] = function(t)
			local e = hnEaseInCubic(t)
			return 1 - e, e * -52, 0, 1
		end
		HIT_NOTIF_OUT_SAMPLERS["slide right"] = function(t)
			local e = hnEaseInCubic(t)
			return 1 - e, e * 52, 0, 1
		end
		HIT_NOTIF_OUT_SAMPLERS["slide down"] = function(t)
			local e = hnEaseInCubic(t)
			return 1 - e, 0, e * 32, 1
		end
		HIT_NOTIF_OUT_SAMPLERS.bounce = function(t)
			local e = hnEaseInCubic(t)
			return 1 - e, 0, 0, 1 - e * 0.1 + math.sin(t * math.pi) * 0.09 * (1 - e)
		end
		HIT_NOTIF_OUT_SAMPLERS["fade bounce"] = function(t)
			local e = hnEaseInCubic(t)
			return 1 - e, 0, 0, 1 - e * 0.08 + math.sin(t * math.pi * 1.5) * 0.07 * (1 - t)
		end
		HIT_NOTIF_OUT_SAMPLERS.scale = function(t)
			local e = hnEaseInCubic(t)
			return 1 - e, 0, 0, 1 - e * 0.4
		end

		local function sampleHitNotifAnim(style, t, isOut)
			t = math.clamp(t, 0, 1)
			local map = isOut and HIT_NOTIF_OUT_SAMPLERS or HIT_NOTIF_IN_SAMPLERS
			local fn = map[string.lower(style or "fade")] or map.fade
			local a, ox, oy, sc = fn(t)
			return math.clamp(a, 0, 1), ox, oy, math.clamp(sc, 0.01, 1.35)
		end

		local function applyHitNotifVisual(entry, alpha, ox, oy, scale)
			local tr = 1 - math.clamp(alpha, 0, 1)
			entry.outer.BackgroundTransparency = tr
			entry.inner.BackgroundTransparency = tr
			entry.label.TextTransparency = tr
			if entry.uiScale then
				entry.uiScale.Scale = scale
			end
			local y = (entry.displayY or entry.targetY or 0) + oy
			entry.outer.Position = UDim2.fromOffset(math.floor(ox + 0.5), math.floor(y + 0.5))
		end

		local function measureHitNotifBox(text, textSize)
			local bounds = TextService:GetTextSize(text, textSize, Enum.Font.Code, Vector2.new(1000, 40))
			return math.clamp(bounds.X + 20, 200, 540), math.max(bounds.Y + 12, 26)
		end

		local function removeHitNotifEntry(index)
			local entry = hitNotifEntries[index]
			if entry and entry.outer then
				pcall(function()
					entry.outer:Destroy()
				end)
			end
			table.remove(hitNotifEntries, index)
		end

		local function formatHitNotifLine(targetName, dmg, bodyPart)
			return string.format(
				"hit %s for %d in the %s",
				targetName,
				math.floor(dmg + 0.5),
				bodyPart or "Body"
			)
		end

		local function createHitNotifBox(text)
			local hn = config.hitNotifications
			local textSize = hn.textSize or 14
			local boxW, boxH = measureHitNotifBox(text, textSize)

			local outer = Library:Create("Frame", {
				Name = "HitNotifOuter",
				BackgroundColor3 = Library.MainColor,
				BorderColor3 = Library.OutlineColor,
				BorderMode = Enum.BorderMode.Inset,
				Size = UDim2.fromOffset(boxW, boxH),
				Position = UDim2.fromOffset(0, 0),
				BackgroundTransparency = 1,
				ZIndex = 251,
				Parent = hitNotifRoot,
			})
			Library:AddToRegistry(outer, {
				BackgroundColor3 = "MainColor",
				BorderColor3 = "OutlineColor",
			}, true)

			local uiScale = Instance.new("UIScale")
			uiScale.Scale = 0.75
			uiScale.Parent = outer

			local inner = Library:Create("Frame", {
				Name = "HitNotifInner",
				BackgroundColor3 = Library.BackgroundColor,
				BorderColor3 = Library.OutlineColor,
				BorderMode = Enum.BorderMode.Inset,
				Position = UDim2.fromOffset(1, 1),
				Size = UDim2.new(1, -2, 1, -2),
				BackgroundTransparency = 1,
				ZIndex = 252,
				Parent = outer,
			})
			Library:AddToRegistry(inner, {
				BackgroundColor3 = "BackgroundColor",
				BorderColor3 = "OutlineColor",
			}, true)

			local label = Library:CreateLabel({
				Size = UDim2.new(1, -12, 1, 0),
				Position = UDim2.fromOffset(6, 0),
				Text = text,
				Font = Enum.Font.Code,
				TextSize = textSize,
				TextColor3 = hn.color or Library.FontColor,
				TextTransparency = 1,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Center,
				ZIndex = 254,
				Parent = inner,
			}, false)

			return {
				outer = outer,
				inner = inner,
				label = label,
				uiScale = uiScale,
				boxW = boxW,
				boxH = boxH,
			}
		end

		local function pushHitNotification(targetName, dmg, bodyPart)
			if not config.hitNotifications.enabled or dmg <= 0 then
				return
			end

			local hn = config.hitNotifications
			local now = tick()
			applyHitNotifRootPosition()
			hitNotifRoot.Visible = true

			local parts = createHitNotifBox(formatHitNotifLine(targetName, dmg, bodyPart))
			table.insert(hitNotifEntries, 1, {
				outer = parts.outer,
				inner = parts.inner,
				label = parts.label,
				uiScale = parts.uiScale,
				boxW = parts.boxW,
				boxH = parts.boxH,
				start = now,
				phaseStart = now,
				phase = "in",
				duration = hn.duration or 3,
				targetY = 0,
				displayY = 0,
			})

			while #hitNotifEntries > math.clamp(hn.maxVisible or 8, 1, 25) do
				removeHitNotifEntry(#hitNotifEntries)
			end
		end

		local function getPlayerFromHitPart(hitPart)
			if not hitPart then
				return nil, nil, nil
			end
			local char = hitPart:FindFirstAncestorOfClass("Model")
			if not char and hitPart.Parent and hitPart.Parent:IsA("Model") then
				char = hitPart.Parent
			end
			if not char then
				return nil, nil, nil
			end
			local hum = char:FindFirstChildOfClass("Humanoid")
			local plr = players:GetPlayerFromCharacter(char)
			return plr, hum, hitPart.Name
		end

		local function shouldNotifyPlayerHit(plr)
			if not config.hitNotifications.enabled or plr == player then
				return false
			end

			local lastShot = getgenv().InstanceCombatLastShotAt or 0
			if tick() - lastShot < 4 then
				return true
			end

			if config.target.lastplayer == plr then
				return true
			end
			if config.target.enabled and config.target.character then
				local tp = players:GetPlayerFromCharacter(config.target.character)
				if tp == plr then
					return true
				end
			end
			local lastHit = ragePerf.lastHitAtByPlayer[plr]
			return lastHit ~= nil and tick() - lastHit < 4
		end

		local function tryClaimHitDamage(plr, hum, bodyPart, allowFallback)
			if not hum or not hum.Parent then
				return false
			end

			local last = hitNotifHpTrack[plr]
			if last == nil then
				last = hum.Health
				hitNotifHpTrack[plr] = last
			end

			local cur = hum.Health
			local dmg = last - cur
			if dmg >= 0.01 then
				pushHitNotification(plr.Name, dmg, bodyPart or ragePerf.hitPartByPlayer[plr] or config.target.hitpart or "Body")
				hitNotifHpTrack[plr] = cur
				ragePerf.lastHitAtByPlayer[plr] = tick()
				return true
			end

			if allowFallback then
				pushHitNotification(plr.Name, 1, bodyPart or ragePerf.hitPartByPlayer[plr] or config.target.hitpart or "Body")
				ragePerf.lastHitAtByPlayer[plr] = tick()
				return true
			end

			return false
		end

		local function resolveQueuedHitNotif(plr, job)
			local hum = job.hum
			local bodyPart = job.bodyPart
			if not hum or not hum.Parent then
				return
			end

			if tryClaimHitDamage(plr, hum, bodyPart, false) then
				return
			end

			for _ = 1, 15 do
				task.wait(0)
				if tryClaimHitDamage(plr, hum, bodyPart, false) then
					return
				end
			end

			for _ = 1, 8 do
				task.wait(0.03)
				if tryClaimHitDamage(plr, hum, bodyPart, false) then
					return
				end
			end

			tryClaimHitDamage(plr, hum, bodyPart, true)
		end

		local function enqueueHitNotifResolve(plr, hum, bodyPart)
			hitNotifResolveQueues[plr] = hitNotifResolveQueues[plr] or {}
			table.insert(hitNotifResolveQueues[plr], {
				hum = hum,
				bodyPart = bodyPart,
				queuedAt = tick(),
			})

			if hitNotifResolveBusy[plr] then
				return
			end

			hitNotifResolveBusy[plr] = true
			task.spawn(function()
				while hitNotifResolveQueues[plr] and #hitNotifResolveQueues[plr] > 0 do
					local job = table.remove(hitNotifResolveQueues[plr], 1)
					resolveQueuedHitNotif(plr, job)
				end
				hitNotifResolveBusy[plr] = false
			end)
		end

		local function pollHitNotifHealth()
			if not config.hitNotifications.enabled then
				return
			end

			for _, plr in ipairs(players:GetPlayers()) do
				if plr == player then
					continue
				end
				if not shouldNotifyPlayerHit(plr) then
					continue
				end

				local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
				if not hum then
					continue
				end

				local last = hitNotifHpTrack[plr]
				if last == nil then
					hitNotifHpTrack[plr] = hum.Health
					continue
				end

				local cur = hum.Health
				if cur < last - 0.01 then
					local bodyPart = ragePerf.hitPartByPlayer[plr] or config.target.hitpart or "Body"
					pushHitNotification(plr.Name, last - cur, bodyPart)
					hitNotifHpTrack[plr] = cur
					ragePerf.lastHitAtByPlayer[plr] = tick()
					if cur <= 0 then
						local tryKill = getgenv().InstanceTryKillSound
						if tryKill then
							tryKill(plr, last, cur)
						end
					end
				elseif cur > last then
					hitNotifHpTrack[plr] = cur
				end
			end
		end

		local function recordLocalHitTarget(plr, hum, bodyPart)
			if not plr or not hum or plr == player then
				return
			end
			localHitTargets[hum] = {
				plr = plr,
				bodyPart = bodyPart,
				hitAt = tick(),
				lastHp = hum.Health,
			}
		end

		local function notifyProjectileImpact(hitPart)
			if not hitPart then
				return
			end

			local plr, hum, bodyPart = getPlayerFromHitPart(hitPart)
			if not plr or not hum or plr == player then
				return
			end

			ragePerf.hitPartByPlayer[plr] = bodyPart
			ragePerf.lastHitAtByPlayer[plr] = tick()
			recordLocalHitTarget(plr, hum, bodyPart)

			if not config.hitNotifications.enabled then
				return
			end

			if not shouldNotifyPlayerHit(plr) then
				return
			end

			enqueueHitNotifResolve(plr, hum, bodyPart)
		end

		ragebot.notifyProjectileImpact = notifyProjectileImpact
		ragebot.getPlayerFromHitPart = getPlayerFromHitPart

		local function onTargetHealthChanged(plr, newHp)
			if not config.hitNotifications.enabled then
				return
			end
			if hitNotifHpTrack[plr] == nil then
				hitNotifHpTrack[plr] = newHp
				return
			end
			if newHp > (hitNotifHpTrack[plr] or newHp) then
				hitNotifHpTrack[plr] = newHp
			end
		end

		local function unbindHitNotifPlayer(plr)
			if hitNotifHumConn[plr] then
				hitNotifHumConn[plr]:Disconnect()
				hitNotifHumConn[plr] = nil
			end
			if hitNotifCharConn[plr] then
				hitNotifCharConn[plr]:Disconnect()
				hitNotifCharConn[plr] = nil
			end
			hitNotifHpTrack[plr] = nil
			hitNotifResolveQueues[plr] = nil
			hitNotifResolveBusy[plr] = nil
		end

		local function bindHitNotifCharacter(plr, char)
			if plr == player or not char then
				return
			end
			if hitNotifHumConn[plr] then
				hitNotifHumConn[plr]:Disconnect()
				hitNotifHumConn[plr] = nil
			end
			local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 8)
			if not hum then
				return
			end
			hitNotifHpTrack[plr] = hum.Health
			hitNotifHumConn[plr] = Port.Track(hum.HealthChanged:Connect(function(newHp)
				local localHit = localHitTargets and localHitTargets[hum]
				if newHp <= 0 and localHit and localHit.plr and localHit.plr ~= player and not config.hitNotifications.enabled then
					local tryKill2 = getgenv().InstanceTryKillSound
					if tryKill2 then
						tryKill2(localHit.plr, hitNotifHpTrack[plr] or 0, newHp)
					end
					if localHitTargets then
						localHitTargets[hum] = nil
					end
				end

				if not config.hitNotifications.enabled then
					local last = hitNotifHpTrack[plr]
					if last == nil or newHp > last then
						hitNotifHpTrack[plr] = newHp
					end
					return
				end

				local last = hitNotifHpTrack[plr]
				if last == nil then
					hitNotifHpTrack[plr] = newHp
					return
				end

				if newHp < last - 0.01 then
					if shouldNotifyPlayerHit(plr) then
						local bodyPart = ragePerf.hitPartByPlayer[plr] or config.target.hitpart or "Body"
						pushHitNotification(plr.Name, last - newHp, bodyPart)
						ragePerf.lastHitAtByPlayer[plr] = tick()
					end
					if newHp <= 0 then
						local tryKill = getgenv().InstanceTryKillSound
						if tryKill then
							tryKill(plr, last, newHp)
						end
					end
					hitNotifHpTrack[plr] = newHp
				elseif newHp > last then
					hitNotifHpTrack[plr] = newHp
				end
			end))

			Port.Track(hum.Died:Connect(function()
				local last = hitNotifHpTrack[plr]
				local tryKill = getgenv().InstanceTryKillSound
				if tryKill and last and last > 0 then
					tryKill(plr, last, 0)
				end

				local localHit = localHitTargets and localHitTargets[hum]
				if localHit then
					if not config.hitNotifications.enabled then
						local tryKill2 = getgenv().InstanceTryKillSound
						if tryKill2 and localHit.plr and localHit.plr ~= player then
							tryKill2(localHit.plr, last or 0, 0)
						end
					end
					if localHitTargets then
						localHitTargets[hum] = nil
					end
				end
			end))
		end

		local function bindHitNotifPlayer(plr)
			if plr == player then
				return
			end
			if hitNotifCharConn[plr] then
				hitNotifCharConn[plr]:Disconnect()
			end
			hitNotifCharConn[plr] = Port.Track(plr.CharacterAdded:Connect(function(char)
				bindHitNotifCharacter(plr, char)
			end))
			if plr.Character then
				bindHitNotifCharacter(plr, plr.Character)
			end
		end

		Port.Track(players.PlayerAdded:Connect(bindHitNotifPlayer))
		Port.Track(players.PlayerRemoving:Connect(unbindHitNotifPlayer))
		for _, plr in players:GetPlayers() do
			bindHitNotifPlayer(plr)
		end

		local function updateHitNotifications(dt)
			local hn = config.hitNotifications
			if not hn.enabled or shouldSuppressGameplayOverlays() then
				hitNotifRoot.Visible = false
				if not hn.enabled then
					for i = #hitNotifEntries, 1, -1 do
						removeHitNotifEntry(i)
					end
				end
				return
			end

			pollHitNotifHealth()

			hitNotifRoot.Visible = #hitNotifEntries > 0
			applyHitNotifRootPosition()

			dt = dt or 0
			local now = tick()
			local inDur = math.clamp(hn.animInDuration or 0.52, 0.15, 2)
			local outDur = math.clamp(hn.animOutDuration or 0.38, 0.15, 2)
			local totalDur = hn.duration or 3
			local gap = hn.stackGap or 6
			local inStyle = hn.inAnimation or "fade bounce"
			local outStyle = hn.outAnimation or "fade"

			local y = 0
			for _, entry in ipairs(hitNotifEntries) do
				entry.targetY = y
				entry.displayY = entry.displayY or y
				if dt > 0 then
					entry.displayY = entry.displayY + (entry.targetY - entry.displayY) * (1 - math.exp(-dt * 14))
				else
					entry.displayY = entry.targetY
				end
				y = y + (entry.boxH or 26) + gap
			end

			local i = 1
			while i <= #hitNotifEntries do
				local entry = hitNotifEntries[i]
				local age = now - entry.start

				if entry.phase == "in" then
					local t = (now - entry.phaseStart) / inDur
					if t >= 1 then
						entry.phase = "hold"
						entry.phaseStart = now
						t = 1
					end
					local a, ox, oy, sc = sampleHitNotifAnim(inStyle, t, false)
					applyHitNotifVisual(entry, a, ox, oy, sc)
				elseif entry.phase == "hold" then
					applyHitNotifVisual(entry, 1, 0, 0, 1)
					if age >= totalDur - outDur then
						entry.phase = "out"
						entry.phaseStart = now
					end
				elseif entry.phase == "out" then
					local t = (now - entry.phaseStart) / outDur
					if t >= 1 then
						removeHitNotifEntry(i)
						continue
					end
					local a, ox, oy, sc = sampleHitNotifAnim(outStyle, t, true)
					applyHitNotifVisual(entry, a, ox, oy, sc)
				else
					entry.phase = "in"
					entry.phaseStart = now
				end

				i = i + 1
			end
		end

		ragebot.updateHitNotifications = updateHitNotifications
		ragebot.clearHitNotifications = function()
			for i = #hitNotifEntries, 1, -1 do
				removeHitNotifEntry(i)
			end
			if hitNotifRoot then
				hitNotifRoot.Visible = false
			end
		end
		ragebot.hitNotifAnimStyles = HIT_NOTIF_ANIM_STYLES
		ragebot.applyHitNotifRootPosition = applyHitNotifRootPosition

		-- Driven by the ragebot HUD loop in the original script.
		local hitNotifAnimLast = tick()
		Port.Track(game:GetService("RunService").RenderStepped:Connect(function()
			local now = tick()
			local dt = math.clamp(now - hitNotifAnimLast, 0, 0.05)
			hitNotifAnimLast = now
			if config.hitNotifications.enabled or #hitNotifEntries > 0 then
				updateHitNotifications(dt)
			end
		end))
	end

	-- Feedback: hit notifications
	do
		local hitNotifTab = Port.Section(FeedbackTab, "Hit Notifications")
		local rbHitCfg = ragebot.config.hitNotifications

		local hitNotificationsToggle = hitNotifTab:AddToggle('HitNotifications', {
			Text = 'hit notifications',
			Default = false,
			Callback = function(val)
				rbHitCfg.enabled = val
				if not val and ragebot.clearHitNotifications then
					ragebot.clearHitNotifications()
				end
			end
		}):AddColorPicker('HitNotificationsColor', {
			Default = rbHitCfg.color,
			Title = 'text color',
			Callback = function(val)
				rbHitCfg.color = val
			end
		})

		local hitNotifDepBox = hitNotifTab:AddDependencyBox()
		hitNotifDepBox:AddSlider('HitNotifDuration', {
			Text = 'duration',
			Default = rbHitCfg.duration,
			Min = 1,
			Max = 8,
			Rounding = 1,
			Compact = true,
			Suffix = 's',
			Callback = function(val)
				rbHitCfg.duration = val
			end
		})
		hitNotifDepBox:AddSlider('HitNotifTextSize', {
			Text = 'text size',
			Default = rbHitCfg.textSize,
			Min = 10,
			Max = 24,
			Rounding = 0,
			Compact = true,
			Callback = function(val)
				rbHitCfg.textSize = val
			end
		})
		hitNotifDepBox:AddSlider('HitNotifMaxVisible', {
			Text = 'max on screen',
			Default = rbHitCfg.maxVisible,
			Min = 1,
			Max = 25,
			Rounding = 0,
			Compact = true,
			Callback = function(val)
				rbHitCfg.maxVisible = math.clamp(val, 1, 25)
			end
		})
		local hitNotifPositionDropdown = hitNotifDepBox:AddDropdown('HitNotifPosition', {
			Text = 'position',
			Default = rbHitCfg.position or 'Top Left',
			Values = {
				'Top Left', 'Top Center', 'Top Right',
				'Center Left', 'Center', 'Center Right',
				'Bottom Left', 'Bottom Center', 'Bottom Right',
				'Custom',
			},
			Callback = function(val)
				rbHitCfg.position = val
				if ragebot.applyHitNotifRootPosition then
					ragebot.applyHitNotifRootPosition()
				end
				if Library.UpdateDependencyBoxes then
					Library:UpdateDependencyBoxes()
				end
			end
		})

		local hitNotifPosDepBox = hitNotifDepBox:AddDependencyBox()
		hitNotifPosDepBox:AddSlider('HitNotifOffsetX', {
			Text = 'custom x',
			Default = rbHitCfg.offsetX,
			Min = 0,
			Max = 1200,
			Rounding = 0,
			Compact = true,
			Callback = function(val)
				rbHitCfg.offsetX = val
				if ragebot.applyHitNotifRootPosition then
					ragebot.applyHitNotifRootPosition()
				end
			end
		})
		hitNotifPosDepBox:AddSlider('HitNotifOffsetY', {
			Text = 'custom y',
			Default = rbHitCfg.offsetY,
			Min = 0,
			Max = 800,
			Rounding = 0,
			Compact = true,
			Callback = function(val)
				rbHitCfg.offsetY = val
				if ragebot.applyHitNotifRootPosition then
					ragebot.applyHitNotifRootPosition()
				end
			end
		})
		hitNotifPosDepBox:SetupDependencies({
			{ hitNotifPositionDropdown, 'Custom' },
		})

		hitNotifDepBox:AddSlider('HitNotifStackGap', {
			Text = 'stack gap',
			Default = rbHitCfg.stackGap,
			Min = 2,
			Max = 24,
			Rounding = 0,
			Compact = true,
			Callback = function(val)
				rbHitCfg.stackGap = val
			end
		})
		local hitNotifAnimStyles = ragebot.hitNotifAnimStyles or {
			"fade", "slide left", "slide right", "slide down", "bounce", "fade bounce", "scale",
		}
		hitNotifDepBox:AddDropdown('HitNotifInAnim', {
			Text = 'in animation',
			Default = rbHitCfg.inAnimation,
			Values = hitNotifAnimStyles,
			Callback = function(val)
				rbHitCfg.inAnimation = val
			end
		})
		hitNotifDepBox:AddDropdown('HitNotifOutAnim', {
			Text = 'out animation',
			Default = rbHitCfg.outAnimation,
			Values = hitNotifAnimStyles,
			Callback = function(val)
				rbHitCfg.outAnimation = val
			end
		})
		hitNotifDepBox:AddSlider('HitNotifInSpeed', {
			Text = 'in speed',
			Default = rbHitCfg.animInDuration,
			Min = 0.15,
			Max = 1.5,
			Rounding = 2,
			Compact = true,
			Suffix = 's',
			Callback = function(val)
				rbHitCfg.animInDuration = val
			end
		})
		hitNotifDepBox:AddSlider('HitNotifOutSpeed', {
			Text = 'out speed',
			Default = rbHitCfg.animOutDuration,
			Min = 0.15,
			Max = 1.5,
			Rounding = 2,
			Compact = true,
			Suffix = 's',
			Callback = function(val)
				rbHitCfg.animOutDuration = val
			end
		})
		hitNotifDepBox:SetupDependencies({
			{ hitNotificationsToggle, true }
		})
	end

	-- Character: profile / name / outfit / fps / ping / region spoof, movement, self material
	do
		local frame = Port.Section(CharacterTab, "Profile Spoof")

		local config = {}
		if not config.profile then
			config.profile = {
				level = { enabled = false, value = 9999 },
				winstreak = { enabled = false, value = 9999 }
			}
		end

		-- Player spoofer. Values are "guarded" (the way the other hub does it): the spoofed
		-- value is written to the player's attribute / leaderstat, and whenever the game
		-- changes it back it is written again, so it sticks. The real value is remembered
		-- and restored when a spoof is switched off or the hub is unloaded. The same
		-- fields can be spoofed for you ("local") and for every other player ("others").
		local Players = game:GetService("Players")
		local me = Players.LocalPlayer
		local spoofs = {}
		for _, scope in { "local", "others" } do
			spoofs[scope] = {
				level      = { enabled = false, value = 9999 },
				streak     = { enabled = false, value = 9999 },
				elo        = { enabled = false, value = 3600 },
				status     = { enabled = false, value = "Prime" },
				influencer = { enabled = false },
				employee   = { enabled = false },
				team       = { enabled = false },
			}
		end
		-- level / streak keep their old config entries, which the flags below fill in.
		spoofs["local"].level, spoofs["local"].streak = config.profile.level, config.profile.winstreak

		local guards = setmetatable({}, { __mode = "k" }) -- player -> { [key] = guard }
		local function guardFor(player, key, read, write, signal)
			local byKey = guards[player]
			if not byKey then
				byKey = {}
				guards[player] = byKey
			end
			local guard = byKey[key]
			if guard then
				return guard
			end
			guard = { original = read(), spoofed = nil, writing = false }
			guard.connection = signal():Connect(function()
				if guard.writing then return end
				guard.original = read()
				if guard.spoofed ~= nil then
					guard.writing = true
					write(guard.spoofed)
					guard.writing = false
				end
			end)
			guard.write = write
			byKey[key] = guard
			return guard
		end
		local function release(player, key)
			local byKey = guards[player]
			local guard = byKey and byKey[key]
			if not guard then return end
			guard.connection:Disconnect()
			byKey[key] = nil
			guard.writing = true
			pcall(guard.write, guard.original)
			guard.writing = false
		end
		local function setAttribute(player, name, enabled, value)
			if not enabled or value == nil then
				release(player, "a:" .. name)
				return
			end
			local guard = guardFor(player, "a:" .. name,
				function() return player:GetAttribute(name) end,
				function(v) player:SetAttribute(name, v) end,
				function() return player:GetAttributeChangedSignal(name) end)
			guard.spoofed = value
			guard.writing = true
			player:SetAttribute(name, value)
			guard.writing = false
		end
		local function setLeaderstat(player, name, enabled, value)
			local stats = player:FindFirstChild("CustomLeaderstats")
			local object = stats and stats:FindFirstChild(name)
			if not object or not object:IsA("ValueBase") then
				return
			end
			if not enabled or value == nil then
				release(player, "s:" .. name)
				return
			end
			local guard = guardFor(player, "s:" .. name,
				function() return object.Value end,
				function(v) object.Value = v end,
				function() return object:GetPropertyChangedSignal("Value") end)
			guard.spoofed = value
			guard.writing = true
			object.Value = value
			guard.writing = false
		end

		local function applyPlayer(player)
			local set = spoofs[player == me and "local" or "others"]
			setAttribute(player, "Level", set.level.enabled, set.level.value)
			setLeaderstat(player, "Level", set.level.enabled, set.level.value)
			setAttribute(player, "StatisticDuelsWinStreak", set.streak.enabled, set.streak.value)
			setLeaderstat(player, "Win Streak", set.streak.enabled, set.streak.value)
			setAttribute(player, "DisplayELO", set.elo.enabled, set.elo.value)
			setLeaderstat(player, "Current ELO", set.elo.enabled, set.elo.value)
			setAttribute(player, "PlayerStatus", set.status.enabled, set.status.value)
			setAttribute(player, "IsInfluencer", set.influencer.enabled, true)
			setAttribute(player, "IsRobloxEmployee", set.employee.enabled, true)
			setAttribute(player, "GroupRank", set.team.enabled, 255)
		end
		local function applyAll()
			for _, player in ipairs(Players:GetPlayers()) do
				pcall(applyPlayer, player)
			end
		end
		Port.Track(Players.PlayerAdded:Connect(function(player)
			task.delay(1, function() pcall(applyPlayer, player) end) -- leaderstats appear a moment later
		end))
		Port.Track(Players.PlayerRemoving:Connect(function(player)
			guards[player] = nil
		end))
		Port.OnUnload(function()
			for player, byKey in pairs(guards) do
				for key in pairs(byKey) do
					release(player, key)
				end
			end
		end)
		-- Leaderstat folders show up after the player does: re-apply now and then.
		task.spawn(function()
			while not Port.Unloaded do
				task.wait(3)
				applyAll()
			end
		end)

		local function spoofControls(scope, prefix, title)
			local set = spoofs[scope]
			local function numberField(key, flagStem, label, default)
				frame:AddToggle(prefix .. flagStem .. "Spoof", {
					Text = label, Default = false,
					Callback = function(on) set[key].enabled = on; applyAll() end,
				})
				frame:AddInput(prefix .. flagStem .. "Value", {
					Text = label, Default = tostring(default), Numeric = true, Finished = false, Placeholder = tostring(default),
					Callback = function(text) set[key].value = tonumber(text) or default; applyAll() end,
				})
			end
			return numberField
		end

		-- You (flags keep the old names so saved configs still load).
		local localField = spoofControls("local", "", "")
		frame:AddToggle("LevelSpoof", {
			Tooltip = "Only you see the spoofed values",
			Text = "level", Default = false,
			Callback = function(val) config.profile.level.enabled = val; applyAll() end,
		})
		frame:AddInput("LevelValue", {
			Text = "level", Default = "9999", Numeric = true, Finished = false, Placeholder = "9999",
			Callback = function(val) config.profile.level.value = tonumber(val) or 9999; applyAll() end,
		})
		frame:AddToggle("WinStreakSpoof", {
			Text = "win streak", Default = false,
			Callback = function(val) config.profile.winstreak.enabled = val; applyAll() end,
		})
		frame:AddInput("WinStreakValue", {
			Text = "win streak", Default = "9999", Numeric = true, Finished = false, Placeholder = "9999",
			Callback = function(val) config.profile.winstreak.value = tonumber(val) or 9999; applyAll() end,
		})
		localField("elo", "Elo", "ranked elo", 3600)
		frame:AddToggle("StatusSpoof", {
			Text = "nametag status", Default = false,
			Callback = function(on) spoofs["local"].status.enabled = on; applyAll() end,
		})
		frame:AddInput("StatusValue", {
			Text = "nametag status", Default = "Prime", Placeholder = "Prime", Finished = true,
			Callback = function(text) spoofs["local"].status.value = (text ~= "" and text) or "Prime"; applyAll() end,
		})
		for key, label in { influencer = "influencer badge", employee = "roblox employee badge", team = "team badge" } do
			frame:AddToggle("Spoof_" .. key, {
				Text = label, Default = false,
				Callback = function(on) spoofs["local"][key].enabled = on; applyAll() end,
			})
		end

		-- Other players (what you see them as).
		local otherField = spoofControls("others", "Other", "")
		otherField("level", "Level", "others: level", 0)
		otherField("streak", "Streak", "others: win streak", 0)
		otherField("elo", "Elo", "others: ranked elo", 0)
		frame:AddToggle("OtherStatusSpoof", {
			Text = "others: nametag status", Default = false,
			Callback = function(on) spoofs["others"].status.enabled = on; applyAll() end,
		})
		frame:AddInput("OtherStatusValue", {
			Text = "others: nametag status", Default = "Prime", Placeholder = "Prime", Finished = true,
			Callback = function(text) spoofs["others"].status.value = (text ~= "" and text) or "Prime"; applyAll() end,
		})

		-- Name / display name / avatar spoofing for you and for every other player, the way
		-- the other hub does it: the real names are replaced in the text of the game's UI
		-- (and in overhead name tags), character models get the spoofed user's clothes and
		-- accessories (the originals are stashed and put back), the game's own avatar loader
		-- is pointed at the spoofed user, and avatar thumbnails in the UI are swapped.
		-- Only you see any of it; everything is undone when a spoof is turned off.
		MD3.LYIdentitySpoof = function(frame)
			local Players = game:GetService("Players")
			local me = Players.LocalPlayer
			local cfg = {}
			for _, scope in { "local", "others" } do
				cfg[scope] = {
					name    = { enabled = false, value = "Player" },
					display = { enabled = false, value = "Player" },
					avatar  = { enabled = false, value = "1" },
					verified = { enabled = false },
					premium  = { enabled = false },
				}
			end
			local function scopeOf(player)
				return player == me and "local" or "others"
			end
			-- Roblox's verified / premium badge glyphs, added after the name.
			local BADGE_VERIFIED = utf8.char(0xE000)
			local BADGE_PREMIUM = utf8.char(0xE001)
			local function badgeSuffix(set)
				return (set.premium.enabled and BADGE_PREMIUM or "") .. (set.verified.enabled and BADGE_VERIFIED or "")
			end
			local function presented(player)
				local set = cfg[scopeOf(player)]
				local name = set.name.enabled and set.name.value ~= "" and set.name.value or player.Name
				local display = set.display.enabled and set.display.value ~= "" and set.display.value or player.DisplayName
				local suffix = badgeSuffix(set)
				if suffix ~= "" then
					name, display = name .. suffix, display .. suffix
				end
				return name, display
			end
			MD3.LYPresentedName = function()
				local _, display = presented(me)
				return display
			end
			local function avatarId(player)
				local set = cfg[scopeOf(player)].avatar
				if set.enabled then
					return tonumber(set.value)
				end
				return nil
			end

			-- Text: replace real names with the presented ones in labels ---------------
			local texts = setmetatable({}, { __mode = "k" }) -- object -> { original, shown }
			local hooks = setmetatable({}, { __mode = "k" })
			local function plainReplace(text, find, replace)
				if find == "" or find == replace then return text end
				local out, position = {}, 1
				while true do
					local from, to = text:find(find, position, true)
					if not from then break end
					table.insert(out, text:sub(position, from - 1))
					table.insert(out, replace)
					position = to + 1
				end
				if position == 1 then return text end
				table.insert(out, text:sub(position))
				return table.concat(out)
			end
			local function spoofText(text)
				for _, player in ipairs(Players:GetPlayers()) do
					local name, display = presented(player)
					text = plainReplace(text, player.DisplayName, display)
					text = plainReplace(text, player.Name, name)
				end
				return text
			end
			local function anyNameSpoof()
				for _, scope in { "local", "others" } do
					local set = cfg[scope]
					if set.name.enabled or set.display.enabled or set.verified.enabled or set.premium.enabled then return true end
				end
				return false
			end
			local function isOurs(inst)
				return Window.Gui ~= nil and inst:IsDescendantOf(Window.Gui)
			end
			local function syncText(inst)
				if isOurs(inst) then return end
				local record = texts[inst]
				if not record then
					record = {}
					texts[inst] = record
				end
				local now = inst.Text
				if record.shown == nil or now ~= record.shown then
					record.original = now
				end
				local shown = anyNameSpoof() and spoofText(record.original) or record.original
				record.shown = shown
				if inst.Text ~= shown then
					inst.Text = shown
				end
			end
			local function hookText(inst)
				if hooks[inst] or not (inst:IsA("TextLabel") or inst:IsA("TextButton")) then return end
				hooks[inst] = inst:GetPropertyChangedSignal("Text"):Connect(function()
					pcall(syncText, inst)
				end)
				pcall(syncText, inst)
			end
			local roots = {}
			local function watchRoot(root)
				if not root or roots[root] then return end
				roots[root] = true
				Port.Track(root.DescendantAdded:Connect(function(inst)
					if anyNameSpoof() then task.defer(hookText, inst) end
				end))
			end
			local function sweepText()
				local gui = me:FindFirstChild("PlayerGui")
				watchRoot(gui)
				watchRoot(workspace) -- new name tags only (event); the map itself is never scanned
				local scan = { gui }
				for _, other in ipairs(Players:GetPlayers()) do
					if other.Character then table.insert(scan, other.Character) end
				end
				local count = 0
				for _, root in scan do
					if root then
						for _, inst in ipairs(root:GetDescendants()) do
							if inst:IsA("TextLabel") or inst:IsA("TextButton") then
								if anyNameSpoof() then
									hookText(inst)
								else
									local connection = hooks[inst]
									if connection then
										connection:Disconnect()
										hooks[inst] = nil
										pcall(syncText, inst) -- restores the original
										texts[inst] = nil
									end
								end
							end
							count += 1
							if count % 400 == 0 then task.wait() end
						end
					end
				end
			end
			-- Humanoid overhead names.
			local displayNames = setmetatable({}, { __mode = "k" })
			local function syncHumanoids()
				for _, player in ipairs(Players:GetPlayers()) do
					local character = player.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if humanoid then
						local _, display = presented(player)
						local set = cfg[scopeOf(player)]
						local spoofing = set.display.enabled or set.verified.enabled or set.premium.enabled
						if spoofing then
							if displayNames[humanoid] == nil then displayNames[humanoid] = humanoid.DisplayName end
							if humanoid.DisplayName ~= display then humanoid.DisplayName = display end
						elseif displayNames[humanoid] ~= nil then
							humanoid.DisplayName = displayNames[humanoid]
							displayNames[humanoid] = nil
						end
					end
				end
			end

			-- Avatar decorator: any character model of a player gets the spoofed user's look.
			-- Per model: the originals (accessories, clothes, face decals) are stashed and
			-- anything the game adds later is stashed too; the spoofed user's accessories are
			-- welded on through their attachments, clothes / body colors / head are copied; all
			-- of it is undone on restore. Descriptions and source models are cached per user.
			local STASH = { "Accessory", "Shirt", "Pants", "ShirtGraphic" }
			local HEAD_DECOR = { "Decal", "SurfaceAppearance", "SpecialMesh" }
			local function isAny(inst, classes)
				for _, class in classes do
					if inst:IsA(class) then return true end
				end
				return false
			end
			local descriptions = {}  -- userId -> HumanoidDescription | false
			local sources = {}       -- userId:rig -> model | false
			local function sourceModel(userId, rigType)
				local key = tostring(userId) .. ":" .. tostring(rigType)
				if sources[key] ~= nil then return sources[key] or nil end
				if descriptions[userId] == nil then
					local ok, description = pcall(function()
						return Players:GetHumanoidDescriptionFromUserIdAsync(userId)
					end)
					descriptions[userId] = ok and description or false
				end
				sources[key] = false
				if descriptions[userId] then
					local made, model = pcall(function()
						if Players.CreateHumanoidModelFromDescriptionAsync then
							return Players:CreateHumanoidModelFromDescriptionAsync(descriptions[userId], rigType)
						end
						return Players:CreateHumanoidModelFromDescription(descriptions[userId], rigType)
					end)
					if made and model then sources[key] = model end
				end
				return sources[key] or nil
			end
			local function firstAttachment(part)
				for _, child in ipairs(part:GetChildren()) do
					if child:IsA("Attachment") then return child end
				end
				return nil
			end
			local function findAttachment(character, name)
				for _, child in ipairs(character:GetChildren()) do
					if child:IsA("BasePart") then
						local attachment = child:FindFirstChild(name)
						if attachment and attachment:IsA("Attachment") then return attachment end
					end
				end
				return nil
			end
			-- Welds an accessory onto the character through its attachments (no Humanoid needed).
			local function attachAccessory(accessory, character)
				local handle = accessory:FindFirstChild("Handle")
				if handle and handle:IsA("BasePart") then
					for _, child in ipairs(handle:GetChildren()) do
						if child:IsA("Weld") or child:IsA("WeldConstraint") or child:IsA("ManualWeld") then
							child:Destroy()
						end
					end
					local own = firstAttachment(handle)
					local target = own and findAttachment(character, own.Name)
					if own and target then
						handle.Anchored = false
						local weld = Instance.new("Weld")
						weld.Name = "AccessoryWeld"
						weld.Part0, weld.Part1 = handle, target.Parent
						weld.C0, weld.C1 = own.CFrame, target.CFrame
						weld.Parent = handle
					end
				end
				accessory.Parent = character
			end
			local decorated = setmetatable({}, { __mode = "k" }) -- model -> state
			local function restoreModel(model)
				local state = decorated[model]
				if not state then return end
				decorated[model] = nil
				state.cancelled = true
				for _, connection in ipairs(state.connections) do connection:Disconnect() end
				for _, clone in ipairs(state.clones) do pcall(clone.Destroy, clone) end
				if model.Parent then
					for _, item in ipairs(state.stashed) do
						if item:IsA("Accessory") then attachAccessory(item, model) else item.Parent = model end
					end
					for part, color in pairs(state.colors) do
						if part.Parent then part.Color = color end
					end
					local head = model:FindFirstChild("Head")
					if head then
						for _, item in ipairs(state.headStashed) do item.Parent = head end
						if state.head then
							head.Transparency = state.head.Transparency
							if state.head.MeshId and head:IsA("MeshPart") then
								head.MeshId, head.TextureID = state.head.MeshId, state.head.TextureID
							end
						end
					end
				else
					for _, item in ipairs(state.stashed) do pcall(item.Destroy, item) end
					for _, item in ipairs(state.headStashed) do pcall(item.Destroy, item) end
				end
			end
			-- Waits (up to `timeout`) for the model to have what the source has: the body
			-- parts, and for every accessory the part its attachment sits on.
			local function modelReady(model, source)
				for _, child in ipairs(source:GetChildren()) do
					if child:IsA("BasePart") and not model:FindFirstChild(child.Name) then return false end
					if child:IsA("Accessory") then
						local handle = child:FindFirstChild("Handle")
						local own = handle and handle:IsA("BasePart") and firstAttachment(handle)
						if own and not findAttachment(model, own.Name) then return false end
					end
				end
				return true
			end
			local function decorate(model, userId)
				restoreModel(model)
				local state = { clones = {}, stashed = {}, headStashed = {}, colors = {}, connections = {}, cancelled = false }
				decorated[model] = state
				local humanoid = model:FindFirstChildOfClass("Humanoid") or model:WaitForChild("Humanoid", 10)
				if state.cancelled or not humanoid then return end
				local source = sourceModel(userId, humanoid.RigType)
				if state.cancelled or not source then return end
				local waited = 0
				while not modelReady(model, source) and waited < 10 and not state.cancelled and model.Parent do
					task.wait(0.1)
					waited += 0.1
				end
				if state.cancelled or not model.Parent then return end
				local spoofed = {}
				local function stash(child)
					if spoofed[child] or child.Parent ~= model then return end
					child.Parent = nil
					table.insert(state.stashed, child)
				end
				-- Stash the originals now and whatever the game adds later.
				for _, child in ipairs(model:GetChildren()) do
					if isAny(child, STASH) then stash(child) end
				end
				table.insert(state.connections, model.ChildAdded:Connect(function(child)
					if isAny(child, STASH) and not spoofed[child] then
						task.defer(stash, child)
					end
				end))
				for _, item in ipairs(source:GetChildren()) do
					if item:IsA("Accessory") then
						local clone = item:Clone()
						spoofed[clone] = true
						table.insert(state.clones, clone)
						attachAccessory(clone, model)
					elseif item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") then
						local clone = item:Clone()
						spoofed[clone] = true
						table.insert(state.clones, clone)
						clone.Parent = model
					elseif item:IsA("BasePart") then
						local target = model:FindFirstChild(item.Name)
						if target and target:IsA("BasePart") then
							state.colors[target] = target.Color
							target.Color = item.Color
						end
					end
				end
				local head, from = model:FindFirstChild("Head"), source:FindFirstChild("Head")
				if head and from and head:IsA("BasePart") and from:IsA("BasePart") then
					for _, child in ipairs(head:GetChildren()) do
						if isAny(child, HEAD_DECOR) then
							child.Parent = nil
							table.insert(state.headStashed, child)
						end
					end
					for _, child in ipairs(from:GetChildren()) do
						if isAny(child, HEAD_DECOR) then
							local clone = child:Clone()
							table.insert(state.clones, clone)
							clone.Parent = head
						end
					end
					state.head = { Transparency = head.Transparency }
					head.Transparency = from.Transparency
					if head:IsA("MeshPart") and from:IsA("MeshPart") then
						state.head.MeshId, state.head.TextureID = head.MeshId, head.TextureID
						head.MeshId, head.TextureID = from.MeshId, from.TextureID
					end
				end
			end
			-- Every character model that belongs to a player (their Character, plus models the
			-- game builds for matches, found by name).
			local modelOwner = setmetatable({}, { __mode = "k" }) -- model -> player
			local function playerForModel(model)
				for _, player in ipairs(Players:GetPlayers()) do
					if player.Character == model or model.Name == player.Name then return player end
				end
				return nil
			end
			local function trackModel(model)
				if not model:IsA("Model") or modelOwner[model] then return end
				local player = playerForModel(model)
				if player then
					modelOwner[model] = player
					local userId = avatarId(player)
					if userId then task.spawn(decorate, model, userId) end
				end
			end
			local function syncAvatar(player)
				if player.Character then trackModel(player.Character) end
				for model, owner in pairs(modelOwner) do
					if owner == player and model.Parent then
						local userId = avatarId(player)
						if userId then
							if not decorated[model] or decorated[model].userId ~= userId then
								task.spawn(function()
									decorate(model, userId)
									if decorated[model] then decorated[model].userId = userId end
								end)
							end
						else
							restoreModel(model)
						end
					end
				end
			end
			local function bindPlayer(player)
				Port.Track(player.CharacterAdded:Connect(function(character)
					task.wait(0.6)
					modelOwner[character] = nil
					trackModel(character)
				end))
			end
			for _, player in ipairs(Players:GetPlayers()) do bindPlayer(player) end
			Port.Track(Players.PlayerAdded:Connect(bindPlayer))
			Port.Track(workspace.DescendantAdded:Connect(function(inst)
				if inst:IsA("Humanoid") and inst.Parent then
					task.defer(function()
						if inst.Parent then trackModel(inst.Parent) end
					end)
				end
			end))
			for _, child in ipairs(workspace:GetChildren()) do
				if child:IsA("Model") then trackModel(child) end
			end

			-- The game's own avatar loader (spectated / preloaded duelers) ------------------
			local loaderRestore
			local function installLoader()
				if loaderRestore or not (debug and debug.getupvalues and debug.setupvalue) then return end
				local dueler = MD3.LYRequire and MD3.LYRequire("ClientDueler")
				local method = type(dueler) == "table" and rawget(dueler, "_PreloadCharacterModel")
				if type(method) ~= "function" then return end
				local index, original
				for slot, value in debug.getupvalues(method) do
					if typeof(value) == "Instance" and pcall(value.IsA, value, "Players") and value:IsA("Players") then
						index, original = slot, value
						break
					end
				end
				if not index then return end
				local stand = setmetatable({}, { __index = function(_, key)
					if key == "GetHumanoidDescriptionFromUserIdAsync" then
						return function(_, userId)
							for _, player in ipairs(Players:GetPlayers()) do
								if player.UserId == userId and avatarId(player) then
									return Players:GetHumanoidDescriptionFromUserIdAsync(avatarId(player))
								end
							end
							return Players:GetHumanoidDescriptionFromUserIdAsync(userId)
						end
					end
					local value = Players[key]
					if type(value) == "function" then
						return function(_, ...) return value(Players, ...) end
					end
					return value
				end })
				if pcall(debug.setupvalue, method, index, stand) then
					loaderRestore = function() pcall(debug.setupvalue, method, index, original) end
				end
			end

			-- Thumbnails in the UI ------------------------------------------------------------
			local images = setmetatable({}, { __mode = "k" })
			local function swapImage(text)
				for _, player in ipairs(Players:GetPlayers()) do
					local target = avatarId(player)
					if target then
						local id = tostring(player.UserId)
						text = text:gsub("([%?&]id=)" .. id, "%1" .. tostring(target))
						text = text:gsub("(userId=)" .. id, "%1" .. tostring(target))
					end
				end
				return text
			end
			local function sweepImages()
				local gui = me:FindFirstChild("PlayerGui")
				if not gui then return end
				local anyAvatar = cfg["local"].avatar.enabled or cfg["others"].avatar.enabled
				local count = 0
				for _, inst in ipairs(gui:GetDescendants()) do
					if (inst:IsA("ImageLabel") or inst:IsA("ImageButton")) and not isOurs(inst) then
						local record = images[inst]
						local image = inst.Image
						if record and image ~= record.shown then record.original = image end
						if anyAvatar then
							if not record then
								record = { original = image }
								images[inst] = record
							end
							local shown = swapImage(record.original)
							record.shown = shown
							if inst.Image ~= shown then inst.Image = shown end
						elseif record then
							inst.Image = record.original
							images[inst] = nil
						end
					end
					count += 1
					if count % 400 == 0 then task.wait() end
				end
			end

			local function refresh()
				pcall(sweepText)
				pcall(syncHumanoids)
				for _, player in ipairs(Players:GetPlayers()) do pcall(syncAvatar, player) end
				if cfg["local"].avatar.enabled or cfg["others"].avatar.enabled then pcall(installLoader) end
				pcall(sweepImages)
			end
			local refreshing = false
			local function requestRefresh()
				if refreshing then return end
				refreshing = true
				task.defer(function()
					refresh()
					refreshing = false
				end)
			end
			task.spawn(function()
				while not Port.Unloaded do
					task.wait(4)
					if anyNameSpoof() or cfg["local"].avatar.enabled or cfg["others"].avatar.enabled then
						pcall(function() pcall(sweepText); pcall(syncHumanoids); pcall(sweepImages) end)
					end
				end
			end)
			Port.OnUnload(function()
				for _, scope in { "local", "others" } do
					for _, key in { "name", "display", "avatar", "verified", "premium" } do cfg[scope][key].enabled = false end
				end
				pcall(refresh)
				if loaderRestore then loaderRestore() end
			end)

			-- Controls ---------------------------------------------------------------------
			local function field(prefix, key, label, target, default, numeric)
				frame:AddToggle(prefix .. key .. "Spoof", {
					Text = label, Default = false,
					Callback = function(on) target.enabled = on; requestRefresh() end,
				})
				frame:AddInput(prefix .. key .. "Value", {
					Text = label, Default = default, Placeholder = default,
					Numeric = numeric == true, Finished = true,
					Callback = function(value) target.value = (value ~= "" and value) or default; requestRefresh() end,
				})
			end
			local mine = cfg["local"]
			field("My", "Name", "my name", mine.name, "Player")
			field("My", "Display", "my display name", mine.display, "Player")
			field("My", "Avatar", "my avatar (user id)", mine.avatar, "1", true)
			local function badge(prefix, key, label, target, description)
				frame:AddToggle(prefix .. key .. "Spoof", {
					Text = label, Tooltip = description, Default = false,
					Callback = function(on) target.enabled = on; requestRefresh() end,
				})
			end
			badge("My", "Verified", "verified badge", mine.verified, "Add the verified checkmark after your name")
			badge("My", "Premium", "premium badge", mine.premium, "Add the Premium icon after your name")
			local others = cfg["others"]
			field("Others", "Name", "others: name", others.name, "Player")
			field("Others", "Display", "others: display name", others.display, "Player")
			field("Others", "Avatar", "others: avatar (user id)", others.avatar, "1", true)
			badge("Others", "Verified", "others: verified badge", others.verified, "Add the verified checkmark after other players' names")
			badge("Others", "Premium", "others: premium badge", others.premium, "Add the Premium icon after other players' names")
		end

		-- More of the player spoofer, done the way the other hub does it:
		--  * profile page (clicking a player): ViewProfile.Fetch asks the server through
		--    ReplicatedStorage; its upvalue is swapped for a stand-in that makes the real
		--    request and then edits the returned data (wins, win %, elo, level, favorite map),
		--  * keys / event currency / seasons: fields of the game's own player data,
		--  * leaderboard rank: the game's ranking lookup and the board list are redirected,
		--  * ping: the upvalue `Players` of Utility.GetLocalConnectionPing is swapped.
		-- Every hook is optional: if a game function / upvalue is not found, that spoof
		-- just does nothing. They are all undone when the hub is unloaded.
		MD3.LYSpoofExtras = function(frame, spoofs)
			local Players = game:GetService("Players")
			local ReplicatedStorage = game:GetService("ReplicatedStorage")
			local me = Players.LocalPlayer
			local extra = {}
			for _, scope in { "local", "others" } do
				extra[scope] = {
					casualWins   = { enabled = false, value = 0 },
					rankedWins   = { enabled = false, value = 0 },
					casualPct    = { enabled = false, value = 0 },
					rankedPct    = { enabled = false, value = 0 },
					favoriteMap  = { enabled = false, value = "Arena" },
				}
			end
			local keys        = { enabled = false, value = 999 }
			local event       = { enabled = false, value = 9999 }
			local board       = { enabled = false, value = 1 }
			local ping        = { enabled = false, value = "Low" }

			local function scopeOf(player)
				if player == me or player == me.UserId then return "local" end
				return "others"
			end

			-- Profile page ------------------------------------------------------------
			local profile = { installed = false, restore = nil }
			local function editProfile(player, data)
				if type(data) ~= "table" then return data end
				local scope = scopeOf(player)
				local base, more = spoofs[scope], extra[scope]
				if base.level.enabled then data.Level = base.level.value end
				if more.casualWins.enabled then data.CasualWins = more.casualWins.value end
				if more.rankedWins.enabled then data.RankedWins = more.rankedWins.value end
				if more.casualPct.enabled then data.CasualWinPercent = more.casualPct.value / 100 end
				if more.rankedPct.enabled then data.RankedWinPercent = more.rankedPct.value / 100 end
				if base.elo.enabled then data.RankedCurrentELO = base.elo.value end
				if more.favoriteMap.enabled then data.FavoriteMap = more.favoriteMap.value end
				return data
			end
			local function installProfileHook()
				if profile.installed or not (debug and debug.getupvalues and debug.setupvalue) then return end
				local viewProfile = MD3.LYRequire and MD3.LYRequire("ViewProfile")
				local meta = viewProfile and getmetatable(viewProfile)
				local methods = type(meta) == "table" and rawget(meta, "__index")
				local fetch = type(methods) == "table" and rawget(methods, "Fetch")
				if type(fetch) ~= "function" then return end
				local index, original
				for slot, value in debug.getupvalues(fetch) do
					if typeof(value) == "Instance" and pcall(value.IsA, value, "ReplicatedStorage") and value:IsA("ReplicatedStorage") then
						index, original = slot, value
					end
				end
				if not index then return end
				local request
				pcall(function() request = ReplicatedStorage.Remotes.Misc.RequestProfile end)
				if not request then return end
				local stand = setmetatable({}, { __index = function()
					return { Misc = { RequestProfile = { InvokeServer = function(_, player)
						local ok, data = pcall(request.InvokeServer, request, player)
						if not ok then return nil end
						return editProfile(player, data)
					end } } }
				end })
				if pcall(debug.setupvalue, fetch, index, stand) then
					profile.installed = true
					profile.restore = function() pcall(debug.setupvalue, fetch, index, original) end
				end
			end

			-- Player-data fields: keys, event currency, season elo --------------------
			local function dataSet(field, getter)
				if MD3.LYData then pcall(MD3.LYData.Set, field, getter) end
			end
			local function seasonsWithElo()
				local original = MD3.LYData and MD3.LYData.Real("Seasons")
				local library = MD3.LYRequire and MD3.LYRequire("SeasonLibrary")
				local current = type(library) == "table" and library.CurrentSeason
				if type(original) ~= "table" or type(current) ~= "table" or not spoofs["local"].elo.enabled then
					return original
				end
				local name = current.Name
				local universal = library.UNIVERSAL_ELO_NAME
				local clone = table.clone(original)
				local season = table.clone(clone[name] or {})
				local performances = table.clone(season.RankedPerformances or {})
				local entry = table.clone(performances[universal] or {})
				entry.CurrentELO = spoofs["local"].elo.value
				performances[universal] = entry
				season.RankedPerformances = performances
				clone[name] = season
				return clone
			end
			local function applyData()
				dataSet("WeaponKeys", keys.enabled and function() return keys.value end or nil)
				dataSet("EventCurrency", event.enabled and function() return event.value end or nil)
				dataSet("Seasons", spoofs["local"].elo.enabled and seasonsWithElo or nil)
			end

			-- Leaderboard rank ----------------------------------------------------------
			local boardHook = { restore = nil }
			local function installBoard()
				if boardHook.restore or not (debug and debug.getconstants and debug.setconstant) then return end
				local controller = MD3.LYRequire and MD3.LYRequire("LeaderboardController")
				local library = MD3.LYRequire and MD3.LYRequire("SeasonLibrary")
				if type(controller) ~= "table" or type(library) ~= "table" then return end
				local meta = getmetatable(controller)
				local methods = type(meta) == "table" and rawget(meta, "__index")
				local ranking = type(methods) == "table" and rawget(methods, "GetRankingByUserID")
				local highest = rawget(library, "GetHighestELOLeaderboardRanking")
				if type(ranking) ~= "function" or type(highest) ~= "function" then return end
				local constantIndex
				for slot, value in debug.getconstants(highest) do
					if value == "GetRankingByUserID" then constantIndex = slot break end
				end
				if not constantIndex then return end
				local alias = "GetRankingByUserID\\0ly"
				pcall(debug.setconstant, highest, constantIndex, alias)
				pcall(rawset, controller, alias, function(self, kind, userId)
					if board.enabled and kind == "Highest ELO" and userId ~= nil
						and (userId == me.UserId or tostring(userId) == tostring(me.UserId)) then
						return board.value
					end
					return ranking(self, kind, userId)
				end)
				boardHook.restore = function()
					pcall(debug.setconstant, highest, constantIndex, "GetRankingByUserID")
					pcall(rawset, controller, alias, nil)
				end
			end

			-- Ping ----------------------------------------------------------------------
			local pingHook = { restore = nil }
			local PING = { Low = { 150, 160 }, Medium = { 60, 75 }, High = { 17, 25 } }
			local function installPing()
				if pingHook.restore or not (debug and debug.getupvalues and debug.setupvalue) then return end
				local utility
				pcall(function() utility = require(ReplicatedStorage.Modules.Utility) end)
				local meta = utility and getmetatable(utility)
				local methods = type(meta) == "table" and rawget(meta, "__index")
				local fn = type(methods) == "table" and rawget(methods, "GetLocalConnectionPing")
				if type(fn) ~= "function" then return end
				local index, original
				for slot, value in debug.getupvalues(fn) do
					if typeof(value) == "Instance" and pcall(value.IsA, value, "Players") and value:IsA("Players") then index, original = slot, value end
				end
				if not index then return end
				local stand = { LocalPlayer = { GetNetworkPing = function()
					if not ping.enabled then return me:GetNetworkPing() end
					local range = PING[ping.value] or PING.Low
					return math.random(range[1], range[2]) / 1000
				end } }
				if pcall(debug.setupvalue, fn, index, stand) then
					pingHook.restore = function() pcall(debug.setupvalue, fn, index, original) end
				end
			end

			Port.OnUnload(function()
				if profile.restore then profile.restore() end
				if boardHook.restore then boardHook.restore() end
				if pingHook.restore then pingHook.restore() end
				pcall(function()
					if MD3.LYData then
						MD3.LYData.Set("WeaponKeys", nil)
						MD3.LYData.Set("EventCurrency", nil)
						MD3.LYData.Set("Seasons", nil)
					end
				end)
			end)

			-- Controls --------------------------------------------------------------------
			local function field(prefix, key, label, target, default, onChange, text)
				frame:AddToggle(prefix .. key .. "Spoof", {
					Text = label, Default = false,
					Callback = function(on) target.enabled = on; onChange() end,
				})
				frame:AddInput(prefix .. key .. "Value", {
					Text = label, Default = tostring(default), Placeholder = tostring(default),
					Numeric = not text, Finished = text == true,
					Callback = function(value)
						if text then
							target.value = (value ~= "" and value) or default
						else
							target.value = tonumber(value) or default
						end
						onChange()
					end,
				})
			end
			local function refreshProfile() installProfileHook() end
			local function refreshData() installProfileHook(); applyData() end
			local function refreshBoard()
				installBoard()
			end

			field("", "Keys", "keys", keys, 999, refreshData)
			field("", "EventCurrency", "event currency", event, 9999, refreshData)
			field("", "LeaderboardRank", "leaderboard rank", board, 1, refreshBoard)
			frame:AddToggle("PingSpoof2", {
				Text = "ping (menu)", Default = false,
				Callback = function(on) ping.enabled = on; installPing() end,
			})
			frame:AddDropdown("PingSpoof2Type", {
				Text = "ping level", Default = "Low", Values = { "Low", "Medium", "High" },
				Callback = function(value) ping.value = value or "Low"; installPing() end,
			})
			local mine = extra["local"]
			field("", "CasualWins", "casual wins", mine.casualWins, 99999, refreshProfile)
			field("", "RankedWins", "ranked wins", mine.rankedWins, 9999, refreshProfile)
			field("", "CasualPct", "casual win %", mine.casualPct, 100, refreshProfile)
			field("", "RankedPct", "ranked win %", mine.rankedPct, 100, refreshProfile)
			field("", "FavoriteMap", "favorite map", mine.favoriteMap, "Arena", refreshProfile, true)
			local others = extra["others"]
			field("Other", "CasualWins", "others: casual wins", others.casualWins, 0, refreshProfile)
			field("Other", "RankedWins", "others: ranked wins", others.rankedWins, 0, refreshProfile)
			field("Other", "CasualPct", "others: casual win %", others.casualPct, 0, refreshProfile)
			field("Other", "RankedPct", "others: ranked win %", others.rankedPct, 0, refreshProfile)
			field("Other", "FavoriteMap", "others: favorite map", others.favoriteMap, "", refreshProfile, true)

			-- The level / elo toggles above feed the profile page and the seasons too.
			local function recheck()
				refreshData()
				installBoard()
			end
			task.spawn(function()
				while not Port.Unloaded do
					task.wait(2)
					if spoofs["local"].elo.enabled or spoofs["local"].level.enabled
						or spoofs["others"].level.enabled or spoofs["others"].elo.enabled then
						pcall(recheck)
					end
				end
			end)
		end

		MD3.LYSpoofExtras(frame, spoofs)

		MD3.LYIdentitySpoof(frame)

		local fpsTab = Port.Section(CharacterTab, "FPS Spoof")
		local msTab = Port.Section(CharacterTab, "Ping Spoof")
		local regionTab = Port.Section(CharacterTab, "Region Spoof")

		if not config.profile.fpsspoof then
			config.profile.fpsspoof = { enabled = false, value = "1", fraud = false }
		end

		if not config.profile.msspoof then
			config.profile.msspoof = { enabled = false, value = "1", fraud = false }
		end

		if not config.profile.regionspoof then
			config.profile.regionspoof = { enabled = false, value = "dc.lystore.lol" }
		end

		_G.FPSSpoofConnections = _G.FPSSpoofConnections or {}
		for i = 1, #_G.FPSSpoofConnections do
			_G.FPSSpoofConnections[i]:Disconnect()
		end
		_G.FPSSpoofConnections = {}

		_G.MSSpoofConnections = _G.MSSpoofConnections or {}
		for i = 1, #_G.MSSpoofConnections do
			_G.MSSpoofConnections[i]:Disconnect()
		end
		_G.MSSpoofConnections = {}

		_G.RegionSpoofConnections = _G.RegionSpoofConnections or {}
		for i = 1, #_G.RegionSpoofConnections do
			_G.RegionSpoofConnections[i]:Disconnect()
		end
		_G.RegionSpoofConnections = {}

		if _G.FPSFraudThread then
			_G.FPSFraudThread = false
		end

		if _G.MSFraudThread then
			_G.MSFraudThread = false
		end

		local PlayerGui = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
		local foundLabels = {}
		local foundRegionLabels = {}

		local function findLabels(parent)
			local children = parent:GetChildren()
			for i = 1, #children do
				local child = children[i]
				if child:IsA("TextLabel") and child.Name == "Title" then
					if child.Parent.Name == "ServerRegion" then
						foundRegionLabels[#foundRegionLabels + 1] = child
					else
						foundLabels[#foundLabels + 1] = child
					end
				end
				findLabels(child)
			end
		end

		findLabels(PlayerGui)

		local lastBaseFPS = nil
		local lastBaseMS = nil
		local fpsTrend = 0
		local msTrend = 0
		local lastFPSTime = 0
		local lastMSTime = 0

		local function getFraudFPS()
			local base = tonumber(config.profile.fpsspoof.value) or 60

			if lastBaseFPS == nil then
				lastBaseFPS = base
			end

			local variation = math.random(-8, 12)
			fpsTrend = fpsTrend + math.random(-3, 5)
			fpsTrend = math.clamp(fpsTrend, -15, 15)

			local totalVariation = variation + fpsTrend

			if math.random(1, 100) <= 15 then
				totalVariation = totalVariation + math.random(-10, 20)
			end

			if math.random(1, 100) <= 8 then
				totalVariation = totalVariation - math.random(5, 15)
			end

			local newValue = base + totalVariation

			if math.random(1, 100) <= 5 then
				newValue = newValue + math.random(20, 45)
			end

			if newValue < 10 then
				newValue = math.random(10, 25)
			end

			if newValue > 144 then
				newValue = math.random(120, 144)
			end

			if math.random(1, 100) <= 3 then
				newValue = math.random(30, 50)
			end

			lastBaseFPS = newValue
			return tostring(math.floor(newValue))
		end

		local function getFraudMS()
			local base = tonumber(config.profile.msspoof.value) or 50

			if lastBaseMS == nil then
				lastBaseMS = base
			end

			msTrend = msTrend + math.random(-4, 6)
			msTrend = math.clamp(msTrend, -20, 25)

			local spike = 0
			if math.random(1, 100) <= 12 then
				spike = math.random(15, 45)
			end

			if math.random(1, 100) <= 7 then
				spike = spike - math.random(10, 30)
			end

			local variation = math.random(-12, 18)
			local newValue = base + variation + msTrend + spike

			if newValue < 8 then
				newValue = math.random(8, 20)
			end

			if newValue > 250 then
				newValue = math.random(180, 250)
			end

			if math.random(1, 100) <= 10 then
				newValue = newValue + math.random(5, 25)
			end

			if math.random(1, 100) <= 6 then
				newValue = math.random(100, 200)
			end

			lastBaseMS = newValue
			return tostring(math.floor(newValue))
		end

		local function applyFPSSpoof()
			for i = 1, #_G.FPSSpoofConnections do
				_G.FPSSpoofConnections[i]:Disconnect()
			end
			_G.FPSSpoofConnections = {}
			_G.FPSFraudThread = false
			lastBaseFPS = nil
			fpsTrend = 0
			if not config.profile.fpsspoof.enabled then return end

			if config.profile.fpsspoof.fraud then
				_G.FPSFraudThread = true
				task.spawn(function()
					while _G.FPSFraudThread do
						local target = getFraudFPS()
						for i = 1, #foundLabels do
							local label = foundLabels[i]
							local spoofed = label.Text:gsub("%d+fps", target .. "fps")
							if spoofed ~= label.Text then
								label.Text = spoofed
							end
						end
						local waitTime = 0.95 + math.random() * 0.4
						task.wait(waitTime)
					end
				end)
			else
				local target = config.profile.fpsspoof.value
				for i = 1, #foundLabels do
					local label = foundLabels[i]
					_G.FPSSpoofConnections[#_G.FPSSpoofConnections + 1] = Port.Track(label:GetPropertyChangedSignal("Text"):Connect(function()
						local spoofed = label.Text:gsub("%d+fps", target .. "fps")
						if spoofed ~= label.Text then
							label.Text = spoofed
						end
					end))
				end
			end
		end

