		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")
		local LocalPlayer = Players.LocalPlayer

		_G.Features = _G.Features or {}
		_G.Features.Noclip = _G.Features.Noclip or {
			Enabled = false,
			Conn = nil
		}

		_G.Features.ModDetector = _G.Features.ModDetector or {
			Enabled = false,
			Connection = nil,
			Checking = false
		}

		-- part -> CanCollide before noclip touched it. Turning noclip off puts
		-- these back; forcing every part to true switched on the game's hitbox,
		-- FakeMass and accessory parts, which then shoved the character off the floor.
		local noclipOriginals = setmetatable({}, { __mode = "k" })

		local function updnoclip()
			if _G.Features.Noclip.Conn then
				_G.Features.Noclip.Conn:Disconnect()
				_G.Features.Noclip.Conn = nil
			end
			if _G.Features.Noclip.Enabled then
				_G.Features.Noclip.Conn = Port.Track(RunService.Stepped:Connect(function()
					local curchar = LocalPlayer.Character
					if not curchar then return end
					for _, part in pairs(curchar:GetDescendants()) do
						if part:IsA("BasePart") then
							if noclipOriginals[part] == nil then
								noclipOriginals[part] = part.CanCollide
							end
							part.CanCollide = false
						end
					end
				end))
			else
				for part, original in pairs(noclipOriginals) do
					if part.Parent then
						part.CanCollide = original
					end
				end
				table.clear(noclipOriginals)
			end
		end

		Port.Track(LocalPlayer.CharacterAdded:Connect(function()
			task.wait(0.2)
			if _G.Features.Noclip.Enabled then
				updnoclip()
			end
		end))

		Port.Section(CharacterTab, "Movement"):AddToggle('noclip', {
			Text = 'noclip',
			Default = _G.Features.Noclip.Enabled,
			Callback = function(Value)
				_G.Features.Noclip.Enabled = Value
				updnoclip()
			end
		})

		_G.Features.Handicaps = _G.Features.Handicaps or { Enabled = false }

