			{ key = "Primary",   label = "Primary",   rate = 20, tp = false, reach = 6 },
			{ key = "Secondary", label = "Secondary", rate = 20, tp = false, reach = 6 },
			{ key = "Knife",     label = "Knife",     rate = 20, tp = true,  reach = 6 },
			{ key = "Melee",     label = "Melee",     rate = 20, tp = true,  reach = 6 },
		}) do
			local cfg = rage[slotInfo.key]
			local sec = RagebotTab:AddSection(slotInfo.label)
			sec:AddDropdown({
				Title = "Hit part",
				Options = { "HitboxHead", "HitboxBody", "Head", "Body", "Closest", "Random" },
				Default = cfg.HitPart,
				Flag = "Rage" .. slotInfo.key .. "HitPart",
				Callback = function(v) cfg.HitPart = v end,
			})
			sec:AddSlider({
				Title = "Hit chance", Min = 0, Max = 100, Step = 1, Default = cfg.HitChance, Suffix = "%",
				Flag = "Rage" .. slotInfo.key .. "HitChance",
				Callback = function(v) cfg.HitChance = v end,
			})
			-- Guns top out at 30/s; knife and melee keep the full 60.
			local maxRate = (slotInfo.key == "Knife" or slotInfo.key == "Melee") and 60 or 30
			cfg.Rate = math.min(cfg.Rate, maxRate)
			sec:AddSlider({
				Title = "Fire rate", Min = 1, Max = maxRate, Step = 1, Default = cfg.Rate, Suffix = "/s",
				Description = maxRate == 60 and "60 = as fast as the server accepts (highest damage per second)"
					or "Shots per second (max 30)",
				Flag = "Rage" .. slotInfo.key .. "Rate",
				Callback = function(v) cfg.Rate = math.min(v, maxRate) end,
			})
			sec:AddToggle({
				Title = "Teleport to target",
				Description = (slotInfo.key == "Melee" or slotInfo.key == "Knife")
					and "Snap onto the target for melee reach"
					or "Snap onto the target for the shot; most detectable",
				Default = cfg.Teleport,
				Flag = "Rage" .. slotInfo.key .. "Teleport",
				Callback = function(on) cfg.Teleport = on end,
			})
			sec:AddSlider({
				Title = "Teleport reach", Min = 0, Max = 20, Step = 0.5, Default = cfg.TeleportReach, Suffix = " studs",
				Flag = "Rage" .. slotInfo.key .. "TeleportReach",
				Callback = function(v) cfg.TeleportReach = v end,
			})
			sec:AddToggle({
				Title = "Physics glue",
				Description = "Bind PhysicsRepRootPart to the hitbox while teleported",
				Default = cfg.Glue,
				Flag = "Rage" .. slotInfo.key .. "Glue",
				Callback = function(on) cfg.Glue = on end,
			})
		end

		-- Weapon tweaks -------------------------------------------------------------------
		-- Scale values in the equipped item's Info table. Every value is scaled
		-- from the game's original (remembered on first touch), so it doesn't
		-- compound frame after frame, and goes back when its slider returns to 1.

		-- Recoil, fire rate and melee rate live in Combat > Gun (no recoil / rapid
		-- fire / rapid attack), which hooks the item modules directly.
		local weaponTweaks = {
			AutoWeapon = false,
			AimSpeedMult = 1,
			DashCooldown = 1,
			MeleeReach = 1,
			GrenadeFuse = false, FuseTime = 0.5,
			InfiniteDoubleJumps = false,
		}
		local SCALED_KEYS = {
			AimSpeed = "AimSpeedMult",
			DashCooldown = "DashCooldown",
			AttackReach = "MeleeReach",
			HeavyAttackReach = "MeleeReach",
		}
		local originalInfo = setmetatable({}, { __mode = "k" }) -- info table -> { key -> original }

		local function writeInfo(info, key, value)
			local frozen = type(isreadonly) == "function" and isreadonly(info)
			if frozen and type(setreadonly) == "function" then
				setreadonly(info, false)
			end
			pcall(rawset, info, key, value)
			if frozen and type(setreadonly) == "function" then
				setreadonly(info, true)
			end
		end

		-- Sets info[key], remembering the game's value; nil puts the original back.
		local function setInfo(info, key, value)
			local saved = originalInfo[info]
			if not saved then
				saved = {}
				originalInfo[info] = saved
			end
			if value == nil then
				if saved[key] ~= nil then
					writeInfo(info, key, saved[key])
					saved[key] = nil
				end
				return
			end
			if saved[key] == nil then
				saved[key] = rawget(info, key)
			end
			writeInfo(info, key, value)
		end

		local function original(info, key)
			local saved = originalInfo[info]
			if saved and saved[key] ~= nil then
				return saved[key]
			end
			return rawget(info, key)
		end

		local function applyWeaponTweaks(info)
			for key, setting in SCALED_KEYS do
				local base = original(info, key)
				local mult = weaponTweaks[setting]
				local scalable = type(base) == "number" or typeof(base) == "Vector2"
				if scalable and mult ~= 1 and not (type(base) == "number" and setting:find("Cooldown") and base <= 0) then
					setInfo(info, key, base * mult)
				else
					setInfo(info, key, nil)
				end
			end
			local fuse = original(info, "DetonateDelay")
			setInfo(info, "DetonateDelay", if weaponTweaks.GrenadeFuse and type(fuse) == "number" then weaponTweaks.FuseTime else nil)
			setInfo(info, "MaxDoubleJumps", if weaponTweaks.InfiniteDoubleJumps then 676767 else nil)
			local spamming = rawget(info, "InputSpammingEnabled")
			if type(spamming) == "table" then
				setInfo(spamming, "StartShooting", if weaponTweaks.AutoWeapon then true else nil)
			end
		end

		local function restoreWeaponTweaks()
			for info, saved in originalInfo do
				for key, value in saved do
					writeInfo(info, key, value)
				end
			end
			table.clear(originalInfo)
		end

		local function tweaksActive()
			local t = weaponTweaks
			return t.AutoWeapon or t.GrenadeFuse or t.InfiniteDoubleJumps
				or t.AimSpeedMult ~= 1 or t.MeleeReach ~= 1 or t.DashCooldown ~= 1
		end

		-- The local player's equipped item. getgc never turned it up, so it's
		-- picked up from the item modules instead: every item passes itself to
		-- Equip, guns to Update each frame, throwables to StartAiming. (StartShooting
		-- is left alone; Combat > Gun already wraps it.)
		local localItem = nil
		local function remember(item)
			if type(item) ~= "table" or type(rawget(item, "Info")) ~= "table" then
				return
			end
			local ok, isLocal = pcall(function()
				return item.ClientFighter.IsLocalPlayer
			end)
			if ok and isLocal == true then
				localItem = item
			end
		end
		local ITEM_HOOKS = {
			Gun = { "Equip", "Update", "StartAiming" },
			Melee = { "Equip" },
			Throwable = { "StartAiming" },
		}
		for moduleName, methods in ITEM_HOOKS do
			local class = moduleAt({ "Modules", "ItemTypes", moduleName })
			if class then
				for _, method in methods do
					patch(class, method, function(original)
						return function(self, ...)
							remember(self)
							return original(self, ...)
						end
					end)
				end
			end
		end
		local function getLocalItem()
			if localItem and localItem.Info and localItem.ClientFighter then
				return localItem
			end
			localItem = nil
			return nil
		end

		local tweaksWereActive = false
		local function updateWeaponTweaks()
			if tweaksActive() then
				tweaksWereActive = true
				local item = getLocalItem()
				if item then
					applyWeaponTweaks(item.Info)
				end
			elseif tweaksWereActive then
				tweaksWereActive = false
				restoreWeaponTweaks()
			end
		end

		local function tweak(key)
			return function(value)
				weaponTweaks[key] = value
			end
		end

		local WeaponTweakSection = GunSection or CombatTab:AddSection("Gun")
		WeaponTweakSection:AddToggle({ Title = "Auto weapon", Description = "Semi-auto weapons fire while you hold the trigger", Default = false, Flag = "AutoWeapon", Callback = tweak("AutoWeapon") })
		WeaponTweakSection:AddSlider({ Title = "Aim speed", Min = 1, Max = 10, Step = 0.5, Default = 1, Suffix = "x", Flag = "AimSpeedMult", Callback = tweak("AimSpeedMult") })
		WeaponTweakSection:AddSlider({ Title = "Dash cooldown", Min = 0, Max = 1, Step = 0.05, Default = 1, Suffix = "x", Flag = "DashCooldownMult", Callback = tweak("DashCooldown") })
		WeaponTweakSection:AddSlider({ Title = "Melee reach", Min = 1, Max = 5, Step = 0.5, Default = 1, Suffix = "x", Flag = "MeleeRangeMult", Callback = tweak("MeleeReach") })
		WeaponTweakSection:AddToggle({ Title = "Custom grenade fuse", Description = "Override the grenade detonation delay", Default = false, Flag = "GrenadeFuseEnabled", Callback = tweak("GrenadeFuse") })
		WeaponTweakSection:AddSlider({ Title = "Fuse time", Min = 0, Max = 5, Step = 0.1, Default = weaponTweaks.FuseTime, Suffix = "s", Flag = "GrenadeFuseTime", Callback = tweak("FuseTime") })

		-- Jump ------------------------------------------------------------------------------
		-- Infinite double jumps: MechanicsController:DoubleJumpRequest only allows
		-- EquippedItem.Info.MaxDoubleJumps jumps per airtime (nil for most items).
		-- While the toggle is on, skip that count and double jump whenever airborne.

		local jump = { Custom = false, Power = 20, InfiniteDoubleJumps = false, LongJump = false, LongJumpForce = 50 }

		do
			local controller = moduleAt({ "Controllers", "MechanicsController" })
			local meta = controller and getmetatable(controller)
			local methods = type(meta) == "table" and rawget(meta, "__index")
			if type(methods) == "table" then
				patch(methods, "DoubleJumpRequest", function(original)
					return function(self, ...)
						if not jump.InfiniteDoubleJumps then
							return original(self, ...)
						end
						local fighter = self.LocalFighter
						local ok, airborne = pcall(function()
							return fighter.EquippedItem ~= nil and not fighter:IsGrounded()
						end)
						if ok and airborne then
							return self:DoubleJump()
						end
						return original(self, ...)
					end
				end)
			end
		end

		local restoreJumpPower = nil
		local function updateJump()
			local character = LocalPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			if jump.Custom and humanoid then
				if not restoreJumpPower then
					restoreJumpPower = snapshot(humanoid, { "JumpPower" })
				end
				if humanoid.JumpPower ~= jump.Power then
					humanoid.JumpPower = jump.Power
				end
			elseif restoreJumpPower then
				restoreJumpPower()
				restoreJumpPower = nil
			end
		end
		track(LocalPlayer.CharacterAdded:Connect(function()
			restoreJumpPower = nil
		end))
		track(function()
			if restoreJumpPower then
				restoreJumpPower()
			end
		end)

		local JumpSection = CharacterTab:AddSection("Movement")
		JumpSection:AddToggle({ Title = "Custom jump power", Default = false, Flag = "CustomJumpPower", Callback = function(on) jump.Custom = on end })
		JumpSection:AddSlider({ Title = "Jump power", Min = 0, Max = 200, Step = 1, Default = jump.Power, Flag = "JumpPowerValue", Callback = function(v) jump.Power = v end })
		JumpSection:AddToggle({
			Title = "Infinite double jumps",
			Description = "Unlimited double jumps with every weapon",
			Default = false,
			Flag = "InfiniteDoubleJumps",
			Callback = function(on)
				jump.InfiniteDoubleJumps = on
				weaponTweaks.InfiniteDoubleJumps = on
			end,
		})
		JumpSection:AddToggle({ Title = "Long jump", Description = "Boost your horizontal speed when you jump", Default = false, Flag = "LongJump", Callback = function(on) jump.LongJump = on end })
		JumpSection:AddSlider({ Title = "Long jump force", Min = 10, Max = 200, Step = 5, Default = jump.LongJumpForce, Flag = "LongJumpForce", Callback = function(v) jump.LongJumpForce = v end })

		local wasJumping = false
		track(RunService.Heartbeat:Connect(function()
			local character = LocalPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if not (jump.LongJump and humanoid and root) then
				wasJumping = false
				return
			end
			local jumping = humanoid:GetState() == Enum.HumanoidStateType.Jumping
			if jumping and not wasJumping and humanoid.MoveDirection.Magnitude > 0.1 then
				root.AssemblyLinearVelocity += humanoid.MoveDirection.Unit * jump.LongJumpForce
			end
			wasJumping = jumping
		end))

		-- Auto strafe -------------------------------------------------------------------------

		local autoStrafe = { Enabled = false, Direction = "Random", Interval = 0.3, Side = 1, LastSwitch = 0 }
		local AutoStrafeSection = CharacterTab:AddSection("Auto Strafe")
		AutoStrafeSection:AddToggle({ Title = "Enabled", Description = "Drift left / right while you move", Default = false, Flag = "AutoStrafe", Callback = function(on) autoStrafe.Enabled = on end })
		AutoStrafeSection:AddDropdown({ Title = "Direction", Options = { "Left", "Right", "Random" }, Default = autoStrafe.Direction, Flag = "AutoStrafeDir", Callback = function(v) autoStrafe.Direction = v end })
		AutoStrafeSection:AddSlider({ Title = "Interval", Min = 0.1, Max = 1, Step = 0.05, Default = autoStrafe.Interval, Suffix = "s", Flag = "AutoStrafeInterval", Callback = function(v) autoStrafe.Interval = v end })

		local function updateAutoStrafe()
			local character = LocalPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = character and character:FindFirstChild("HumanoidRootPart")
			local cam = camera()
			if not (autoStrafe.Enabled and humanoid and root and cam and humanoid.MoveDirection.Magnitude > 0.1) then
				return
			end
			local now = os.clock()
			if now - autoStrafe.LastSwitch >= autoStrafe.Interval then
				autoStrafe.LastSwitch = now
				if autoStrafe.Direction == "Random" then
					autoStrafe.Side = math.random() > 0.5 and 1 or -1
				else
					autoStrafe.Side = autoStrafe.Direction == "Left" and -1 or 1
				end
			end
			local push = cam.CFrame.RightVector * autoStrafe.Side * 0.5
			root.AssemblyLinearVelocity += Vector3.new(push.X, 0, push.Z)
		end

		-- One loop for everything above ----------------------------------------------------

		RunService:BindToRenderStep(COMBAT_STEP, Enum.RenderPriority.Camera.Value + 1, function(dt)
			updateTriggerbot(dt)
			updateFlickbot(dt)
			checkLockedTarget()
			updateWeaponTweaks()
			updateJump()
			updateAutoStrafe()
		end)
		track(function()
			RunService:UnbindFromRenderStep(COMBAT_STEP)
			restoreWeaponTweaks()
		end)
	end

	--==========================================================================--
	--== Visuals / camera / crosshair / feedback / misc extras (from main)   ==--
	--==========================================================================--

	-- Tonemapper ---------------------------------------------------------------------

	do
		local TonemapSection = VisualsTab:AddSection("Tonemapper")
		local tonemapper = { Enabled = false, Preset = "Default" }
		local restoreTonemapper = nil

		local function applyTonemapper()
			if tonemapper.Enabled then
				restoreTonemapper = restoreTonemapper or snapshot(Lighting, { "TonemapperPreset" })
				pcall(function()
					Lighting.TonemapperPreset = Enum.TonemapperPreset[tonemapper.Preset]
				end)
			elseif restoreTonemapper then
				restoreTonemapper()
				restoreTonemapper = nil
			end
		end

		TonemapSection:AddToggle({
			Title = "Enabled",
			Description = "Switch Roblox's tone mapping preset",
			Default = false,
			Flag = "TonemapperEnabled",
			Callback = function(on)
				tonemapper.Enabled = on
				applyTonemapper()
			end,
		})
		TonemapSection:AddDropdown({
			Title = "Preset",
			Options = { "Default", "Retro" },
			Default = tonemapper.Preset,
			Flag = "TonemapperPreset",
			Callback = function(preset)
				tonemapper.Preset = preset
				applyTonemapper()
			end,
		})
		track(function()
			tonemapper.Enabled = false
			applyTonemapper()
		end)
	end

	-- Lightning ----------------------------------------------------------------------
	-- Cosmetic, local-only bolts (jagged Beam segments) near the camera, with a
	-- short flash and optional thunder.

	do
		local LightningSection = VisualsTab:AddSection("Lightning")
		local lightning = {
			Enabled = false, Interval = 3, Distance = 80, Height = 200, Thickness = 3,
			Jaggedness = 8, Segments = 6, Color = Color3.fromRGB(180, 180, 255),
			Flash = 5, Sound = true, Volume = 1,
		}
		local generation = 0

		local function strike()
			local cam = camera()
			if not cam then
				return
			end
			local angle = math.random() * math.pi * 2
			local distance = lightning.Distance * (0.5 + math.random() * 0.5)
			local camPos = cam.CFrame.Position
			local base = Vector3.new(camPos.X + math.cos(angle) * distance, camPos.Y - 20, camPos.Z + math.sin(angle) * distance)
			local top = base + Vector3.new(0, lightning.Height, 0)

			local folder = own(Instance.new("Folder"))
			folder.Name = PREFIX .. "Lightning"

			local points = { top }
			for index = 1, lightning.Segments do
				local jag = lightning.Jaggedness
				table.insert(points, top:Lerp(base, index / (lightning.Segments + 1)) + Vector3.new(
					(math.random() - 0.5) * jag * 2,
					(math.random() - 0.5) * jag,
					(math.random() - 0.5) * jag * 2
				))
			end
			table.insert(points, base)

			for index = 1, #points - 1 do
				local a0 = Instance.new("Attachment")
				a0.Position = points[index]
				a0.Parent = workspace.Terrain
				local a1 = Instance.new("Attachment")
				a1.Position = points[index + 1]
				a1.Parent = workspace.Terrain
				local beam = Instance.new("Beam")
				beam.Attachment0 = a0
				beam.Attachment1 = a1
				beam.Width0 = lightning.Thickness
				beam.Width1 = lightning.Thickness * 0.7
				beam.Color = ColorSequence.new(lightning.Color)
				beam.LightEmission = 1
				beam.LightInfluence = 0
				beam.Brightness = 3
				beam.FaceCamera = true
				beam.Segments = 1
				beam.Parent = a0
				-- Cleaned up with the folder below.
				folder.Destroying:Connect(function()
					a0:Destroy()
					a1:Destroy()
				end)
			end

			if lightning.Flash > 0 then
				local lightPart = Instance.new("Part")
				lightPart.Anchored = true
				lightPart.CanCollide = false
				lightPart.CanQuery = false
				lightPart.CanTouch = false
				lightPart.Transparency = 1
				lightPart.Size = Vector3.one
				lightPart.Position = top
				local light = Instance.new("PointLight")
				light.Brightness = lightning.Flash
				light.Range = math.min(lightning.Distance * 2, 60)
				light.Color = lightning.Color
				light.Parent = lightPart
				lightPart.Parent = folder
			end
			folder.Parent = workspace

			if lightning.Sound then
				local sound = Instance.new("Sound")
				sound.SoundId = "rbxassetid://12222058"
				sound.Volume = lightning.Volume
				sound.Parent = SoundService
				sound:Play()
				task.delay(4, sound.Destroy, sound)
			end

			task.delay(0.3, function()
				pcall(folder.Destroy, folder)
			end)
		end

		local function setting(key)
			return function(value)
				lightning[key] = value
			end
		end

		LightningSection:AddToggle({
			Title = "Enabled",
			Description = "Cosmetic lightning bolts near your camera (only you see them)",
			Default = false,
			Flag = "Lightning",
			Callback = function(on)
				lightning.Enabled = on
				generation += 1
				local current = generation
				if on then
					task.spawn(function()
						while lightning.Enabled and current == generation do
							pcall(strike)
							task.wait(lightning.Interval * (0.5 + math.random()))
						end
					end)
				end
			end,
		})
		LightningSection:AddSlider({ Title = "Interval", Min = 0.5, Max = 10, Step = 0.1, Default = lightning.Interval, Suffix = "s", Flag = "LightningInterval", Callback = setting("Interval") })
		LightningSection:AddSlider({ Title = "Distance", Min = 20, Max = 200, Step = 5, Default = lightning.Distance, Flag = "LightningDist", Callback = setting("Distance") })
		LightningSection:AddSlider({ Title = "Height", Min = 50, Max = 400, Step = 10, Default = lightning.Height, Flag = "LightningHeight", Callback = setting("Height") })
		LightningSection:AddSlider({ Title = "Thickness", Min = 0.5, Max = 12, Step = 0.1, Default = lightning.Thickness, Flag = "LightningThick", Callback = setting("Thickness") })
		LightningSection:AddSlider({ Title = "Jaggedness", Min = 0, Max = 20, Step = 0.5, Default = lightning.Jaggedness, Flag = "LightningJag", Callback = setting("Jaggedness") })
		LightningSection:AddSlider({ Title = "Segments", Min = 2, Max = 12, Step = 1, Default = lightning.Segments, Flag = "LightningSegs", Callback = setting("Segments") })
		LightningSection:AddColorPicker({ Title = "Color", Default = lightning.Color, Flag = "LightningColor", Callback = setting("Color") })
		LightningSection:AddSlider({ Title = "Flash brightness", Min = 0, Max = 20, Step = 0.5, Default = lightning.Flash, Flag = "LightningFlash", Callback = setting("Flash") })
		LightningSection:AddToggle({ Title = "Thunder sound", Default = lightning.Sound, Flag = "LightningSound", Callback = setting("Sound") })
		LightningSection:AddSlider({ Title = "Volume", Min = 0, Max = 3, Step = 0.1, Default = lightning.Volume, Flag = "LightningVolume", Callback = setting("Volume") })
		track(function()
			lightning.Enabled = false
			generation += 1
		end)
	end

	-- Third person ---------------------------------------------------------------------
	-- Moves the camera by an offset in its own space after the game has placed it.

	do
		local ThirdPersonSection = CameraTab:AddSection("Third Person")
		local thirdPerson = { Enabled = false, X = 3, Y = 2, Z = 6, RayCheck = false }
		local STEP = PREFIX .. "ThirdPerson"
		local bound = false

		local function update()
			local cam = camera()
			if not (thirdPerson.Enabled and cam) then
				return
			end
			local origin = cam.CFrame.Position
			local offset = cam.CFrame:VectorToWorldSpace(Vector3.new(thirdPerson.X, thirdPerson.Y, thirdPerson.Z))
			local target = origin + offset
			if thirdPerson.RayCheck and offset.Magnitude > 0 then
				local params = RaycastParams.new()
				params.FilterType = Enum.RaycastFilterType.Exclude
				params.FilterDescendantsInstances = { LocalPlayer.Character }
				local result = workspace:Raycast(origin, offset, params)
				if result then
					target = origin + offset.Unit * math.max(0, result.Distance - 0.2)
				end
			end
			cam.CFrame = CFrame.new(target, target + cam.CFrame.LookVector)
		end

		local function setBound(on)
			if on and not bound then
				RunService:BindToRenderStep(STEP, Enum.RenderPriority.Camera.Value + 1, update)
			elseif not on and bound then
				pcall(RunService.UnbindFromRenderStep, RunService, STEP)
			end
			bound = on
		end

		ThirdPersonSection:AddToggle({
			Title = "Enabled",
			Description = "Client-side third person camera (only you see the offset)",
			Default = false,
			Flag = "ThirdPerson",
			Callback = function(on)
				thirdPerson.Enabled = on
				setBound(on)
			end,
		})
		ThirdPersonSection:AddSlider({ Title = "X offset", Min = -15, Max = 15, Step = 0.1, Default = thirdPerson.X, Flag = "TPX", Callback = function(v) thirdPerson.X = v end })
		ThirdPersonSection:AddSlider({ Title = "Y offset", Min = -5, Max = 10, Step = 0.1, Default = thirdPerson.Y, Flag = "TPY", Callback = function(v) thirdPerson.Y = v end })
		ThirdPersonSection:AddSlider({ Title = "Z offset", Min = 0, Max = 15, Step = 0.1, Default = thirdPerson.Z, Flag = "TPZ", Callback = function(v) thirdPerson.Z = v end })
		ThirdPersonSection:AddToggle({ Title = "Ray check", Description = "Keep the camera from clipping through walls", Default = false, Flag = "TPRayCheck", Callback = function(on) thirdPerson.RayCheck = on end })
		track(function()
			setBound(false)
		end)
	end

	-- Crosshair text -------------------------------------------------------------------

	do
		local crosshairText = {
			Enabled = false, Content = "", Size = 14, Offset = 24,
			Color = Color3.new(1, 1, 1), Outline = false, OutlineColor = Color3.new(0, 0, 0),
		}

		local label = Instance.new("TextLabel")
		label.AnchorPoint = Vector2.new(0.5, 0)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.Code
		label.Size = UDim2.fromOffset(200, 30)
		label.Visible = false
		label.Parent = crosshairRoot
		track(own(label))

		local function layout()
			label.Visible = crosshairText.Enabled and crosshairText.Content ~= ""
			label.Text = crosshairText.Content
			label.TextSize = crosshairText.Size
			label.TextColor3 = crosshairText.Color
			label.Position = UDim2.fromOffset(0, crosshairText.Offset)
			label.TextStrokeTransparency = crosshairText.Outline and 0 or 1
			label.TextStrokeColor3 = crosshairText.OutlineColor
		end
		layout()

		local function setting(key)
			return function(value)
				crosshairText[key] = value
				layout()
			end
		end

		-- Shows with the crosshair (it lives in the crosshair's own ScreenGui).
		local TextSection = CrosshairTab:AddSection("Text")
		TextSection:AddToggle({ Title = "Enabled", Description = "A label under the crosshair (needs the crosshair on)", Default = false, Flag = "CrosshairTextEnabled", Callback = setting("Enabled") })
		TextSection:AddInput({ Title = "Content", Default = "", Placeholder = "Text under the crosshair", Flag = "CrosshairTextContent", Callback = setting("Content") })
		TextSection:AddSlider({ Title = "Size", Min = 6, Max = 48, Step = 1, Default = crosshairText.Size, Suffix = "px", Flag = "CrosshairTextSize", Callback = setting("Size") })
		TextSection:AddSlider({ Title = "Offset", Min = 0, Max = 100, Step = 1, Default = crosshairText.Offset, Suffix = "px", Flag = "CrosshairTextOffset", Callback = setting("Offset") })
		TextSection:AddColorPicker({ Title = "Color", Default = crosshairText.Color, Flag = "CrosshairTextColor", Callback = setting("Color") })
		TextSection:AddToggle({ Title = "Outline", Default = false, Flag = "CrosshairTextOutline", Callback = setting("Outline") })
		TextSection:AddColorPicker({ Title = "Outline color", Default = crosshairText.OutlineColor, Flag = "CrosshairTextOutlineColor", Callback = setting("OutlineColor") })
	end

	-- Notification position ---------------------------------------------------------------
	-- Where Lin67 Hub's own toasts stack (MD3 keeps them in Window._notifier.Instance).

	do
		local NotifSection = FeedbackTab:AddSection("Notifications")
		local notif = { Side = "BottomRight", Offset = 0 }
		local frame = Window._notifier and Window._notifier.Instance
		local listLayout = frame and frame:FindFirstChildOfClass("UIListLayout")
		local restoreFrame = frame and snapshot(frame, { "AnchorPoint", "Position" })
		local restoreLayout = listLayout and snapshot(listLayout, { "VerticalAlignment" })

		local function apply()
			if not frame then
				return
			end
			local isTop = notif.Side:find("Top") ~= nil
			local isLeft = notif.Side:find("Left") ~= nil
			frame.AnchorPoint = Vector2.new(isLeft and 0 or 1, isTop and 0 or 1)
			frame.Position = UDim2.new(isLeft and 0 or 1, isLeft and 16 or -16, isTop and 0 or 1, (isTop and 16 or -16) + notif.Offset)
			if listLayout then
				listLayout.VerticalAlignment = isTop and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Bottom
			end
		end

		NotifSection:AddDropdown({
			Title = "Position",
			Options = { "TopLeft", "TopRight", "BottomLeft", "BottomRight" },
			Default = notif.Side,
			Flag = "NotifSide",
			Callback = function(side)
				notif.Side = side
				apply()
			end,
		})
		NotifSection:AddSlider({
			Title = "Vertical offset",
			Min = -200, Max = 200, Step = 5, Default = notif.Offset, Suffix = "px",
			Flag = "NotifOffset",
			Callback = function(value)
				notif.Offset = value
				apply()
			end,
		})
		track(function()
			if restoreFrame then
				restoreFrame()
			end
			if restoreLayout then
				restoreLayout()
			end
		end)
	end

	-- Auto pickup / auto loadout ---------------------------------------------------------

	do
		-- Ground supplies are BaseParts named "_drop" in workspace: a child model
		-- "AmmoBalanced" marks an ammo pack, "Health" a health pack. The server picks them
		-- up on touch, and firetouchinterest from our root works at any distance
		-- (measured: health packs 73/99/123 studs away were picked up), so we never move.
		local autoPickup = { Enabled = false, Interval = 0.25 }
		local pickupThread = nil

		local function needsHealth()
			local char = LocalPlayer.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			return hum ~= nil and hum.Health > 0 and hum.Health < hum.MaxHealth - 1
		end

		local function needsAmmo()
			local needed = false
			pcall(function()
				local fc = require(LocalPlayer.PlayerScripts.Controllers.FighterController)
				local items = fc and fc.LocalFighter and (rawget(fc.LocalFighter, "Items") or fc.LocalFighter.Items)
				if not items then return end
				for _, it in pairs(items) do
					local info = it.Info
					if info and info.MaxAmmo then
						local ammo = it:Get("Ammo") or 0
						local reserve = it:Get("AmmoReserve") or 0
						local maxReserve = info.MaxAmmoReserve
						if ammo < info.MaxAmmo or (maxReserve and reserve < maxReserve) then
							needed = true
						end
					end
				end
			end)
			return needed
		end

		local function setAutoPickup(on)
			autoPickup.Enabled = on
			pickupThread = nil
			if not on then
				return true
			end
			if type(firetouchinterest) ~= "function" then
				autoPickup.Enabled = false
				return false
			end
			local thread
			thread = task.spawn(function()
				local myThread = coroutine.running()
				pickupThread = myThread
				local lastTouch = {}
				while autoPickup.Enabled and pickupThread == myThread do
					local char = LocalPlayer.Character
					local root = char and char:FindFirstChild("HumanoidRootPart")
					if root then
						local wantHealth, wantAmmo = needsHealth(), needsAmmo()
						if wantHealth or wantAmmo then
							local now = tick()
							for _, part in workspace:GetChildren() do
								if part.Name == "_drop" and part:IsA("BasePart") then
									local wanted = (wantAmmo and part:FindFirstChild("AmmoBalanced") ~= nil)
										or (wantHealth and part:FindFirstChild("Health") ~= nil)
									if wanted and now - (lastTouch[part] or 0) >= 0.6 then
										lastTouch[part] = now
										pcall(firetouchinterest, root, part, 0)
										pcall(firetouchinterest, root, part, 1)
									end
								end
							end
						end
					end
					task.wait(autoPickup.Interval)
				end
			end)
			return true
		end

		local pickupToggle
		pickupToggle = MatchSection:AddToggle({
			Title = "Auto pickup",
			Description = "Grab ammo and health drops when you need them, from any distance",
			Default = false,
			Flag = "AutoPickup",
			Callback = function(on)
				if not setAutoPickup(on) and on then
					Window:Notify({ Title = "Auto pickup", Content = "Your executor has no firetouchinterest", Icon = "error" })
					task.defer(function()
						pickupToggle:Set(false, true)
					end)
				end
			end,
		})
		track(function()
			setAutoPickup(false)
		end)

		-- Fires Remotes.Replication.Fighter.PickWeapons with the chosen list when
		-- the weapon pick screen shows up.
		local autoLoadout = { Enabled = false, Weapons = { "Assault Rifle", "Handgun", "Fists", "Grenade" } }

		-- Slot of each weapon: the pick screen fills Primary, Secondary, Melee, Utility in
		-- that order and the server expects the list in the same order, but the multi
		-- dropdown returns the picks in option order.
		local LOADOUT_SLOT = {
			["Assault Rifle"] = 1, ["Shotgun"] = 1, ["Sniper"] = 1, ["SMG"] = 1, ["Burst Rifle"] = 1,
			["Bow"] = 1, ["Crossbow"] = 1, ["Minigun"] = 1, ["RPG"] = 1, ["Energy Rifle"] = 1,
			["Handgun"] = 2, ["Revolver"] = 2, ["Flare Gun"] = 2, ["Uzi"] = 2,
			["Knife"] = 3, ["Fists"] = 3, ["Katana"] = 3, ["Chainsaw"] = 3,
			["Grenade"] = 4, ["Flashbang"] = 4, ["Smoke Grenade"] = 4,
		}
		local function orderedLoadout()
			local bySlot, extra = {}, {}
			for _, name in autoLoadout.Weapons do
				local slot = LOADOUT_SLOT[name]
				if slot and not bySlot[slot] then
					bySlot[slot] = name
				elseif not slot then
					table.insert(extra, name)
				end
			end
			local list = {}
			for slot = 1, 4 do
				if bySlot[slot] then table.insert(list, bySlot[slot]) end
			end
			for _, name in extra do table.insert(list, name) end
			return list
		end

		local lastAutoLoadoutAt = 0
		local function tryAutoLoadout()
			if not autoLoadout.Enabled or #autoLoadout.Weapons == 0 then
				return
			end
			if os.clock() - lastAutoLoadoutAt < 1 then
				return
			end
			lastAutoLoadoutAt = os.clock()
			local remotes = ReplicatedStorage:FindFirstChild("Remotes")
			local replication = remotes and remotes:FindFirstChild("Replication")
			local fighter = replication and replication:FindFirstChild("Fighter")
			local pick = fighter and fighter:FindFirstChild("PickWeapons")
			local list = orderedLoadout()
			if not pick or #list == 0 then
				return
			end
			-- Like the pick screen's Finish(): a staggered-spawn duel wants the pick sent
			-- ahead of time through its own remote.
			local remote = pick
			pcall(function()
				local duels = moduleAt({ "Controllers", "DuelController" })
				local duel = duels and duels:GetDuel(LocalPlayer)
				local dueler = duel and duel.LocalDueler
				if dueler and dueler:GetStaggeredSpawnsTurn() then
					local ahead = remotes.Duels:FindFirstChild("PickWeaponsAheadOfTime")
					if ahead then remote = ahead end
				end
			end)
			pcall(remote.FireServer, remote, list)
			-- Close the pick screen the way the game's own Finish does.
			pcall(function()
				local pages = moduleAt({ "Modules", "UserInterface", "Pages" })
				if pages and pages.PageSystem and pages.PageSystem.CurrentPage then
					local name = pages.PageSystem.CurrentPage.Name
					if name == "PickWeapons" or name == "PickWeaponsList" then
						pages.PageSystem:CloseCurrentPage()
					end
				end
			end)
		end

		MatchSection:AddToggle({
			Title = "Auto loadout",
			Description = "Equip the weapons below when the pick screen appears",
			Default = false,
			Flag = "AutoLoadout",
			Callback = function(on)
				autoLoadout.Enabled = on
			end,
		})
		MatchSection:AddDropdown({
			Title = "Loadout weapons",
			Options = {
				"Assault Rifle", "Handgun", "Shotgun", "Sniper", "SMG", "Revolver",
				"Knife", "Fists", "Grenade", "Flashbang", "Smoke Grenade",
			},
			Multi = true,
			Default = autoLoadout.Weapons,
			Flag = "AutoLoadoutWeapons",
			Callback = function(selected)
				autoLoadout.Weapons = type(selected) == "table" and selected or {}
			end,
		})
		-- The game opens its pick screen through Pages:OpenPickWeaponsPage (the page frames
		-- already exist, so nothing new is added to the GUI when it opens): run after that.
		pcall(function()
			local pages = moduleAt({ "Modules", "UserInterface", "Pages" })
			if not pages then return end
			local class = pages
			if rawget(class, "OpenPickWeaponsPage") == nil then
				local meta = getmetatable(pages)
				class = meta and type(meta.__index) == "table" and meta.__index or pages
			end
			patch(class, "OpenPickWeaponsPage", function(original)
				return function(self, ...)
					local results = table.pack(original(self, ...))
					if autoLoadout.Enabled then
						task.delay(0.6, tryAutoLoadout)
					end
					return table.unpack(results, 1, results.n)
				end
			end)
		end)
		track(PlayerGui.DescendantAdded:Connect(function(descendant)
			if autoLoadout.Enabled and (descendant.Name == "PickWeapons" or descendant.Name == "PickWeaponsList"
				or descendant.Name == "PickWeaponsPage" or descendant.Name == "WeaponSelect") then
				task.delay(0.6, tryAutoLoadout)
			end
		end))
	end

	-- Rank charm override ------------------------------------------------------------------
	-- Charm:_SetupSeasonRankCharm reads the ELO / leaderboard rank from the
	-- charm's metadata; they're swapped in for that call only (your screen only).

	do
		-- Lives in the Cosmetics tab (own "Rank Charm" sub-tab); falls back to Misc when the
		-- Cosmetics tab could not be built.
		local rankSub = MD3.LYCosmeticsTab and MD3.LYCosmeticsTab:AddSubTab("Rank Charm", { Columns = 1 })
		local RankCharmSection = (rankSub or MiscTab):AddSection("Rank Charm Override")
		local rankCharm = { Enabled = false, ELO = 3000, LeaderboardRank = 1 }

		-- The charm on the equipped weapon (Charm module) reads its ELO / rank from the
		-- equipped data's metadata. A charm equipped without metadata (never ranked) has none,
		-- so one is made for the duration of the call and removed again.
		local function hookCharm()
			local class = moduleAt({ "Modules", "Charm" })
			return class ~= nil and patch(class, "_SetupSeasonRankCharm", function(original)
				return function(self, ...)
					local data = rankCharm.Enabled and type(self) == "table" and self.EquippedData
					if type(data) ~= "table" then
						return original(self, ...)
					end
					local createdMeta = type(data.Metadata) ~= "table"
					local meta = createdMeta and {} or data.Metadata
					local realELO, realRank = meta.SeasonELO, meta.SeasonLeaderboardRank
					meta.SeasonELO, meta.SeasonLeaderboardRank = rankCharm.ELO, rankCharm.LeaderboardRank
					if createdMeta then
						data.Metadata = meta
					end
					local result = table.pack(pcall(original, self, ...))
					if createdMeta then
						data.Metadata = nil
					else
						meta.SeasonELO, meta.SeasonLeaderboardRank = realELO, realRank
					end
					if not result[1] then
						error(result[2], 0)
					end
					return table.unpack(result, 2, result.n)
				end
			end)
		end

		-- The charm previews in the loadout / catalog (CosmeticViewportFrame) take the values
		-- from the player's own season data instead; with the override on they get the custom
		-- ones too, through the game's own SeasonLibrary:FormatSeasonRankCharm.
		local function hookPreview()
			local class = moduleAt({ "Modules", "CosmeticViewportFrame" })
			return class ~= nil and patch(class, "_SetupSeasonRankCharm", function(original)
				return function(self, model, ...)
					if rankCharm.Enabled and type(self) == "table" and type(self.Name) == "string"
						and #self.Name >= 8 and string.sub(self.Name, 1, 7) == "Season " and typeof(model) == "Instance"
					then
						local number = tonumber(string.sub(self.Name, 8))
						local okLib, library = pcall(function()
							return require(ReplicatedStorage.Modules.SeasonLibrary)
						end)
						local season = okLib and type(library) == "table" and number and library.SeasonsByVersion[number]
						if season then
							local ok = pcall(library.FormatSeasonRankCharm, library, model, season.Name, rankCharm.ELO, rankCharm.LeaderboardRank)
							if ok then
								return
							end
						end
					end
					return original(self, model, ...)
				end
			end)
		end

		local hooked, previewHooked = false, false
		RankCharmSection:AddToggle({
			Title = "Override rank charm",
			Description = "Show a custom rank on your Season charm (only you see it; re-equip the charm to refresh)",
			Default = false,
			Flag = "RankCharmOverride",
			Callback = function(on)
				rankCharm.Enabled = on
				hooked = hooked or hookCharm()
				previewHooked = previewHooked or hookPreview()
			end,
		})
		RankCharmSection:AddSlider({ Title = "ELO", Min = 0, Max = 10000, Step = 50, Default = rankCharm.ELO, Flag = "RankCharmELO", Callback = function(v) rankCharm.ELO = v end })
		RankCharmSection:AddSlider({ Title = "Leaderboard rank", Min = 1, Max = 500, Step = 1, Default = rankCharm.LeaderboardRank, Flag = "RankCharmLeaderboardRank", Callback = function(v) rankCharm.LeaderboardRank = v end })
	end

	-- Auras ---------------------------------------------------------------------------------
	-- 46 particle auras on your own character (only you see them). The data (emitter pool +
	-- per-aura part layout, read from the external loader's config tables) is embedded below as
	-- MD3.LYAuraSource (same text as saved/solix_auras.lua) and only parsed the first time an aura
	-- is switched on.

	do
		local AURA_NAMES = {
			"angel1", "angel2", "antannas", "aura", "aura2", "aura_44", "bats", "butterfly", "chains", "cloudy",
			"cloudy2", "collapse", "dust", "energy", "evil", "expand", "fast", "flowers", "flowers2", "greenleafs",
			"halo", "hearts", "hearts2", "minimal", "moon", "orbits", "planet", "planet2", "pop", "risen",
			"scorching", "shatterspace", "sky", "smoke", "snowflakes", "snowflakes2", "sparkle", "stardom",
			"starlight", "starlight2", "stars", "stars2", "strike", "studio", "studio2", "waves",
		}
		-- Data records use R6 and R15 limb names; map whichever the character does not have.
		local LIMB_FALLBACK = {
			["Left Leg"] = { "LeftUpperLeg", "LeftLowerLeg", "LeftFoot" },
			["Right Leg"] = { "RightUpperLeg", "RightLowerLeg", "RightFoot" },
			["Left Arm"] = { "LeftUpperArm", "LeftLowerArm", "LeftHand" },
			["Right Arm"] = { "RightUpperArm", "RightLowerArm", "RightHand" },
			Torso = { "UpperTorso", "LowerTorso" },
			UpperTorso = { "Torso" },
			LowerTorso = { "Torso" },
			LeftUpperArm = { "Left Arm" }, LeftLowerArm = { "Left Arm" }, LeftHand = { "Left Arm" },
			RightUpperArm = { "Right Arm" }, RightLowerArm = { "Right Arm" }, RightHand = { "Right Arm" },
			LeftUpperLeg = { "Left Leg" }, LeftLowerLeg = { "Left Leg" }, LeftFoot = { "Left Leg" },
			RightUpperLeg = { "Right Leg" }, RightLowerLeg = { "Right Leg" }, RightFoot = { "Right Leg" },
		}
		local ENUMS = {
			Orientation = Enum.ParticleOrientation,
			Shape = Enum.ParticleEmitterShape,
			ShapeStyle = Enum.ParticleEmitterShapeStyle,
			ShapeInOut = Enum.ParticleEmitterShapeInOut,
			EmissionDirection = Enum.NormalId,
		}
		local RANGES = { Lifetime = true, Speed = true, RotSpeed = true, Rotation = true }
		local SEQUENCES = { Size = true, Transparency = true, Squash = true }
		local aura = {
			Enabled = false,
			Names = { "aura_44" },
			Intensity = 1,
			Color = Color3.new(1, 1, 1),
			ColorOverride = false, -- off until you pick a color (or press the button to go back)
			Ready = false, -- set a few seconds after load so restoring the saved config isn't taken as a pick
			Generation = 0,
			Alive = true,
			Loading = false,
			Data = nil,
			Character = nil,
			Created = {},
			Effects = {}, -- { emitter / beam, its original color keypoints } for live recoloring
			LastRecolor = 0,
			Failed = 0,
			RetryAt = 0,
		}

		local function toCFrame(t)
			return CFrame.new(t[1], t[2], t[3], t[4], t[5], t[6], t[7], t[8], t[9], t[10], t[11], t[12])
		end

		local function numberSequence(list)
			local points, last = {}, -1
			for _, key in list do
				if key[1] > last then
					table.insert(points, NumberSequenceKeypoint.new(key[1], key[2], key[3] or 0))
					last = key[1]
				end
			end
			return NumberSequence.new(points)
		end

		local function colorSequence(list)
			local points, last = {}, -1
			for _, key in list do
				if key[1] > last then
					local color = Color3.new(key[2], key[3], key[4])
					-- Any non-white color recolors the aura, keeping the light / dark pattern of its keypoints.
					local tint = aura.Color
					if aura.ColorOverride then
						-- black keypoints (aura_44 is mostly black smoke) become a slightly darker shade
						local value = 0.85 + 0.15 * math.max(key[2], key[3], key[4])
						color = Color3.new(tint.R * value, tint.G * value, tint.B * value)
					end
					table.insert(points, ColorSequenceKeypoint.new(key[1], color))
					last = key[1]
				end
			end
			return ColorSequence.new(points)
		end

		-- Properties are applied one by one so a value this client rejects only skips itself.
		local function applyProperties(instance, props)
			for key, value in props do
				if key ~= "A0" and key ~= "A1" then
					local ok = pcall(function()
						if key == "Color" then
							instance.Color = colorSequence(value)
						elseif SEQUENCES[key] then
							instance[key] = numberSequence(value)
						elseif RANGES[key] then
							instance[key] = NumberRange.new(value[1], value[2])
						elseif key == "Acceleration" then
							instance.Acceleration = Vector3.new(value[1], value[2], value[3])
						elseif key == "SpreadAngle" then
							instance.SpreadAngle = Vector2.new(value[1], value[2])
						elseif ENUMS[key] then
							instance[key] = ENUMS[key][value]
						else
							instance[key] = value
						end
					end)
					if not ok then
						aura.Failed += 1
					end
				end
			end
		end

		local function findLimb(character, name)
			local direct = character:FindFirstChild(name)
			if direct and direct:IsA("BasePart") then
				return direct
			end
			for _, other in LIMB_FALLBACK[name] or {} do
				local part = character:FindFirstChild(other)
				if part and part:IsA("BasePart") then
					return part
				end
			end
			return nil
		end

		local function clearAura()
			for _, instance in aura.Created do
				pcall(game.Destroy, instance)
			end
			aura.Created = {}
			aura.Effects = {}
			aura.Hidden = nil
			aura.Character = nil
		end

		-- Animated pickers (Rainbow / Breathing / Cycle) fire every frame: the colors are swapped on
		-- the effects that exist instead of rebuilding the whole aura.
		local function recolorAura()
			for _, entry in aura.Effects do
				local effect = entry[1]
				if effect.Parent then
					pcall(function()
						effect.Color = colorSequence(entry[2])
					end)
				end
			end
		end

		-- Builds one aura on `character`; returns false when the character is missing a limb it needs.
		local function buildAura(character, name)
			local records = aura.Data.auras[name]
			local root = character:FindFirstChild("HumanoidRootPart")
			if not records or not root then
				return false
			end
			local pool = aura.Data.pool
			local created = aura.Created
			local folder = own(Instance.new("Folder"))
			folder.Name = MD3.Env.RandomName()
			folder.Parent = camera()
			table.insert(created, folder)
			local extras = {}
			aura.Failed = 0

			for _, record in records do
				local part
				if record.ExtraPart then
					local parent = extras[record.ParentPart] or findLimb(character, record.ParentPart or "") or root
					part = Instance.new("Part")
					part.Name = record.Name
					part.Size = Vector3.new(record.Size[1], record.Size[2], record.Size[3])
					part.Transparency = 1
					part.CanCollide, part.CanQuery, part.CanTouch = false, false, false
					part.CastShadow = false
					part.Massless = true
					part.Anchored = false
					part.CFrame = parent.CFrame * toCFrame(record.RelativeCFrame)
					local weld = Instance.new("Weld")
					weld.Part0, weld.Part1 = parent, part
					weld.C0 = toCFrame(record.RelativeCFrame)
					weld.Parent = part
					part.Parent = folder
					extras[record.Name] = extras[record.Name] or part
				else
					part = findLimb(character, record.Name)
				end

				if part then
					local namedAttachments, pendingBeams = {}, {}
					local function makeEffect(id, parent)
						local props = pool[id]
						if not props then
							return
						end
						local effect
						if props.A0 then
							effect = Instance.new("Beam")
							table.insert(pendingBeams, { effect, props.A0, props.A1 })
						else
							effect = Instance.new("ParticleEmitter")
						end
						applyProperties(effect, props)
						if props.Color then
							table.insert(aura.Effects, { effect, props.Color })
						end
						if not props.A0 then
							effect.Rate = (props.Rate or 20) * aura.Intensity
						end
						effect.Parent = parent
						if parent == part then
							table.insert(created, effect)
						end
					end

					for _, att in record.attachments or {} do
						local attachment = Instance.new("Attachment")
						attachment.Name = att.Name
						attachment.CFrame = toCFrame(att.CFrame)
						attachment.Parent = part
						table.insert(created, attachment)
						namedAttachments[att.Name] = namedAttachments[att.Name] or attachment
						for _, id in att.children or {} do
							makeEffect(id, attachment)
						end
					end
					for _, id in record.beams or {} do
						makeEffect(id, part)
					end
					for _, id in record.particles or {} do
						makeEffect(id, part)
					end
					for _, pending in pendingBeams do
						local beam = pending[1]
						beam.Attachment0 = namedAttachments[pending[2]]
						beam.Attachment1 = namedAttachments[pending[3]]
						if not (beam.Attachment0 and beam.Attachment1) then
							beam:Destroy()
						end
					end
				end
			end
			aura.Character = character
			return true
		end

		local function loadAuraData()
			if aura.Data then
				return true
			end
			local chunk = type(MD3.LYAuraSource) == "string" and loadstring(MD3.LYAuraSource)
			local ok, result = pcall(chunk or error, "aura data missing")
			if ok and type(result) == "table" and type(result.pool) == "table" and type(result.auras) == "table" then
				aura.Data = result
			end
			return aura.Data ~= nil
		end

		-- First person: the camera sits in the head. The aura is switched off there and back on in
		-- third person (and while spectating from further away).
		local function updateAuraVisibility(force)
			local character = aura.Character
			local head = character and character:FindFirstChild("Head")
			local cam = camera()
			-- The game hides your own head locally (LocalTransparencyModifier 1) in first person, which
			-- holds while jumping too; the camera-distance check covers other cameras.
			local hide = head ~= nil and (head.LocalTransparencyModifier >= 0.9
				or (cam ~= nil and (cam.CFrame.Position - head.Position).Magnitude < 3))
			if not force and hide == aura.Hidden then
				return
			end
			aura.Hidden = hide
			for _, entry in aura.Effects do
				pcall(function()
					entry[1].Enabled = not hide
				end)
			end
		end

		local function characterReady(character)
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			return humanoid ~= nil and humanoid.Health > 0 and character:FindFirstChild("HumanoidRootPart") ~= nil
				and character:FindFirstChild("Head") ~= nil
				and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")) ~= nil
		end

		local function refreshAura()
			clearAura()
			if not aura.Enabled or aura.Loading then
				return
			end
			if not aura.Data then
				aura.Loading = true
				task.spawn(function()
					local ok = pcall(loadAuraData) and aura.Data ~= nil
					aura.Loading = false
					if not ok then
						Window:Notify({ Title = "Auras", Content = "Couldn't load the aura data", Icon = "error" })
					elseif aura.Alive then
						refreshAura()
					end
				end)
				return
			end
			local character = LocalPlayer.Character
			if characterReady(character) then
				local ok, err = true, true
				for _, name in aura.Names do
					local okOne, resOne = pcall(buildAura, character, name)
					if not okOne then
						ok, err = false, resOne
						break
					elseif not resOne then
						err = false
					end
				end
				aura.Character = ok and err and character or nil
				if ok and err then
					updateAuraVisibility(true)
				end
				if ok and not err then
					clearAura()
					aura.RetryAt = os.clock() + 10
				elseif not ok then
					clearAura()
					aura.RetryAt = os.clock() + 15
					Window:Notify({ Title = "Auras", Content = "Couldn't build the aura: " .. tostring(err), Icon = "error" })
				end
			end
		end

		local AuraSection = VisualsTab:AddSection("Auras")
		AuraSection:AddToggle({
			Title = "Enabled",
			Description = "Particle aura around your character (only you see it)",
			Default = false,
			Flag = "AuraEnabled",
			Callback = function(on)
				aura.Enabled = on
				refreshAura()
			end,
		})
		-- Debounced so dragging the color / slider does not rebuild on every step.
		local function refreshLater()
			aura.Generation += 1
			local generation = aura.Generation
			task.delay(0.3, function()
				if generation == aura.Generation and aura.Alive then
					refreshAura()
				end
			end)
		end
		AuraSection:AddDropdown({
			Title = "Auras",
			Description = "Pick one or several to stack",
			Options = AURA_NAMES,
			Multi = true,
			Default = aura.Names,
			Flag = "AuraNames",
			Callback = function(selected)
				local picked = {}
				if type(selected) == "table" then
					local lookup = {}
					for key, value in selected do
						if type(key) == "string" and value == true then
							lookup[key] = true
						elseif type(value) == "string" then
							lookup[value] = true
						end
					end
					for _, name in AURA_NAMES do -- keep the list's order
						if lookup[name] then
							table.insert(picked, name)
						end
					end
				elseif type(selected) == "string" then
					picked = { selected }
				end
				aura.Names = picked
				refreshLater()
			end,
		})
		AuraSection:AddColorPicker({
			Title = "Color",
			Description = "Pick a color to recolor the aura (any color, white included)",
			Default = aura.Color,
			Flag = "AuraColor",
			Callback = function(value)
				aura.Color = value
				if aura.Ready or value.R < 0.99 or value.G < 0.99 or value.B < 0.99 then
					aura.ColorOverride = true
				end
				local now = os.clock()
				if aura.ColorOverride and now - aura.LastRecolor >= 0.05 then
					aura.LastRecolor = now
					recolorAura()
				end
				refreshLater() -- settles on the exact final color once the picker stops changing
			end,
		})
		task.delay(4, function()
			aura.Ready = true
		end)
		AuraSection:AddSlider({
			Title = "Intensity",
			Description = "Particle emission rate multiplier",
			Min = 0.1, Max = 2, Step = 0.05, Default = aura.Intensity, Suffix = "x",
			Flag = "AuraIntensity",
			Callback = function(value)
				if value ~= aura.Intensity then
					aura.Intensity = value
					refreshLater()
				end
			end,
		})

		-- Respawns, the match starting and the lobby swapping characters.
		task.spawn(function()
			while aura.Alive do
				task.wait(0.75)
				if aura.Enabled and aura.Data and not aura.Loading then
					local character = LocalPlayer.Character
					local built = aura.Character
					if built and (built ~= character or not built:IsDescendantOf(workspace) or not characterReady(built)) then
						clearAura()
						built = nil
					end
					if not built and characterReady(character) and os.clock() >= aura.RetryAt then
						refreshAura()
					end
				end
			end
		end)
		task.spawn(function()
			while aura.Alive do
				task.wait(0.1)
				if aura.Character then
					updateAuraVisibility(false)
				end
			end
		end)
		track(function()
			aura.Alive = false
			aura.Enabled = false
			clearAura()
		end)
	end

