	-- Hacker detector & silent load ------------------------------------------------------------
	-- (The mod detector is in Misc › Miscellaneous.)

	do
		local DetectorSection = MiscTab:AddSection("Detectors")
		local BASE_SPEED = 16
		local hacker = { Enabled = false, Threshold = 2, Generation = 0 }

		-- Shared so the ragebot's "prioritize hackers" can read the same flags.
		getgenv().InstanceHackerFlagged = getgenv().InstanceHackerFlagged or {}

		local function monitor(generation)
			local positions = {}
			local flagged = getgenv().InstanceHackerFlagged
			table.clear(flagged)
			while hacker.Enabled and generation == hacker.Generation do
				local now = os.clock()
				for _, player in Players:GetPlayers() do
					local character = player ~= LocalPlayer and player.Character
					local root = character and character:FindFirstChild("HumanoidRootPart")
					if root then
						local previous = positions[player]
						if previous and now - previous.Time > 0.1 then
							local speed = (root.Position - previous.Position).Magnitude / (now - previous.Time)
							-- Big jumps are usually respawns / teleports, not movement.
							if speed > BASE_SPEED * hacker.Threshold and speed < 500 and not flagged[player] then
								flagged[player] = true
								Window:Notify({
									Title = "Suspicious player",
									Content = ("%s (%.0f studs/s)"):format(player.Name, speed),
									Icon = "warning",
								})
							end
						end
						positions[player] = { Position = root.Position, Time = now }
					end
				end
				task.wait(0.5)
			end
		end

		DetectorSection:AddToggle({
			Title = "Hacker detector",
			Description = "Flag players moving much faster than normal (speed hacks / fly)",
			Default = false,
			Flag = "HackerDetector",
			Callback = function(on)
				hacker.Enabled = on
				hacker.Generation += 1
				if on then
					task.spawn(monitor, hacker.Generation)
				end
			end,
		})
		DetectorSection:AddSlider({
			Title = "Speed threshold",
			Description = "Flag above this multiple of the base walk speed",
			Min = 1.5, Max = 5, Step = 0.1, Default = hacker.Threshold, Suffix = "x",
			Flag = "HackerThreshold",
			Callback = function(v)
				hacker.Threshold = v
			end,
		})
		track(function()
			hacker.Enabled = false
			hacker.Generation += 1
		end)

		-- Silent load: the game's own notification popups are dropped.
		local silentLoad = false
		local hookedNotifications = false
		local function hookNotifications()
			local class = moduleAt({ "Modules", "UserInterface", "Notifications" })
			if not class then
				return false
			end
			local function silence(original)
				return function(self, ...)
					if silentLoad then
						return
					end
					return original(self, ...)
				end
			end
			local played = patch(class, "Play", silence)
			local queued = patch(class, "Queue", silence)
			return played or queued
		end
		DetectorSection:AddToggle({
			Title = "Silent load",
			Description = "Next start: no loading screen, the hub starts hidden, no popups (RightShift opens it). Also hides the game's notification popups",
			Default = false,
			Flag = "SilentLoad",
			Callback = function(on)
				silentLoad = on
				hookedNotifications = hookedNotifications or hookNotifications()
			end,
		})
	end
end)
if not extrasOk then
	warn("Lin67 Hub: extra features failed to load:", extrasError)
	Window:Notify({ Title = "Some features failed to load", Content = tostring(extrasError), Icon = "error", Duration = 8 })
end

-- MD3 puts each tab's sub-tab bar inside the tab's scrolling page, so it
-- scrolled away with the content. Pin it over the top of the page instead:
-- the page's top padding makes room for it and its backdrop (the page area's
-- own color) hides content scrolled up underneath. Tab switches tween the
-- page's Position, so the bar lives beside the page and follows its Visible.
do
	local NAV_HEIGHT, EDGE = 42, 12
	local pagesFrame = CombatTab.Instance.Parent

	local function pin(page, nav)
		if nav.Parent ~= page then
			return
		end
		local padding = page:FindFirstChildOfClass("UIPadding")
		local layout = page:FindFirstChildOfClass("UIListLayout")
		local gap = layout and layout.Padding.Offset or 8
		local top = padding and padding.PaddingTop.Offset or EDGE
		local scrollbar = page.ScrollBarThickness

		local bar = Instance.new("Frame")
		bar.Name = page.Name .. "_SubNav"
		bar.BackgroundTransparency = 1
		bar.BorderSizePixel = 0
		bar.Size = UDim2.new(1, -scrollbar, 0, top + NAV_HEIGHT + gap / 2)
		bar.ZIndex = page.ZIndex + 5
		for _, piece in { "Rounded", "Square" } do
			local fill = Instance.new("Frame")
			fill.Name = piece
			fill.BorderSizePixel = 0
			fill.ZIndex = bar.ZIndex
			if piece == "Rounded" then
				fill.Size = UDim2.fromScale(1, 1)
				local corner = pagesFrame:FindFirstChildOfClass("UICorner")
				if corner then
					corner:Clone().Parent = fill
				end
			else
				-- Squares off the bottom corners; only the top follows the page's rounding.
				fill.Position = UDim2.new(0, 0, 0.5, 0)
				fill.Size = UDim2.fromScale(1, 0.5)
			end
			local function paint()
				fill.BackgroundColor3 = pagesFrame.BackgroundColor3
				fill.BackgroundTransparency = pagesFrame.BackgroundTransparency
			end
			paint()
			track(pagesFrame:GetPropertyChangedSignal("BackgroundColor3"):Connect(paint))
			track(pagesFrame:GetPropertyChangedSignal("BackgroundTransparency"):Connect(paint))
			fill.Parent = bar
		end

		nav.Position = UDim2.new(0, EDGE, 0, top)
		nav.Size = UDim2.new(1, -EDGE * 2 + scrollbar, 0, NAV_HEIGHT)
		nav.ZIndex = bar.ZIndex + 1
		nav.Parent = bar
		if padding then
			padding.PaddingTop = UDim.new(0, top + NAV_HEIGHT + gap)
		end

		bar.Visible = page.Visible
		track(page:GetPropertyChangedSignal("Visible"):Connect(function()
			bar.Visible = page.Visible
		end))
		track(page.Destroying:Connect(function()
			bar:Destroy()
		end))
		bar.Parent = pagesFrame
	end

	local function watchPage(page)
		if not page:IsA("ScrollingFrame") then
			return
		end
		local nav = page:FindFirstChild("SubNavBar")
		if nav then
			pin(page, nav)
			return
		end
		-- The bar is created with the tab's first section.
		local added
		added = page.ChildAdded:Connect(function(child)
			if child.Name == "SubNavBar" then
				added:Disconnect()
				task.defer(pin, page, child)
			end
		end)
		track(added)
	end

	if pagesFrame then
		for _, page in pagesFrame:GetChildren() do
			watchPage(page)
		end
		track(pagesFrame.ChildAdded:Connect(watchPage))
	end
end

