local nameBlock = Watermark:AddBlock({ Icon = "person", Text = LocalPlayer.DisplayName })
local function updateNameBlock()
	nameBlock:SetText(MD3.LYPresentedName and MD3.LYPresentedName() or LocalPlayer.DisplayName)
end
-- Deferred: OnChanged can run before the element's own Callback updates the spoof.
for _, flag in { "MyDisplaySpoof", "MyDisplayValue", "MyVerifiedSpoof", "MyPremiumSpoof" } do
	local element = Window.Flags[flag]
	if element then
		element:OnChanged(function()
			task.defer(updateNameBlock)
		end)
	end
end
Window:AddKeybindList({ Title = "Keybinds" })

-- Added after the HUD so the settings page also gets the HUD controls.
local SettingsTab = Window:AddSettingsTab()

-- Dark mode: dead weight on a skin pinned to Mode = "Dark" -- the toggle can
-- only throw the whole palette into a light theme nobody asked for. The row is
-- destroyed (gone from the layout, MD3_DarkMode unregistered so saved configs
-- skip it), and Set is stubbed because MD3's own theme listener still holds
-- this element: without the stub a later mode change would render into
-- destroyed instances.
do
	local darkMode = Window.Flags and Window.Flags["MD3_DarkMode"]
	if darkMode then
		darkMode:Destroy()
		darkMode.Set = function() end
	end
end

-- Config import / export -------------------------------------------------------------

-- Share a whole config as one JSON text: copied to the clipboard on export, pasted or
-- read from the clipboard on import. Same value encoding as the saved config files.
MD3.LYConfigShare = function()
	local ConfigShare = SettingsTab:AddSection("Config Share")
	local clipboardSet = setclipboard or toclipboard or set_clipboard or (Clipboard and Clipboard.set)
	local clipboardGet = getclipboard or get_clipboard

	local function serializeValue(value)
		local t = typeof(value)
		if t == "Color3" then
			return { __type = "Color3", hex = value:ToHex() }
		elseif t == "EnumItem" then
			return { __type = "EnumItem", enum = tostring(value.EnumType), name = value.Name }
		elseif t == "table" then
			local out = {}
			for k, v in value do
				out[k] = serializeValue(v)
			end
			return out
		end
		return value
	end

	local function deserializeValue(value)
		if type(value) ~= "table" then
			return value
		end
		if value.__type == "Color3" then
			local ok, color = pcall(Color3.fromHex, tostring(value.hex))
			return ok and color or nil
		elseif value.__type == "EnumItem" then
			local ok, item = pcall(function()
				return Enum[value.enum][value.name]
			end)
			return ok and item or nil
		end
		local out = {}
		for k, v in value do
			out[k] = deserializeValue(v)
		end
		return out
	end

	local function exportConfig()
		local data = {}
		for flag, element in Window.Flags do
			if element.Save ~= false then
				local ok, value = pcall(function()
					return element.GetSaveValue and element:GetSaveValue() or element.Value
				end)
				if ok then
					data[flag] = serializeValue(value)
				end
			end
		end
		return HttpService:JSONEncode(data)
	end

	local function importConfig(text)
		text = trim(tostring(text or ""))
		if text == "" then
			return false, "nothing to import"
		end
		local ok, data = pcall(HttpService.JSONDecode, HttpService, text)
		if not ok or type(data) ~= "table" then
			return false, "not a valid config"
		end
		local applied = 0
		for flag, value in data do
			local element = Window.Flags[flag]
			if element and element.Set then
				if pcall(element.Set, element, deserializeValue(value)) then
					applied += 1
				end
			end
		end
		return true, applied
	end

	local function notify(title, content, icon)
		Window:Notify({ Title = title, Content = content, Icon = icon })
	end

	local pasted = ""
	ConfigShare:AddButton({
		Title = "Export config",
		Description = "Copy every setting as text to the clipboard",
		Icon = "save",
		Callback = function()
			local json = exportConfig()
			if type(clipboardSet) == "function" and pcall(clipboardSet, json) then
				notify("Config exported", "Copied to the clipboard", "save")
			else
				MD3.Env.MakeFolder("Lin67Hub")
				if MD3.Env.WriteFile("Lin67Hub/export.json", json) then
					notify("Config exported", "No clipboard: saved to Lin67Hub/export.json", "save")
				else
					notify("Export failed", "Clipboard and files are unavailable", "error")
				end
			end
		end,
	})
	if type(clipboardGet) == "function" then
		ConfigShare:AddButton({
			Title = "Import from clipboard",
			Description = "Apply a config you copied",
			Icon = "folder",
			Callback = function()
				local okGet, text = pcall(clipboardGet)
				local ok, result = importConfig(okGet and text or "")
				notify(ok and "Config imported" or "Import failed", ok and (tostring(result) .. " settings applied") or result, ok and "folder" or "error")
			end,
		})
	end
	ConfigShare:AddInput({
		Title = "Paste config",
		Placeholder = "Paste the exported text, then press Import",
		Callback = function(text)
			pasted = text
		end,
	})
	ConfigShare:AddButton({
		Title = "Import pasted config",
		Icon = "folder",
		Callback = function()
			local ok, result = importConfig(pasted)
			notify(ok and "Config imported" or "Import failed", ok and (tostring(result) .. " settings applied") or result, ok and "folder" or "error")
		end,
	})
end
MD3.LYConfigShare()

