	local dictionaries = { ["English"] = false, ["繁體中文"] = ZH }
	local current = "English"
	local originals = setmetatable({}, { __mode = "k" }) -- object -> { text, shown, placeholder, shownPlaceholder }
	local hooked = setmetatable({}, { __mode = "k" })    -- object -> connection
	local sweepToken = 0

	local function lookup(dict, text)
		if type(text) ~= "string" or text == "" then
			return nil
		end
		local key = string.lower((string.gsub(string.gsub(text, "^%s+", ""), "%s+$", "")))
		return dict[key]
	end

	local function isTextObject(inst)
		return inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox")
	end

	-- Bring one object in line with the current language.
	local function sync(inst)
		local dict = dictionaries[current]
		local rec = originals[inst]
		if not rec then
			rec = {}
			originals[inst] = rec
		end
		if not inst:IsA("TextBox") then
			local now = inst.Text
			if rec.shown == nil or now ~= rec.shown then
				rec.text = now -- new original (first sight, or the script changed it)
			end
			local shown = dict and lookup(dict, rec.text) or rec.text
			-- Remember what we show BEFORE writing it: with immediate signals the change
			-- handler runs inside the assignment and must see it is our own text, or it
			-- would take the translation for the new original.
			rec.shown = shown
			if inst.Text ~= shown then
				inst.Text = shown
			end
		else
			local now = inst.PlaceholderText
			if rec.shownPlaceholder == nil or now ~= rec.shownPlaceholder then
				rec.placeholder = now
			end
			local shown = dict and lookup(dict, rec.placeholder) or rec.placeholder
			rec.shownPlaceholder = shown
			if inst.PlaceholderText ~= shown then
				inst.PlaceholderText = shown
			end
		end
	end

	local function hook(inst)
		if hooked[inst] or not isTextObject(inst) then
			return
		end
		local property = inst:IsA("TextBox") and "PlaceholderText" or "Text"
		hooked[inst] = inst:GetPropertyChangedSignal(property):Connect(function()
			if current ~= "English" then
				pcall(sync, inst)
			end
		end)
		pcall(sync, inst)
	end

	local function sweep()
		sweepToken += 1
		local token = sweepToken
		local root = Window.Gui
		if not root then
			return
		end
		task.spawn(function()
			local count = 0
			for _, inst in ipairs(root:GetDescendants()) do
				if token ~= sweepToken then
					return
				end
				if isTextObject(inst) then
					if current == "English" then
						local rec = originals[inst]
						if rec then
							pcall(function()
								if inst:IsA("TextBox") then
									if rec.placeholder ~= nil then inst.PlaceholderText = rec.placeholder end
								elseif rec.text ~= nil then
									inst.Text = rec.text
								end
							end)
						end
						local conn = hooked[inst]
						if conn then
							conn:Disconnect()
							hooked[inst] = nil
						end
						originals[inst] = nil
					else
						hook(inst)
					end
				end
				count += 1
				if count % 250 == 0 then
					task.wait() -- spread the work over frames, no hitch
				end
			end
		end)
	end

	local function setLanguage(name)
		if not dictionaries[name] and name ~= "English" then
			name = "English"
		end
		if name == current then
			return
		end
		current = name
		sweep()
	end

	if Window.Gui then
		track(Window.Gui.DescendantAdded:Connect(function(inst)
			if current ~= "English" and isTextObject(inst) then
				task.defer(hook, inst)
			end
		end))
	end

	local LanguageSection = SettingsTab:AddSection("Language")
	LanguageSection:AddDropdown({
		Title = "Language",
		Options = { "English", "繁體中文" },
		Default = "English",
		Flag = "Language",
		Callback = function(value)
			setLanguage(value or "English")
		end,
	})
end
MD3.LYLanguage()

Window.OnUnload:Connect(function()
	for index = #cleanup, 1, -1 do
		local item = cleanup[index]
		pcall(function()
			if type(item) == "function" then
				item()
			elseif typeof(item) == "Instance" then
				item:Destroy()
			else
				item:Disconnect()
			end
		end)
	end
	table.clear(cleanup)
	if restoreLighting then
		restoreLighting()
	end
	if restoreTextures then
		restoreTextures()
	end
end)

-- Must run after every flagged element exists.
Window:LoadAutoloadConfig()

--== Lin67 skin, part 2/2: palette ==--
-- Vape V4's colors as theme roles, merged into whatever the config pinned:
-- roles the player already customized are left alone, the rest get the flat
-- opaque Vape look (surfaces are a solid slab, not glass), and the accent-
-- tinted roles follow the seed so the color picker keeps driving the UI.
local function applyLin67Palette()
	local theme = Window.Theme
	if not theme then
		return
	end

	local SHELL = Color3.fromHex("#1A191A") -- the panel itself
	local BAND = Color3.fromHex("#141414") -- the HUD's dark ground
	local ROW = Color3.fromHex("#201F20") -- inputs, hover rows
	local CHIP = Color3.fromHex("#2D2C2D") -- chips, toasts
	local TEXT = Color3.fromHex("#EDEDED") -- primary text
	local MUTED = Color3.fromHex("#A3A3A3") -- Vape's idle row gray
	local ICON = Color3.fromHex("#A2A2A2") -- idle icons

	local skinColors = {
		Background = SHELL,
		Surface = SHELL,
		SurfaceContainerLow = SHELL, -- pages melt into the shell: one flat panel
		SurfaceContainerHigh = ROW,
		SurfaceContainerHighest = CHIP,
		OnSurface = TEXT,
		OnBackground = TEXT,
		OnSurfaceVariant = MUTED,
		Outline = Color3.fromHex("#3A3A3A"),
		OutlineVariant = Color3.fromHex("#2E2E2E"), -- the shell's hairline
		OnPrimary = Color3.fromHex("#071B15"), -- dark on the mint fills
		OnSecondaryContainer = TEXT, -- active rail label stays light
		Icon = ICON,
		HUDBackground = BAND,
		HUDText = MUTED,
	}
	local skinTransparency = {
		-- opaque everywhere: no glass alphas left in the Vape skin
		Background = 0,
		Surface = 0,
		SurfaceContainerLow = 0,
		SurfaceContainerHigh = 0,
		SurfaceContainerHighest = 0,
		SecondaryContainer = 0.70, -- the seed tint on active chips (sub-tabs)
	}
	local skinFollow = {
		-- --primary is the picker's color; the tinted roles follow it, the
		-- same links MD3's own presets use. Seed is the mint ThemeColor, so
		-- the active rail icon, badge and switches come out Vape mint.
		Primary = "Seed",
		SecondaryContainer = "Seed",
		IconAccent = "Primary",
		IconSelected = "Primary",
	}

	local colors = theme:GetOverrides()
	local transparencies = theme:GetTransparencies()
	local follow = theme:GetFollow()
	for role, color in skinColors do
		if colors[role] == nil then
			colors[role] = color
		end
	end
	for role, value in skinTransparency do
		if transparencies[role] == nil then
			transparencies[role] = value
		end
	end
	for role, source in skinFollow do
		if follow[role] == nil then
			follow[role] = source
		end
	end
	theme:SetOverrides(colors, transparencies, follow)
end
do
	local ok, err = pcall(applyLin67Palette)
	if not ok then
		warn("[Lin67] palette skin failed: " .. tostring(err))
	else
		print("[Lin67] V2: palette applied")
	end
end

if not silentStart then
Window:Notify({
	Title = "Lin67 Hub loaded",
	Content = "Press RightShift to hide / show.",
	Icon = "check_circle",
})
end
